fn gui_profile_route_cleanup_command() -> String {
    let safety = platform_safety_script();
    format!(
        "set -eu; rm -f {complete}; test ! -e {complete}; {safety}",
        complete = sh(GUI_PROFILE_REMOTE_COMPLETE),
        safety = safety,
    )
}

fn wait_gui_profile_snapshot(
    config: &NativeDeviceConfig,
    nonce: &str,
    predicate: impl Fn(&Value) -> bool,
    label: &str,
) -> Result<Value> {
    wait_gui_profile_snapshot_with_timeout(config, nonce, predicate, label, Duration::from_secs(10))
}

fn wait_gui_profile_snapshot_with_timeout(
    config: &NativeDeviceConfig,
    nonce: &str,
    predicate: impl Fn(&Value) -> bool,
    label: &str,
    timeout: Duration,
) -> Result<Value> {
    let started = Instant::now();
    loop {
        let snapshot = launcher_automation::snapshot(config, nonce)?;
        if predicate(&snapshot) {
            return Ok(snapshot);
        }
        if started.elapsed() >= timeout {
            return Err(format!(
                "GUI profiling route timed out waiting for {label}; final snapshot={snapshot}"
            )
            .into());
        }
        thread::sleep(Duration::from_millis(20));
    }
}

fn wait_gui_profile_pprof_finalization(
    config: &NativeDeviceConfig,
    session: &Session,
    nonce: &str,
    remote_path: &str,
    minimum_probe: Duration,
) -> Result<String> {
    let started = Instant::now();
    let timeout = Duration::from_secs(30);
    let mut completion = None;
    let mut next_keepalive = Instant::now();
    loop {
        if completion.is_none() {
            completion = remote_read(session, remote_path);
        }
        if started.elapsed() >= minimum_probe
            && let Some(completion) = completion
        {
            return Ok(completion);
        }
        if started.elapsed() >= timeout {
            return Err("timed out waiting for Arcade velocity-scroll pprof finalization".into());
        }
        if Instant::now() >= next_keepalive {
            launcher_automation::snapshot(config, nonce)
                .map_err(|error| format!("keep Arcade pprof automation session alive: {error}"))?;
            next_keepalive = Instant::now() + Duration::from_secs(1);
        }
        thread::sleep(Duration::from_millis(20));
    }
}

fn gui_profile_effective_view(snapshot: &Value) -> Option<&str> {
    snapshot
        .pointer("/semantic/effective_view")
        .and_then(Value::as_str)
}

fn settled_composition_frame_metrics(frame: &Value) -> Value {
    json!({
        "frame": frame["frame"],
        "phase": frame["phase"],
        "logical_change_class": frame["logical_change_class"],
        "composition": frame["composition"],
        "slint_raster": frame["slint_raster"],
        "slint_damage_rects": frame["slint_damage_rects"],
        "slint_render_us": frame["slint_render_us"],
        "redraw_pending": frame["redraw_pending"],
        "custom_draw_us": frame["custom_draw_us"],
        "copied_bytes": frame.pointer("/latch/copied_bytes").cloned().unwrap_or(Value::Null),
        "copied_rectangles": frame.pointer("/latch/copied_rectangles").cloned().unwrap_or(Value::Null),
        "copy_path": frame.pointer("/latch/copy_path").cloned().unwrap_or(Value::Null),
        "catchup_bytes": frame.pointer("/latch/catchup_bytes").cloned().unwrap_or(Value::Null),
        "invalid_bytes": frame.pointer("/latch/invalid_bytes").cloned().unwrap_or(Value::Null),
        "presentation": frame["presentation"],
    })
}

fn settled_full_raster_recovery_windows(frames: &[Value]) -> Vec<Value> {
    let mut forced: Option<&Value> = None;
    let mut windows = Vec::new();
    for frame in frames {
        match frame.get("slint_raster").and_then(Value::as_str) {
            Some("forced-full")
                if frame
                    .get("slint_render_us")
                    .and_then(Value::as_u64)
                    .is_some() =>
            {
                forced = Some(frame);
            }
            Some("ordinary")
                if forced.is_some()
                    && frame.get("redraw_pending").and_then(Value::as_bool) == Some(true)
                    && frame
                        .get("slint_render_us")
                        .and_then(Value::as_u64)
                        .is_some() =>
            {
                let forced_frame = forced.take().expect("checked above");
                let forced_raster_us = forced_frame["slint_render_us"].as_u64().unwrap_or(0);
                let recovery_raster_us = frame["slint_render_us"].as_u64().unwrap_or(0);
                let forced_sequence = forced_frame["frame"].as_u64().unwrap_or(0);
                let recovery_sequence = frame["frame"].as_u64().unwrap_or(0);
                let recovery_full_screen_damage = frame
                    .get("slint_damage_rects")
                    .and_then(Value::as_array)
                    .is_some_and(|rects| {
                        rects.iter().any(|rect| rect == &json!([0, 0, 1280, 720]))
                    });
                windows.push(json!({
                    "forced": settled_composition_frame_metrics(forced_frame),
                    "recovery": settled_composition_frame_metrics(frame),
                    "frame_gap": recovery_sequence.saturating_sub(forced_sequence),
                    "forced_raster_us": forced_raster_us,
                    "recovery_raster_us": recovery_raster_us,
                    "combined_raster_us": forced_raster_us.saturating_add(recovery_raster_us),
                    "recovery_full_screen_damage": recovery_full_screen_damage,
                }));
            }
            _ => {}
        }
    }
    windows
}

fn settled_modal_receipt_convergence_copy(frame: &Value) -> bool {
    let copied_bytes = frame
        .pointer("/latch/copied_bytes")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    copied_bytes > 0
        && frame.pointer("/latch/copy_path").and_then(Value::as_str) == Some("identity-full")
        && frame
            .pointer("/latch/catchup_bytes")
            .and_then(Value::as_u64)
            == Some(copied_bytes)
        && frame
            .pointer("/latch/invalid_bytes")
            .and_then(Value::as_u64)
            == Some(copied_bytes)
        && frame
            .get("slint_damage_rects")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
        && frame
            .pointer("/composition/force_full_present")
            .and_then(Value::as_bool)
            == Some(false)
}

fn summarize_settled_composition_profile(profile: &Value) -> Result<Value> {
    if profile.get("schema").and_then(Value::as_str) != Some("mister-magik-gui-profiling-window-v1")
        || profile.get("state").and_then(Value::as_str) != Some("complete")
        || profile.get("dropped_frame_records").and_then(Value::as_u64) != Some(0)
    {
        return Err("settled composition route did not produce a complete frame profile".into());
    }
    let frames = profile
        .get("frames")
        .and_then(Value::as_array)
        .ok_or("settled composition profile has no frames")?;
    let settled_modal = frames
        .iter()
        .filter(|frame| {
            frame.get("phase").and_then(Value::as_str) == Some("modal-over-arcade")
                && frame.pointer("/composition/state").and_then(Value::as_str)
                    == Some("modal-over-arcade")
                && frame
                    .pointer("/composition/retirement_state")
                    .and_then(Value::as_str)
                    == Some("idle")
                && frame
                    .pointer("/composition/retirement_receipt")
                    .and_then(Value::as_str)
                    .is_some_and(|receipt| !receipt.is_empty())
        })
        .collect::<Vec<_>>();
    if settled_modal.len() < 8 {
        return Err(format!(
            "settled composition profile has only {} retirement-confirmed modal frames",
            settled_modal.len()
        )
        .into());
    }
    let destination = frames
        .iter()
        .find(|frame| {
            frame.get("phase").and_then(Value::as_str) == Some("settings-destination")
                && frame.pointer("/composition/state").and_then(Value::as_str)
                    == Some("navigation-destination")
                && frame.get("slint_raster").and_then(Value::as_str) == Some("forced-full")
        })
        .ok_or("settled composition profile omitted the forced Settings destination frame")?;
    let following = frames
        .iter()
        .find(|frame| frame.get("phase").and_then(Value::as_str) == Some("settings-following"))
        .ok_or("settled composition profile omitted the following Settings frame")?;
    let cache_recovery = frames
        .iter()
        .find(|frame| {
            frame.get("phase").and_then(Value::as_str) == Some("settings-cache-recovery")
                && frame.pointer("/composition/state").and_then(Value::as_str) == Some("full-slint")
                && frame.get("slint_raster").and_then(Value::as_str) == Some("ordinary")
                && frame.get("redraw_pending").and_then(Value::as_bool) == Some(true)
        })
        .ok_or(
            "settled composition profile omitted the first real Settings cache-recovery raster",
        )?;
    let destination_frame = destination["frame"]
        .as_u64()
        .ok_or("Settings destination frame has no sequence")?;
    let following_frame = following["frame"]
        .as_u64()
        .ok_or("following Settings frame has no sequence")?;
    if following_frame != destination_frame.saturating_add(1) {
        return Err(format!(
            "Settings following frame is not immediate: destination={destination_frame} following={following_frame}"
        )
        .into());
    }
    let sum = |field: &str, selected: &[&Value]| -> u64 {
        selected
            .iter()
            .filter_map(|frame| frame.get(field).and_then(Value::as_u64))
            .sum()
    };
    let convergence_frame_count = settled_modal
        .iter()
        .take_while(|frame| settled_modal_receipt_convergence_copy(frame))
        .count();
    let steady_modal = &settled_modal[convergence_frame_count..];
    let modal_full_presents = steady_modal
        .iter()
        .filter(|frame| {
            frame
                .pointer("/composition/full_frame_present")
                .and_then(Value::as_bool)
                == Some(true)
        })
        .count();
    let modal_copy_bytes = steady_modal
        .iter()
        .filter_map(|frame| frame.pointer("/latch/copied_bytes").and_then(Value::as_u64))
        .sum::<u64>();
    let retirement_confirmed_copy_bytes = settled_modal
        .iter()
        .filter_map(|frame| frame.pointer("/latch/copied_bytes").and_then(Value::as_u64))
        .sum::<u64>();
    let convergence_copy_bytes = settled_modal[..convergence_frame_count]
        .iter()
        .filter_map(|frame| frame.pointer("/latch/copied_bytes").and_then(Value::as_u64))
        .sum::<u64>();
    let recovery_windows = settled_full_raster_recovery_windows(frames);
    if recovery_windows.is_empty() {
        return Err("settled composition profile has no forced-full cache-recovery window".into());
    }
    let recovery_sum = |field: &str| {
        recovery_windows
            .iter()
            .filter_map(|window| window.get(field).and_then(Value::as_u64))
            .sum::<u64>()
    };
    Ok(json!({
        "modal_over_arcade": {
            "retirement_confirmed_frames": settled_modal.len(),
            "retirement_confirmed_copy_bytes": retirement_confirmed_copy_bytes,
            "receipt_convergence_frames": convergence_frame_count,
            "receipt_convergence_copy_bytes": convergence_copy_bytes,
            "steady_frames": steady_modal.len(),
            "steady_full_presents": modal_full_presents,
            "steady_slint_raster_us": sum("slint_render_us", steady_modal),
            "steady_custom_draw_us": sum("custom_draw_us", steady_modal),
            "steady_copy_bytes": modal_copy_bytes,
            "frames": settled_modal.into_iter().map(settled_composition_frame_metrics).collect::<Vec<_>>(),
        },
        "home_to_settings": {
            "destination": settled_composition_frame_metrics(destination),
            "following": settled_composition_frame_metrics(following),
            "cache_recovery": settled_composition_frame_metrics(cache_recovery),
            "two_frame_raster_us": destination["slint_render_us"].as_u64().unwrap_or(0)
                .saturating_add(following["slint_render_us"].as_u64().unwrap_or(0)),
            "destination_to_recovery_raster_us": destination["slint_render_us"].as_u64().unwrap_or(0)
                .saturating_add(following["slint_render_us"].as_u64().unwrap_or(0))
                .saturating_add(cache_recovery["slint_render_us"].as_u64().unwrap_or(0)),
            "two_frame_copy_bytes": destination.pointer("/latch/copied_bytes").and_then(Value::as_u64).unwrap_or(0)
                .saturating_add(following.pointer("/latch/copied_bytes").and_then(Value::as_u64).unwrap_or(0)),
        },
        "full_raster_recovery": {
            "window_count": recovery_windows.len(),
            "forced_raster_us": recovery_sum("forced_raster_us"),
            "recovery_raster_us": recovery_sum("recovery_raster_us"),
            "combined_raster_us": recovery_sum("combined_raster_us"),
            "duplicate_full_raster_count": recovery_windows.iter()
                .filter(|window| window.get("recovery_full_screen_damage").and_then(Value::as_bool) == Some(true))
                .count(),
            "windows": recovery_windows,
        },
        "presentation": gui_presentation_summary(profile)?,
    }))
}

fn summarize_bridge_model_churn_profile(profile: &Value) -> Result<Value> {
    if profile.get("state").and_then(Value::as_str) != Some("complete") {
        return Err(format!("bridge model churn profile did not complete: {profile}").into());
    }
    let frames = profile
        .get("frames")
        .and_then(Value::as_array)
        .ok_or("bridge model churn profile has no frames")?;
    let phase_metrics = |phase: &str, updates: u64| {
        let selected = frames
            .iter()
            .filter(|frame| frame.get("phase").and_then(Value::as_str) == Some(phase))
            .collect::<Vec<_>>();
        let sum = |key: &str| {
            selected
                .iter()
                .filter_map(|frame| frame.get(key).and_then(Value::as_u64))
                .sum::<u64>()
        };
        let bridge_us = sum("bridge_sync_us");
        let raster_us = sum("slint_render_us");
        json!({
            "updates": updates,
            "frames": selected.len(),
            "bridge_us": bridge_us,
            "raster_us": raster_us,
            "bridge_plus_raster_us": bridge_us.saturating_add(raster_us),
            "bridge_plus_raster_us_per_update": bridge_us.saturating_add(raster_us) as f64 / updates as f64,
            "model_replacements": sum("bridge_model_replacements"),
            "row_mutations": sum("bridge_row_mutations"),
            "row_allocations": sum("bridge_row_allocations"),
            "shared_string_constructions": sum("bridge_shared_string_constructions"),
            "model_allocation_us": sum("bridge_model_allocation_us"),
            "full_damage_frames": selected.iter().filter(|frame| {
                frame.get("slint_damage_rects").and_then(Value::as_array).is_some_and(|rects| {
                    rects.iter().any(|rect| rect.as_array().is_some_and(|values| {
                        values.get(2).and_then(Value::as_u64) == Some(1280)
                            && values.get(3).and_then(Value::as_u64) == Some(720)
                    }))
                })
            }).count(),
            "copied_bytes": selected.iter().filter_map(|frame| frame.pointer("/latch/copied_bytes").and_then(Value::as_u64)).sum::<u64>(),
        })
    };
    let playback = profile
        .get("bridge_churn")
        .filter(|value| !value.is_null())
        .ok_or("bridge model churn profile has no playback summary")?;
    if playback
        .pointer("/media_terminal/summary")
        .and_then(Value::as_str)
        != Some("screenshots 0 active · 2/3 done · 1 failed")
        || playback
            .pointer("/media_terminal/rows")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(3)
    {
        return Err("bridge model churn media terminal contents are invalid".into());
    }
    if playback
        .pointer("/media_bridge_terminal/summary")
        .and_then(Value::as_str)
        != Some("screenshots 0 active · 2/3 done · 1 failed")
        || playback
            .pointer("/media_bridge_terminal/rows")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(3)
    {
        return Err("bridge model churn published media terminal contents are invalid".into());
    }
    if playback
        .pointer("/menu_terminal/rows")
        .and_then(Value::as_u64)
        != Some(128)
        || playback
            .pointer("/menu_terminal/selected_rows/0")
            .and_then(Value::as_u64)
            != Some(63)
        || playback
            .pointer("/menu_terminal/selected_rows")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(1)
        || playback
            .pointer("/menu_terminal/acknowledged_rows")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(0)
    {
        return Err("bridge model churn menu terminal contents are invalid".into());
    }
    if playback
        .pointer("/terminal/media_rows")
        .and_then(Value::as_u64)
        != Some(0)
        || playback
            .pointer("/terminal/media_summary")
            .and_then(Value::as_str)
            != Some("")
        || playback
            .pointer("/terminal/menu_restored")
            .and_then(Value::as_bool)
            != Some(true)
    {
        return Err("bridge model churn did not restore production bridge contents".into());
    }
    Ok(json!({
        "media_progress": phase_metrics("media-progress", 60),
        "menu_selection": phase_metrics("menu-selection", 64),
        "light_bridge": phase_metrics("light-bridge", 64),
        "playback": playback,
        "presentation": gui_presentation_summary(profile)?,
    }))
}

fn run_bridge_model_churn_route(
    config: &NativeDeviceConfig,
    session: &Session,
    output_dir: &Path,
) -> Result<Value> {
    fs::create_dir_all(output_dir)?;
    exec_checked(
        session,
        "prepare bridge model churn route",
        &gui_profile_route_cleanup_command(),
    )?;
    restart_launcher_with_one_shot_env(
        session,
        LauncherRestartOptions {
            env_vars: bridge_model_churn_launcher_env(),
            timeout_secs: 45,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            ..LauncherRestartOptions::default()
        },
    )?;
    let status = read_launcher_status(session)?;
    let main_status: Value = serde_json::from_str(
        &remote_read(session, MAIN_STATUS_REMOTE).ok_or("Main status is missing")?,
    )?;
    let begin = launcher_automation::begin(
        config,
        status
            .pointer("/build/version")
            .and_then(Value::as_str)
            .ok_or("bridge model churn status has no build version")?,
        status
            .pointer("/build/source_revision")
            .and_then(Value::as_str)
            .ok_or("bridge model churn status has no source revision")?,
        main_status
            .get("main_generation")
            .and_then(Value::as_u64)
            .ok_or("bridge model churn Main status has no generation")?,
        45,
    )?;
    let begin: Value = serde_json::from_str(&begin)?;
    let nonce = begin["nonce"]
        .as_str()
        .ok_or("bridge model churn automation has no nonce")?
        .to_owned();
    let route_result = (|| -> Result<Value> {
        let initial = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("home")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
            },
            "bridge model churn initial Home",
        )?;
        let start = modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::Y))?;
        wait_for_gui_profile_file(
            config,
            session,
            &nonce,
            GUI_PROFILE_REMOTE_COMPLETE,
            Duration::from_secs(15),
            "bridge model churn completion",
        )?;
        let profile_path = output_dir.join("profile.json");
        get(session, GUI_PROFILE_REMOTE_COMPLETE, &profile_path)?;
        let profile: Value = serde_json::from_str(&fs::read_to_string(&profile_path)?)?;
        let metrics = summarize_bridge_model_churn_profile(&profile)?;
        let terminal = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("home")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
            },
            "bridge model churn restored Home",
        )?;
        let initial_semantic = initial.get("semantic").cloned().unwrap_or(Value::Null);
        let terminal_semantic = terminal.get("semantic").cloned().unwrap_or(Value::Null);
        if initial_semantic != terminal_semantic {
            return Err(format!(
                "bridge model churn semantic state was not restored: initial={initial_semantic}; terminal={terminal_semantic}"
            )
            .into());
        }
        let terminal_home: Value = serde_json::from_str(&launcher_automation::capture_checkpoint(
            config,
            &nonce,
            start,
            "terminal-home",
            output_dir,
        )?)?;
        Ok(json!({
            "schema": "mister-magik-bridge-model-churn-route-v1",
            "actions": { "start": start },
            "initial": initial,
            "terminal": terminal,
            "terminal_home": terminal_home,
            "profile": profile,
            "metrics": metrics,
        }))
    })();
    let end_result = launcher_automation::end(config, &nonce).map(|_| ());
    match (route_result, end_result) {
        (Ok(route), Ok(())) => Ok(route),
        (Err(route), Ok(())) => Err(route),
        (Ok(_), Err(end)) => Err(format!("bridge model churn cleanup failed: {end}").into()),
        (Err(route), Err(end)) => {
            Err(format!("{route}; bridge model churn cleanup failed: {end}").into())
        }
    }
}

fn run_settled_composition_route(
    config: &NativeDeviceConfig,
    session: &Session,
    output_dir: &Path,
) -> Result<Value> {
    fs::create_dir_all(output_dir)?;
    exec_checked(
        session,
        "prepare settled composition route",
        &gui_profile_route_cleanup_command(),
    )?;
    restart_launcher_with_one_shot_env(
        session,
        LauncherRestartOptions {
            env_vars: settled_composition_launcher_env(),
            timeout_secs: 45,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            ..LauncherRestartOptions::default()
        },
    )?;
    let status = read_launcher_status(session)?;
    let main_status: Value = serde_json::from_str(
        &remote_read(session, MAIN_STATUS_REMOTE).ok_or("Main status is missing")?,
    )?;
    let begin = launcher_automation::begin(
        config,
        status
            .pointer("/build/version")
            .and_then(Value::as_str)
            .ok_or("settled composition status has no build version")?,
        status
            .pointer("/build/source_revision")
            .and_then(Value::as_str)
            .ok_or("settled composition status has no source revision")?,
        main_status
            .get("main_generation")
            .and_then(Value::as_u64)
            .ok_or("settled composition Main status has no generation")?,
        45,
    )?;
    let begin: Value = serde_json::from_str(&begin)?;
    let nonce = begin["nonce"]
        .as_str()
        .ok_or("settled composition automation has no nonce")?
        .to_owned();
    let route_result = (|| -> Result<Value> {
        let initial = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("home")
                    && snapshot
                        .pointer("/semantic/selected_item_id")
                        .and_then(Value::as_str)
                        == Some("menu:arcade")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
            },
            "settled composition initial Home",
        )?;
        let enter_arcade =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::A))?;
        let arcade = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("arcade")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
            },
            "settled Arcade before favorite dialog",
        )?;
        let open_drawer = modal_input_action(
            config,
            &nonce,
            AutomationAction::Tap(AutomationButton::Left),
        )?;
        let drawer_open = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("arcade")
                    && snapshot
                        .pointer("/semantic/drawer_open")
                        .and_then(Value::as_bool)
                        == Some(true)
            },
            "Arcade filter drawer open",
        )?;
        thread::sleep(Duration::from_millis(250));
        let drawer_to_top =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::B))?;
        let drawer_top = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("arcade")
                    && snapshot
                        .pointer("/semantic/drawer_open")
                        .and_then(Value::as_bool)
                        == Some(true)
                    && snapshot
                        .pointer("/semantic/drawer_level")
                        .and_then(Value::as_str)
                        == Some("Filters")
            },
            "Arcade filter drawer top level",
        )?;
        let close_drawer =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::A))?;
        let drawer_closed = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("arcade")
                    && snapshot
                        .pointer("/semantic/drawer_open")
                        .and_then(Value::as_bool)
                        == Some(false)
            },
            "Arcade filter drawer closed",
        )?;
        let open_modal =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::X))?;
        let modal = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                snapshot
                    .pointer("/semantic/dialog_message")
                    .and_then(Value::as_str)
                    .is_some_and(|message| message.contains("Favorite"))
                    && snapshot
                        .pointer("/semantic/composition_state")
                        .and_then(Value::as_str)
                        == Some("modal-over-arcade")
            },
            "favorite confirmation over Arcade",
        )?;
        let modal_hold_started = Instant::now();
        let mut modal_hold = Vec::new();
        while modal_hold_started.elapsed() < Duration::from_millis(750) {
            modal_hold.push(launcher_automation::snapshot(config, &nonce)?);
            thread::sleep(Duration::from_millis(50));
        }
        let cancel_modal =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::B))?;
        let return_home = modal_input_action(
            config,
            &nonce,
            AutomationAction::Tap(AutomationButton::Home),
        )?;
        let home = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("home")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
            },
            "Home before Settings destination",
        )?;
        let select_settings =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::Up))?;
        // Landscape Home represents Settings as a separate focus target, not
        // a root-menu item. selected_item_id therefore remains the underlying
        // Arcade tile; the presented Up receipt is the exact focus handoff.
        let settings_selected = launcher_automation::snapshot(config, &nonce)?;
        let enter_settings =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::A))?;
        let settings = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("settings")
                    && snapshot
                        .get("presented_action_sequence")
                        .and_then(Value::as_u64)
                        .is_some_and(|presented| presented >= enter_settings)
            },
            "physically presented Settings destination",
        )?;
        wait_for_gui_profile_file(
            config,
            session,
            &nonce,
            GUI_PROFILE_REMOTE_COMPLETE,
            Duration::from_secs(10),
            "settled composition completion",
        )?;
        let profile_path = output_dir.join("profile.json");
        get(session, GUI_PROFILE_REMOTE_COMPLETE, &profile_path)?;
        let profile: Value = serde_json::from_str(&fs::read_to_string(&profile_path)?)?;
        let metrics = summarize_settled_composition_profile(&profile)?;
        let terminal_settings: Value =
            serde_json::from_str(&launcher_automation::capture_checkpoint(
                config,
                &nonce,
                enter_settings,
                "terminal-settings",
                output_dir,
            )?)?;

        let leave_settings =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::B))?;
        let home_after = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| gui_profile_effective_view(snapshot) == Some("home"),
            "Home restoration after Settings",
        )?;
        let restore_arcade_selection = modal_input_action(
            config,
            &nonce,
            AutomationAction::Tap(AutomationButton::Down),
        )?;
        let restored = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("home")
                    && snapshot
                        .pointer("/semantic/selected_item_id")
                        .and_then(Value::as_str)
                        == Some("menu:arcade")
                    && snapshot
                        .pointer("/semantic/dialog_message")
                        .and_then(Value::as_str)
                        .is_none_or(str::is_empty)
            },
            "exact initial Home navigation state",
        )?;
        Ok(json!({
            "schema": "mister-magik-settled-composition-route-v1",
            "actions": {
                "enter_arcade": enter_arcade,
                "open_drawer": open_drawer,
                "drawer_to_top": drawer_to_top,
                "close_drawer": close_drawer,
                "open_modal": open_modal,
                "cancel_modal": cancel_modal,
                "return_home": return_home,
                "select_settings": select_settings,
                "enter_settings": enter_settings,
                "leave_settings": leave_settings,
                "restore_arcade_selection": restore_arcade_selection,
            },
            "initial": initial,
            "arcade": arcade,
            "drawer_open": drawer_open,
            "drawer_top": drawer_top,
            "drawer_closed": drawer_closed,
            "modal": modal,
            "modal_hold": modal_hold,
            "home": home,
            "settings_selected": settings_selected,
            "settings": settings,
            "terminal_settings": terminal_settings,
            "home_after": home_after,
            "restored": restored,
            "profile": profile,
            "metrics": metrics,
        }))
    })();
    let end_result = launcher_automation::end(config, &nonce).map(|_| ());
    match (route_result, end_result) {
        (Ok(route), Ok(())) => Ok(route),
        (Err(route), Ok(())) => Err(route),
        (Ok(_), Err(end)) => Err(format!("settled composition cleanup failed: {end}").into()),
        (Err(route), Err(end)) => {
            Err(format!("{route}; settled composition cleanup failed: {end}").into())
        }
    }
}

fn run_gui_frame_profile_route(
    config: &NativeDeviceConfig,
    session: &Session,
    output_dir: &Path,
    pmu: bool,
    scroll_duration_ms: u64,
    terminal_checkpoint: Option<&str>,
    startup_orientation: Option<&str>,
) -> Result<Value> {
    run_gui_frame_profile_route_with_pprof(
        config,
        session,
        output_dir,
        GuiFrameProfileRouteSpec {
            pmu,
            scroll_duration_ms,
            terminal_checkpoint,
            pprof_remote_dir: None,
            pprof_finalization_probe: Duration::ZERO,
            input_mode: ArcadeRunInputMode::Held,
            startup_orientation,
            preview_work_attribution: false,
        },
    )
}

fn run_gui_frame_profile_route_turbo(
    config: &NativeDeviceConfig,
    session: &Session,
    output_dir: &Path,
    scroll_duration_ms: u64,
    terminal_checkpoint: Option<&str>,
    startup_orientation: Option<&str>,
) -> Result<Value> {
    run_gui_frame_profile_route_with_pprof(
        config,
        session,
        output_dir,
        GuiFrameProfileRouteSpec {
            pmu: false,
            scroll_duration_ms,
            terminal_checkpoint,
            pprof_remote_dir: None,
            pprof_finalization_probe: Duration::ZERO,
            input_mode: ArcadeRunInputMode::Turbo,
            startup_orientation,
            preview_work_attribution: false,
        },
    )
}

struct GuiFrameProfileRouteSpec<'a> {
    pmu: bool,
    scroll_duration_ms: u64,
    terminal_checkpoint: Option<&'a str>,
    pprof_remote_dir: Option<&'a str>,
    pprof_finalization_probe: Duration,
    input_mode: ArcadeRunInputMode,
    startup_orientation: Option<&'a str>,
    preview_work_attribution: bool,
}

fn run_gui_frame_profile_route_with_pprof(
    config: &NativeDeviceConfig,
    session: &Session,
    output_dir: &Path,
    spec: GuiFrameProfileRouteSpec<'_>,
) -> Result<Value> {
    let GuiFrameProfileRouteSpec {
        pmu,
        scroll_duration_ms,
        terminal_checkpoint,
        pprof_remote_dir,
        pprof_finalization_probe,
        input_mode,
        startup_orientation,
        preview_work_attribution,
    } = spec;
    fs::create_dir_all(output_dir)?;
    exec_checked(
        session,
        "prepare fixed GUI profiling route",
        &gui_profile_route_cleanup_command(),
    )?;
    let mut env_vars = gui_profile_route_launcher_env_with_pprof(
        pmu,
        pprof_remote_dir,
        scroll_duration_ms,
        startup_orientation,
    );
    if preview_work_attribution {
        env_vars.push(("MISTER_PREVIEW_TRACE".into(), "1".into()));
    }
    restart_launcher_with_one_shot_env(
        session,
        LauncherRestartOptions {
            env_vars,
            timeout_secs: 45,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            ..LauncherRestartOptions::default()
        },
    )?;
    let status_before = read_launcher_status(session)?;
    let main_status: Value = serde_json::from_str(
        &remote_read(session, MAIN_STATUS_REMOTE).ok_or("Main status is missing")?,
    )?;
    let build_version = status_before
        .pointer("/build/version")
        .and_then(Value::as_str)
        .ok_or("GUI profiling launcher status has no build version")?;
    let source_revision = status_before
        .pointer("/build/source_revision")
        .and_then(Value::as_str)
        .ok_or("GUI profiling launcher status has no source revision")?;
    let main_generation = main_status
        .get("main_generation")
        .and_then(Value::as_u64)
        .ok_or("GUI profiling Main status has no generation")?;
    let begin = launcher_automation::begin(
        config,
        build_version,
        source_revision,
        main_generation,
        gui_profile_automation_ttl_secs(scroll_duration_ms),
    )?;
    let begin: Value = serde_json::from_str(&begin)?;
    let nonce = begin
        .get("nonce")
        .and_then(Value::as_str)
        .ok_or("GUI profiling automation has no nonce")?
        .to_string();

    let run_result = (|| -> Result<Value> {
        let home_ready = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("home")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
                    && snapshot
                        .pointer("/semantic/selected_item_id")
                        .and_then(Value::as_str)
                        == Some("menu:arcade")
            },
            "settled Home with Arcade selected",
        )?;
        let arcade_enter_sequence =
            modal_input_action(config, &nonce, AutomationAction::Tap(AutomationButton::A))?;
        let arcade_entered = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("arcade")
                    && snapshot
                        .pointer("/semantic/navigation_transition_active")
                        .and_then(Value::as_bool)
                        == Some(false)
                    && matches!(
                        snapshot
                            .pointer("/semantic/preview_state")
                            .and_then(Value::as_str),
                        Some("exact" | "cached" | "empty")
                    )
            },
            "settled Arcade entry",
        )?;
        let turbo_prime_sequence = if input_mode == ArcadeRunInputMode::Turbo {
            Some(modal_input_action(
                config,
                &nonce,
                AutomationAction::Tap(AutomationButton::Down),
            )?)
        } else {
            None
        };
        let scroll_sequence = modal_input_action(
            config,
            &nonce,
            AutomationAction::Hold {
                button: AutomationButton::Down,
                duration_ms: scroll_duration_ms,
            },
        )?;
        let hold_started = Instant::now();
        let mut scroll_snapshots = Vec::new();
        while hold_started.elapsed() < Duration::from_millis(scroll_duration_ms) {
            let mut snapshot = launcher_automation::snapshot(config, &nonce)?;
            snapshot["host_elapsed_ms"] =
                json!(hold_started.elapsed().as_millis().min(u128::from(u64::MAX)) as u64);
            scroll_snapshots.push(snapshot);
            thread::sleep(Duration::from_millis(250).min(
                Duration::from_millis(scroll_duration_ms).saturating_sub(hold_started.elapsed()),
            ));
        }
        let release_sequence = modal_input_action(config, &nonce, AutomationAction::ReleaseAll)?;
        if let Some(remote_dir) = pprof_remote_dir {
            let _ = wait_gui_profile_pprof_finalization(
                config,
                session,
                &nonce,
                &format!("{remote_dir}/profile.json"),
                pprof_finalization_probe,
            )?;
        }
        let settled_arcade = wait_gui_profile_snapshot(
            config,
            &nonce,
            |snapshot| {
                gui_profile_effective_view(snapshot) == Some("arcade")
                    && matches!(
                        snapshot
                            .pointer("/semantic/preview_state")
                            .and_then(Value::as_str),
                        Some("exact" | "cached" | "empty")
                    )
                    && snapshot
                        .get("presented_action_sequence")
                        .and_then(Value::as_u64)
                        .is_some_and(|presented| presented >= release_sequence)
            },
            "terminal Arcade preview",
        )?;
        wait_for_gui_profile_file(
            config,
            session,
            &nonce,
            GUI_PROFILE_REMOTE_COMPLETE,
            Duration::from_secs(10),
            "GUI profiling completion",
        )?;
        // Keep the automation lease alive until the terminal checkpoint has
        // been captured. Frame profiles are large enough that streaming one
        // through an SSH command can exceed the launcher's request lease.
        let terminal_checkpoint = terminal_checkpoint
            .map(|label| {
                launcher_automation::capture_checkpoint(
                    config,
                    &nonce,
                    release_sequence,
                    label,
                    output_dir,
                )
            })
            .transpose()?
            .map(|checkpoint| serde_json::from_str::<Value>(&checkpoint))
            .transpose()?;
        let profile_path = output_dir.join(if pprof_remote_dir.is_some() {
            "frame-profile.json"
        } else {
            "profile.json"
        });
        get(session, GUI_PROFILE_REMOTE_COMPLETE, &profile_path)?;
        let profile: Value = serde_json::from_str(&fs::read_to_string(&profile_path)?)?;
        validate_gui_profile_route(&profile, pmu)?;
        let status_after = read_launcher_status(session)?;
        let preview_work = if preview_work_attribution {
            let launcher_log = remote_read(session, "/tmp/mister-magik-slint.log")
                .ok_or("preview attribution launcher log is missing")?;
            fs::write(output_dir.join("preview-work.log"), &launcher_log)?;
            parse_preview_work_attribution(&launcher_log)?
        } else {
            Value::Null
        };
        Ok(json!({
            "schema": "mister-magik-gui-profile-route-v1",
            "status": "complete",
            "pmu_requested": pmu,
            "actions": {
                "arcade_enter_sequence": arcade_enter_sequence,
                "scroll_sequence": scroll_sequence,
                "release_sequence": release_sequence,
                "turbo_prime_sequence": turbo_prime_sequence,
            },
            "input_mode": input_mode.label(),
            "home_ready": home_ready,
            "arcade_entered": arcade_entered,
            "scroll_snapshots": scroll_snapshots,
            "settled_arcade": settled_arcade,
            "terminal_checkpoint": terminal_checkpoint,
            "profile": profile,
            "status_before": status_before,
            "status_after": status_after,
            "preview_work_attribution": preview_work,
        }))
    })();
    let end_result = launcher_automation::end(config, &nonce).map(|_| ());
    match (run_result, end_result) {
        (Ok(route), Ok(())) => Ok(route),
        (Err(run), Ok(())) => Err(run),
        (Ok(_), Err(end)) => Err(format!("GUI profiling automation cleanup failed: {end}").into()),
        (Err(run), Err(end)) => {
            Err(format!("{run}; GUI profiling automation cleanup failed: {end}").into())
        }
    }
}

fn arcade_velocity_scroll_cleanup_command() -> String {
    format!(
        "{}; rm -f /tmp/mister-magik/realtime-frame-analytics; test ! -e /tmp/mister-magik/realtime-frame-analytics",
        gui_profile_route_cleanup_command()
    )
}

fn retain_arcade_velocity_scroll_failure_context(
    session: &Session,
    output_dir: &Path,
    route_result: &Result<Value>,
) -> Result<()> {
    let Err(error) = route_result else {
        return Ok(());
    };
    if let Some(log) = remote_read(session, "/tmp/mister-magik-slint.log") {
        fs::write(output_dir.join("failed-launcher.log"), log)?;
    }
    let automation_failure = remote_read(session, "/tmp/mister-magik/ui-automation-failure.json");
    if let Some(failure) = automation_failure.as_ref() {
        fs::write(output_dir.join("automation-failure.json"), failure)?;
    }
    let launcher_status = read_launcher_status(session).ok();
    let main_status = remote_read(session, MAIN_STATUS_REMOTE)
        .and_then(|status| serde_json::from_str::<Value>(&status).ok());
    let context = json!({
        "schema": "mister-magik-arcade-velocity-scroll-failure-context-v1",
        "error": error.to_string(),
        "automation_failure": automation_failure
            .as_deref()
            .and_then(|failure| serde_json::from_str::<Value>(failure).ok()),
        "launcher_status": launcher_status,
        "main_status": main_status,
    });
    fs::write(
        output_dir.join("failure-context.json"),
        format!("{}\n", serde_json::to_string_pretty(&context)?),
    )?;
    Ok(())
}

#[derive(Debug)]
struct ArcadeVelocityScrollRouteSnapshot {
    display_mode: DisplayMatrixMode,
    mister_ini: String,
    settings: Option<String>,
    launcher_env: Option<String>,
    boot_id: String,
    manifest: String,
}

fn arcade_velocity_scroll_display_mode(id: &str) -> Result<DisplayMatrixMode> {
    DISPLAY_MATRIX_MODES
        .iter()
        .find(|mode| mode.id == id)
        .copied()
        .ok_or_else(|| format!("Arcade benchmark display mode {id} is unsupported").into())
}

fn snapshot_arcade_velocity_scroll_route(
    config: &NativeDeviceConfig,
) -> Result<ArcadeVelocityScrollRouteSnapshot> {
    let session = connect_with(&config.connection, 10)?;
    let display = exec_checked_output(
        &session,
        "query original Arcade benchmark display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(display.stdout.trim())?.is_some() {
        return Err("Arcade benchmark cannot start during a display transaction".into());
    }
    let display_mode =
        arcade_velocity_scroll_display_mode(&parse_display_reply_active(display.stdout.trim())?)?;
    Ok(ArcadeVelocityScrollRouteSnapshot {
        display_mode,
        mister_ini: remote_read(&session, "/media/fat/MiSTer.ini")
            .ok_or("MiSTer.ini is unavailable before the Arcade benchmark")?,
        settings: remote_read(&session, ORIENTATION_TRANSITION_SETTINGS_REMOTE.as_str()),
        launcher_env: remote_read(&session, DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str()),
        boot_id: remote_read(&session, "/proc/sys/kernel/random/boot_id")
            .ok_or("device boot id is unavailable before the Arcade benchmark")?,
        manifest: remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
            .ok_or("development platform manifest is unavailable before the Arcade benchmark")?,
    })
}

fn restore_optional_remote_file(
    session: &Session,
    path: &str,
    expected: Option<&str>,
    label: &str,
) -> Result<()> {
    match expected {
        Some(contents) => {
            put_bytes(session, path, contents.as_bytes())?;
            exec_checked(
                session,
                &format!("sync restored {label}"),
                &format!("set -eu; sync; test -f {}", sh(path)),
            )?;
        }
        None => {
            exec_checked(
                session,
                &format!("remove transient {label}"),
                &format!("set -eu; rm -f {}; sync; test ! -e {}", sh(path), sh(path)),
            )?;
        }
    }
    Ok(())
}

fn restore_arcade_velocity_scroll_route(
    config: &NativeDeviceConfig,
    snapshot: &ArcadeVelocityScrollRouteSnapshot,
) -> Result<Value> {
    let session = connect_with(&config.connection, 10)?;
    let clear_result = exec_checked(
        &session,
        "clear Arcade benchmark one-shot state",
        &arcade_velocity_scroll_cleanup_command(),
    );
    let launcher_result = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    combine_benchmark_cleanup(clear_result, launcher_result)?;
    drop(session);
    cancel_pending_benchmark_display_mode(config)?;
    apply_confirmed_display_mode(
        config,
        snapshot.display_mode,
        "Arcade benchmark display restoration",
    )?;

    let session = connect_with(&config.connection, 10)?;
    restore_optional_remote_file(
        &session,
        "/media/fat/MiSTer.ini",
        Some(&snapshot.mister_ini),
        "MiSTer.ini",
    )?;
    restore_optional_remote_file(
        &session,
        ORIENTATION_TRANSITION_SETTINGS_REMOTE.as_str(),
        snapshot.settings.as_deref(),
        "launcher settings",
    )?;
    launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    )?;
    restore_optional_remote_file(
        &session,
        DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str(),
        snapshot.launcher_env.as_deref(),
        "launcher environment",
    )?;
    wait_launcher_ready(&session, Instant::now(), Duration::from_secs(45))?;

    let display = exec_checked_output(
        &session,
        "verify restored Arcade benchmark display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(display.stdout.trim())?.is_some()
        || parse_display_reply_active(display.stdout.trim())? != snapshot.display_mode.id
    {
        return Err("Arcade benchmark did not restore the original display mode".into());
    }
    if remote_read(&session, "/media/fat/MiSTer.ini").as_deref()
        != Some(snapshot.mister_ini.as_str())
    {
        return Err("Arcade benchmark did not restore MiSTer.ini exactly".into());
    }
    if remote_read(&session, ORIENTATION_TRANSITION_SETTINGS_REMOTE.as_str()).as_deref()
        != snapshot.settings.as_deref()
    {
        return Err("Arcade benchmark did not restore settings.json exactly".into());
    }
    if remote_read(&session, DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str()).as_deref()
        != snapshot.launcher_env.as_deref()
    {
        return Err("Arcade benchmark did not restore launcher.env exactly".into());
    }
    if remote_read(&session, "/proc/sys/kernel/random/boot_id").as_deref()
        != Some(snapshot.boot_id.as_str())
    {
        return Err("device rebooted during the Arcade benchmark".into());
    }
    if remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE).as_deref()
        != Some(snapshot.manifest.as_str())
    {
        return Err("installed platform manifest changed during the Arcade benchmark".into());
    }
    exec_checked(
        &session,
        "Arcade benchmark restored delivery health",
        &delivery_health_command("dev")?,
    )?;
    let status = read_launcher_status(&session)?;
    Ok(json!({
        "status": "restored",
        "display_mode": snapshot.display_mode.id,
        "mister_ini_sha256": encode_hex(&Sha256::digest(snapshot.mister_ini.as_bytes())),
        "settings_sha256": snapshot
            .settings
            .as_ref()
            .map(|settings| encode_hex(&Sha256::digest(settings.as_bytes()))),
        "launcher_env_sha256": snapshot
            .launcher_env
            .as_ref()
            .map(|environment| encode_hex(&Sha256::digest(environment.as_bytes()))),
        "launcher_pid": status.get("launcher_pid"),
    }))
}

fn arcade_velocity_scroll_summary_orientation(summary: &Value) -> Option<&str> {
    summary
        .get("screen_orientation")
        .and_then(Value::as_str)
        .or_else(|| {
            summary
                .pointer("/route/screen_orientation")
                .and_then(Value::as_str)
        })
}

fn arcade_velocity_scroll_profile_orientation(orientation: &str) -> Result<&'static str> {
    match orientation {
        "normal" => Ok("Normal"),
        "monitor-clockwise" => Ok("Monitor right (clockwise)"),
        "monitor-counterclockwise" => Ok("Monitor left (counterclockwise)"),
        _ => Err(format!("unsupported Arcade benchmark orientation {orientation}").into()),
    }
}

fn arcade_velocity_scroll_effective_route(display_mode: &str, orientation: &str) -> &'static str {
    match (display_mode, orientation) {
        ("hdmi-1280x720p60", "Normal") => "hdmi-landscape",
        ("hdmi-1280x720p60", "Monitor left (counterclockwise)") => "hdmi-portrait-left",
        ("hdmi-1280x720p60", "Monitor right (clockwise)") => "hdmi-portrait-right",
        ("hdmi-1920x1080p60", "Normal") => "hdmi1080-landscape",
        ("hdmi-1920x1080p60", "Monitor left (counterclockwise)") => "hdmi1080-portrait-left",
        ("crt-240p60", "Monitor left (counterclockwise)") => "crt240-portrait-left",
        ("crt-240p60", "Monitor right (clockwise)") => "crt240-portrait-right",
        ("crt-288p50", "Monitor left (counterclockwise)") => "crt288-portrait-left",
        ("crt-288p50", "Monitor right (clockwise)") => "crt288-portrait-right",
        _ => "active",
    }
}

fn run_arcade_velocity_scroll_spec(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    spec: ArcadeVelocityScrollRunSpec,
) -> Result<Value> {
    let expected_profiler = match spec.arm {
        ArcadeVelocityScrollArm::Pprof => ArcadeVelocityScrollProfiler::Pprof,
        ArcadeVelocityScrollArm::Pmu => ArcadeVelocityScrollProfiler::Pmu,
        ArcadeVelocityScrollArm::Streamline => ArcadeVelocityScrollProfiler::Streamline,
        _ => ArcadeVelocityScrollProfiler::None,
    };
    if spec.profiler != expected_profiler {
        return Err("Arcade benchmark run specification has an inconsistent profiler".into());
    }
    let orientation = spec.route.orientation();
    let summary = match spec.arm {
        ArcadeVelocityScrollArm::Control => profile_installed_arcade_velocity_scroll_workload(
            config,
            output_dir,
            spec.duration_ms,
            spec.telemetry_secs,
            None,
            spec.input_mode,
            orientation,
        ),
        ArcadeVelocityScrollArm::Turbo => profile_installed_arcade_velocity_scroll_workload(
            config,
            output_dir,
            spec.duration_ms,
            spec.telemetry_secs,
            None,
            spec.input_mode,
            orientation,
        ),
        ArcadeVelocityScrollArm::Pprof => profile_installed_arcade_velocity_scroll_pprof_workload(
            config,
            output_dir,
            spec.duration_ms,
            spec.telemetry_secs,
            Duration::ZERO,
            "mister-magik-arcade-velocity-scroll-pprof-v1",
            orientation,
        ),
        ArcadeVelocityScrollArm::Pmu => profile_installed_arcade_velocity_scroll_pmu_workload(
            config,
            output_dir,
            spec.duration_ms,
            spec.telemetry_secs,
            "mister-magik-arcade-velocity-scroll-pmu-v1",
            orientation,
        ),
        ArcadeVelocityScrollArm::Streamline => {
            profile_installed_arcade_velocity_scroll_streamline_workload(
                config,
                output_dir,
                spec.duration_ms,
                spec.telemetry_secs,
                orientation,
            )
        }
    }?;
    serde_json::from_str(&summary).map_err(Into::into)
}

fn profile_installed_arcade_velocity_scroll_run(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    spec: ArcadeVelocityScrollRunSpec,
) -> Result<String> {
    fs::create_dir_all(output_dir)?;
    let _signal_guard = AttendedOperationSignalGuard::install();
    let snapshot = snapshot_arcade_velocity_scroll_route(config)?;
    let requested_mode = spec
        .route
        .display_mode()
        .map(arcade_velocity_scroll_display_mode)
        .transpose()?;

    let run_result = (|| -> Result<Value> {
        if let Some(mode) = requested_mode {
            apply_confirmed_display_mode(config, mode, "Arcade benchmark route selection")?;
        }
        let summary = run_arcade_velocity_scroll_spec(config, output_dir, spec)?;
        let effective_display = summary
            .get("display_mode")
            .and_then(Value::as_str)
            .ok_or("Arcade benchmark summary has no effective display mode")?;
        let effective_orientation = arcade_velocity_scroll_summary_orientation(&summary)
            .ok_or("Arcade benchmark summary has no effective orientation")?;
        if let Some(mode) = requested_mode
            && effective_display != mode.id
        {
            return Err(format!(
                "Arcade benchmark route requested {} but ran {effective_display}",
                mode.id
            )
            .into());
        }
        if let Some(orientation) = spec.route.orientation()
            && effective_orientation != arcade_velocity_scroll_profile_orientation(orientation)?
        {
            return Err(format!(
                "Arcade benchmark route requested {orientation} but ran {effective_orientation}"
            )
            .into());
        }
        Ok(summary)
    })();
    let restoration_result = restore_arcade_velocity_scroll_route(config, &snapshot);

    let effective_display_mode = run_result
        .as_ref()
        .ok()
        .and_then(|summary| summary.get("display_mode"))
        .and_then(Value::as_str);
    let effective_orientation = run_result
        .as_ref()
        .ok()
        .and_then(arcade_velocity_scroll_summary_orientation);
    let effective_route = effective_display_mode
        .zip(effective_orientation)
        .map(|(display, orientation)| arcade_velocity_scroll_effective_route(display, orientation));

    let route_record = json!({
        "schema": "mister-magik-arcade-velocity-scroll-route-v1",
        "requested_route": spec.route.label(),
        "requested_display_mode": spec.route.display_mode(),
        "requested_orientation": spec.route.orientation(),
        "duration_ms": spec.duration_ms,
        "evidence_authority": arcade_velocity_scroll_evidence_authority(spec),
        "original_display_mode": snapshot.display_mode.id,
        "effective_route": effective_route,
        "effective_display_mode": effective_display_mode,
        "effective_orientation": effective_orientation,
        "run_status": if run_result.is_ok() { "complete" } else { "failed" },
        "restoration": restoration_result.as_ref().ok(),
        "run_failure": run_result.as_ref().err().map(ToString::to_string),
        "restoration_failure": restoration_result.as_ref().err().map(ToString::to_string),
    });
    fs::write(
        output_dir.join("route.json"),
        format!("{}\n", serde_json::to_string_pretty(&route_record)?),
    )?;

    let (mut summary, restoration) = match (run_result, restoration_result) {
        (Ok(summary), Ok(restoration)) => (summary, restoration),
        (Err(run), Ok(_)) => return Err(run),
        (Ok(_), Err(restoration)) => {
            return Err(format!("Arcade benchmark restoration failed: {restoration}").into());
        }
        (Err(run), Err(restoration)) => {
            return Err(
                format!("{run}; Arcade benchmark restoration failed: {restoration}").into(),
            );
        }
    };
    let effective_display = summary["display_mode"].clone();
    let effective_orientation = arcade_velocity_scroll_summary_orientation(&summary)
        .map(str::to_owned)
        .ok_or("Arcade benchmark summary lost its effective orientation")?;
    summary["requested_route"] = json!(spec.route.label());
    summary["requested_duration_ms"] = json!(spec.duration_ms);
    summary["evidence_authority"] = json!(arcade_velocity_scroll_evidence_authority(spec));
    summary["effective_route"] = json!(arcade_velocity_scroll_effective_route(
        summary["display_mode"].as_str().unwrap_or_default(),
        &effective_orientation,
    ));
    summary["effective_display_mode"] = effective_display;
    summary["effective_orientation"] = json!(effective_orientation);
    summary["route_restoration"] = restoration;
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn arcade_velocity_scroll_evidence_authority(spec: ArcadeVelocityScrollRunSpec) -> &'static str {
    if !matches!(spec.profiler, ArcadeVelocityScrollProfiler::None) {
        "attribution-only"
    } else if spec.duration_ms >= 40_000 {
        "qualification"
    } else {
        "directional"
    }
}

fn profile_installed_arcade_velocity_scroll(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    profile_installed_arcade_velocity_scroll_workload(
        config,
        output_dir,
        ARCADE_VELOCITY_SCROLL_DURATION_MS,
        ARCADE_VELOCITY_SCROLL_TELEMETRY_SECS,
        None,
        ArcadeRunInputMode::Held,
        None,
    )
}

fn profile_installed_arcade_velocity_scroll_workload(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    scroll_duration_ms: u64,
    telemetry_secs: u64,
    artifact_schema: Option<&str>,
    input_mode: ArcadeRunInputMode,
    startup_orientation: Option<&str>,
) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    let capability = exec_checked_output(
        &session,
        "installed Arcade velocity-scroll capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("arcade-velocity-scroll-v1")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support arcade-velocity-scroll-v1".into());
    }
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing")?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable")?;
    let original_display = exec_checked_output(
        &session,
        "query Arcade velocity-scroll display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(original_display.stdout.trim())?.is_some() {
        return Err(
            "Arcade velocity-scroll benchmark cannot start during a display transaction".into(),
        );
    }
    let display_mode = parse_display_reply_active(original_display.stdout.trim())?;
    let _ = arcade_velocity_scroll_minimum_fps(&display_mode)?;
    fs::create_dir_all(output_dir)?;

    let telemetry_endpoint = config.agent()?.clone();
    let telemetry_thread = thread::spawn(move || {
        agent_telemetry_for_duration_with_mode(
            &telemetry_endpoint,
            Duration::from_secs(telemetry_secs),
            100,
            "off",
        )
        .map_err(|error| error.to_string())
    });
    let route_result = match input_mode {
        ArcadeRunInputMode::Held => run_gui_frame_profile_route(
            config,
            &session,
            output_dir,
            false,
            scroll_duration_ms,
            Some("terminal-arcade"),
            startup_orientation,
        ),
        ArcadeRunInputMode::Turbo => run_gui_frame_profile_route_turbo(
            config,
            &session,
            output_dir,
            scroll_duration_ms,
            Some("terminal-arcade"),
            startup_orientation,
        ),
    };
    retain_arcade_velocity_scroll_failure_context(&session, output_dir, &route_result)?;
    let telemetry_result: Result<Vec<Value>> = match telemetry_thread.join() {
        Ok(Ok(telemetry)) => Ok(telemetry),
        Ok(Err(error)) => Err(error.into()),
        Err(_) => Err("Arcade velocity-scroll telemetry collector panicked".into()),
    };
    let run_result = match (route_result, telemetry_result) {
        (Ok(route), Ok(telemetry)) => {
            let telemetry_text = telemetry
                .iter()
                .map(serde_json::to_string)
                .collect::<std::result::Result<Vec<_>, _>>()?
                .join("\n");
            fs::write(
                output_dir.join("telemetry.jsonl"),
                format!("{telemetry_text}\n"),
            )?;
            let mut route_summary = summarize_arcade_velocity_scroll(
                output_dir,
                &route,
                &telemetry,
                &display_mode,
                scroll_duration_ms,
            )?;
            route_summary["input_mode"] = json!(input_mode.label());
            Ok(match artifact_schema {
                Some(schema) => json!({
                    "schema": schema,
                    "artifact_status": "passed",
                    "display_mode": display_mode,
                    "scroll_duration_ms": scroll_duration_ms,
                    "route": route_summary,
                }),
                None => route_summary,
            })
        }
        (Err(route), Ok(_)) => Err(route),
        (Ok(_), Err(telemetry)) => Err(telemetry),
        (Err(route), Err(telemetry)) => {
            Err(format!("{route}; telemetry collection failed: {telemetry}").into())
        }
    };

    let launcher_restore = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let cleanup = exec_checked(
        &session,
        "clean Arcade velocity-scroll benchmark state",
        &arcade_velocity_scroll_cleanup_command(),
    );
    let summary = match (run_result, launcher_restore, cleanup) {
        (Ok(summary), Ok(()), Ok(())) => summary,
        (run, launcher, cleanup) => {
            return Err(format!(
                "Arcade velocity-scroll benchmark failed: run={:?}; launcher_restore={:?}; cleanup={:?}",
                run.err(),
                launcher.err(),
                cleanup.err()
            )
            .into());
        }
    };

    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing after Arcade velocity scroll")?;
    if final_manifest != manifest {
        return Err("installed platform manifest changed during Arcade velocity scroll".into());
    }
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after Arcade velocity scroll")?;
    if final_boot_id != boot_id {
        return Err("device rebooted during Arcade velocity scroll".into());
    }
    let final_display = exec_checked_output(
        &session,
        "verify Arcade velocity-scroll display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(final_display.stdout.trim())?.is_some()
        || parse_display_reply_active(final_display.stdout.trim())? != display_mode
    {
        return Err("display mode changed during Arcade velocity scroll".into());
    }
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_arcade_velocity_scroll_pprof(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    profile_installed_arcade_velocity_scroll_pprof_workload(
        config,
        output_dir,
        ARCADE_VELOCITY_SCROLL_PPROF_DURATION_MS,
        ARCADE_VELOCITY_SCROLL_PPROF_TELEMETRY_SECS,
        Duration::ZERO,
        "mister-magik-arcade-velocity-scroll-pprof-v1",
        None,
    )
}

fn profile_installed_arcade_velocity_scroll_pprof_workload(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    scroll_duration_ms: u64,
    telemetry_secs: u64,
    finalization_probe: Duration,
    artifact_schema: &str,
    startup_orientation: Option<&str>,
) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    let capability = exec_checked_output(
        &session,
        "installed Arcade velocity-scroll pprof capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("arcade-velocity-scroll-attribution-v1")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support arcade-velocity-scroll-attribution-v1".into());
    }
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing")?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable")?;
    let original_display = exec_checked_output(
        &session,
        "query Arcade velocity-scroll pprof display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(original_display.stdout.trim())?.is_some() {
        return Err(
            "Arcade velocity-scroll pprof cannot start during a display transaction".into(),
        );
    }
    let display_mode = parse_display_reply_active(original_display.stdout.trim())?;
    let _ = arcade_velocity_scroll_minimum_fps(&display_mode)?;
    fs::create_dir_all(output_dir)?;
    exec_checked(
        &session,
        "prepare Arcade velocity-scroll pprof state",
        &format!(
            "set -eu; rm -rf {pprof}; {cleanup}",
            pprof = sh(ARCADE_VELOCITY_SCROLL_PPROF_REMOTE_DIR),
            cleanup = gui_profile_route_cleanup_command(),
        ),
    )?;

    let telemetry_endpoint = config.agent()?.clone();
    let telemetry_thread = thread::spawn(move || {
        agent_telemetry_for_duration_with_mode(
            &telemetry_endpoint,
            Duration::from_secs(telemetry_secs),
            100,
            "off",
        )
        .map_err(|error| error.to_string())
    });
    let route_result = run_gui_frame_profile_route_with_pprof(
        config,
        &session,
        output_dir,
        GuiFrameProfileRouteSpec {
            pmu: false,
            scroll_duration_ms,
            terminal_checkpoint: Some("terminal-arcade"),
            pprof_remote_dir: Some(ARCADE_VELOCITY_SCROLL_PPROF_REMOTE_DIR),
            pprof_finalization_probe: finalization_probe,
            input_mode: ArcadeRunInputMode::Held,
            startup_orientation,
            preview_work_attribution: false,
        },
    );
    retain_arcade_velocity_scroll_failure_context(&session, output_dir, &route_result)?;
    let telemetry_result: Result<Vec<Value>> = match telemetry_thread.join() {
        Ok(Ok(telemetry)) => Ok(telemetry),
        Ok(Err(error)) => Err(error.into()),
        Err(_) => Err("Arcade velocity-scroll pprof telemetry collector panicked".into()),
    };
    let run_result = match (route_result, telemetry_result) {
        (Ok(route), Ok(telemetry)) => {
            let telemetry_text = telemetry
                .iter()
                .map(serde_json::to_string)
                .collect::<std::result::Result<Vec<_>, _>>()?
                .join("\n");
            fs::write(
                output_dir.join("telemetry.jsonl"),
                format!("{telemetry_text}\n"),
            )?;
            let profile_text = wait_for_remote_text(
                &session,
                &format!("{ARCADE_VELOCITY_SCROLL_PPROF_REMOTE_DIR}/profile.json"),
                Duration::from_secs(10),
                "Arcade velocity-scroll pprof completion",
            )?;
            let profile: Value = serde_json::from_str(profile_text.trim())?;
            if profile.get("schema").and_then(Value::as_str)
                != Some("mister-magik-arcade-velocity-scroll-pprof-v1")
                || profile.get("state").and_then(Value::as_str) != Some("complete")
                || profile
                    .get("sample_hits")
                    .and_then(Value::as_i64)
                    .unwrap_or(0)
                    <= 0
            {
                return Err("Arcade velocity-scroll pprof pass produced no samples".into());
            }
            fs::write(output_dir.join("profile.json"), &profile_text)?;
            for artifact in ["flamegraph.svg", "stacks.folded"] {
                get(
                    &session,
                    &format!("{ARCADE_VELOCITY_SCROLL_PPROF_REMOTE_DIR}/{artifact}"),
                    &output_dir.join(artifact),
                )?;
            }
            let summary = summarize_arcade_velocity_scroll(
                output_dir,
                &route,
                &telemetry,
                &display_mode,
                scroll_duration_ms,
            )?;
            Ok(json!({
                "schema": artifact_schema,
                "artifact_status": "passed",
                "display_mode": display_mode,
                "scroll_duration_ms": scroll_duration_ms,
                "minimum_finalization_probe_ms": finalization_probe.as_millis(),
                "route": summary,
                "pprof": profile,
            }))
        }
        (Err(route), Ok(_)) => Err(route),
        (Ok(_), Err(telemetry)) => Err(telemetry),
        (Err(route), Err(telemetry)) => {
            Err(format!("{route}; telemetry collection failed: {telemetry}").into())
        }
    };

    let launcher_restore = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let cleanup = exec_checked(
        &session,
        "clean Arcade velocity-scroll pprof state",
        &format!(
            "set -eu; rm -rf {pprof}; {cleanup}",
            pprof = sh(ARCADE_VELOCITY_SCROLL_PPROF_REMOTE_DIR),
            cleanup = gui_profile_route_cleanup_command(),
        ),
    );
    let summary = match (run_result, launcher_restore, cleanup) {
        (Ok(summary), Ok(()), Ok(())) => summary,
        (run, launcher, cleanup) => {
            return Err(format!(
                "Arcade velocity-scroll pprof failed: run={:?}; launcher_restore={:?}; cleanup={:?}",
                run.err(),
                launcher.err(),
                cleanup.err()
            )
            .into());
        }
    };
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing after Arcade velocity-scroll pprof")?;
    if final_manifest != manifest {
        return Err(
            "installed platform manifest changed during Arcade velocity-scroll pprof".into(),
        );
    }
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after Arcade velocity-scroll pprof")?;
    if final_boot_id != boot_id {
        return Err("device rebooted during Arcade velocity-scroll pprof".into());
    }
    let final_display = exec_checked_output(
        &session,
        "verify Arcade velocity-scroll pprof display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(final_display.stdout.trim())?.is_some()
        || parse_display_reply_active(final_display.stdout.trim())? != display_mode
    {
        return Err("display mode changed during Arcade velocity-scroll pprof".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_arcade_velocity_scroll_pmu(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    profile_installed_arcade_velocity_scroll_pmu_workload(
        config,
        output_dir,
        ARCADE_VELOCITY_SCROLL_DURATION_MS,
        ARCADE_VELOCITY_SCROLL_TELEMETRY_SECS,
        "mister-magik-arcade-velocity-scroll-pmu-v1",
        None,
    )
}

fn profile_installed_arcade_velocity_scroll_pmu_workload(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    scroll_duration_ms: u64,
    telemetry_secs: u64,
    artifact_schema: &str,
    startup_orientation: Option<&str>,
) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    let capability = exec_checked_output(
        &session,
        "installed Arcade velocity-scroll PMU capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("arcade-velocity-scroll-attribution-v1")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support arcade-velocity-scroll-attribution-v1".into());
    }
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing")?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable")?;
    let original_display = exec_checked_output(
        &session,
        "query Arcade velocity-scroll PMU display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(original_display.stdout.trim())?.is_some() {
        return Err("Arcade velocity-scroll PMU cannot start during a display transaction".into());
    }
    let display_mode = parse_display_reply_active(original_display.stdout.trim())?;
    let _ = arcade_velocity_scroll_minimum_fps(&display_mode)?;
    fs::create_dir_all(output_dir)?;

    let telemetry_endpoint = config.agent()?.clone();
    let telemetry_thread = thread::spawn(move || {
        agent_telemetry_for_duration_with_mode(
            &telemetry_endpoint,
            Duration::from_secs(telemetry_secs),
            100,
            "off",
        )
        .map_err(|error| error.to_string())
    });
    let route_result = run_gui_frame_profile_route(
        config,
        &session,
        output_dir,
        true,
        scroll_duration_ms,
        Some("terminal-arcade"),
        startup_orientation,
    );
    retain_arcade_velocity_scroll_failure_context(&session, output_dir, &route_result)?;
    let telemetry_result: Result<Vec<Value>> = match telemetry_thread.join() {
        Ok(Ok(telemetry)) => Ok(telemetry),
        Ok(Err(error)) => Err(error.into()),
        Err(_) => Err("Arcade velocity-scroll PMU telemetry collector panicked".into()),
    };
    let run_result = match (route_result, telemetry_result) {
        (Ok(route), Ok(telemetry)) => {
            let telemetry_text = telemetry
                .iter()
                .map(serde_json::to_string)
                .collect::<std::result::Result<Vec<_>, _>>()?
                .join("\n");
            fs::write(
                output_dir.join("telemetry.jsonl"),
                format!("{telemetry_text}\n"),
            )?;
            let pmu = route
                .pointer("/profile/thread_profile")
                .cloned()
                .ok_or("Arcade velocity-scroll PMU profile is missing thread_profile")?;
            if pmu.get("enabled").and_then(Value::as_bool) != Some(true)
                || pmu.get("failure").is_some_and(|failure| !failure.is_null())
                || pmu.get("dropped_spans").and_then(Value::as_u64) != Some(0)
                || pmu
                    .get("records")
                    .and_then(Value::as_array)
                    .is_none_or(Vec::is_empty)
            {
                return Err("Arcade velocity-scroll PMU profile is incomplete".into());
            }
            validate_pmu_counter_set(&pmu, "cortex-a9-neon")?;
            let route_summary = summarize_arcade_velocity_scroll(
                output_dir,
                &route,
                &telemetry,
                &display_mode,
                scroll_duration_ms,
            )?;
            Ok(json!({
                "schema": artifact_schema,
                "artifact_status": "passed",
                "display_mode": display_mode,
                "scroll_duration_ms": scroll_duration_ms,
                "route": route_summary,
                "pmu": pmu,
            }))
        }
        (Err(route), Ok(_)) => Err(route),
        (Ok(_), Err(telemetry)) => Err(telemetry),
        (Err(route), Err(telemetry)) => {
            Err(format!("{route}; telemetry collection failed: {telemetry}").into())
        }
    };
    let launcher_restore = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let cleanup = exec_checked(
        &session,
        "clean Arcade velocity-scroll PMU state",
        &arcade_velocity_scroll_cleanup_command(),
    );
    let summary = match (run_result, launcher_restore, cleanup) {
        (Ok(summary), Ok(()), Ok(())) => summary,
        (run, launcher, cleanup) => {
            return Err(format!(
                "Arcade velocity-scroll PMU failed: run={:?}; launcher_restore={:?}; cleanup={:?}",
                run.err(),
                launcher.err(),
                cleanup.err()
            )
            .into());
        }
    };
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing after Arcade velocity-scroll PMU")?;
    if final_manifest != manifest {
        return Err("installed platform manifest changed during Arcade velocity-scroll PMU".into());
    }
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after Arcade velocity-scroll PMU")?;
    if final_boot_id != boot_id {
        return Err("device rebooted during Arcade velocity-scroll PMU".into());
    }
    let final_display = exec_checked_output(
        &session,
        "verify Arcade velocity-scroll PMU display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(final_display.stdout.trim())?.is_some()
        || parse_display_reply_active(final_display.stdout.trim())? != display_mode
    {
        return Err("display mode changed during Arcade velocity-scroll PMU".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_arcade_velocity_scroll_streamline(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    profile_installed_arcade_velocity_scroll_streamline_workload(
        config,
        output_dir,
        ARCADE_VELOCITY_SCROLL_DURATION_MS,
        ARCADE_VELOCITY_SCROLL_TELEMETRY_SECS,
        None,
    )
}

fn profile_installed_arcade_velocity_scroll_streamline_workload(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    scroll_duration_ms: u64,
    telemetry_secs: u64,
    startup_orientation: Option<&str>,
) -> Result<String> {
    let gatord = streamline_gatord_path(env::var_os("MISTER_GATORD_PATH"))?;
    let gatord_metadata = fs::metadata(&gatord)?;
    if !gatord_metadata.is_file() || gatord_metadata.len() == 0 {
        return Err("MISTER_GATORD_PATH must name a non-empty regular file".into());
    }
    if gatord_metadata.len() > 64 * 1024 * 1024 {
        return Err("MISTER_GATORD_PATH exceeds the 64 MiB upload limit".into());
    }
    let gatord_sha256 = file_sha256(gatord.clone())?;
    fs::create_dir_all(output_dir)?;
    let session = connect_with(&config.connection, 30)?;
    let capability = exec_checked_output(
        &session,
        "installed Arcade velocity-scroll Streamline capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("arcade-velocity-scroll-attribution-v1")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support arcade-velocity-scroll-attribution-v1".into());
    }
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing")?;
    let installed_identity = streamline_installed_identity(&session, config.agent()?, &manifest)?;
    let boot_id = installed_identity.boot_id.clone();
    let original_display = exec_checked_output(
        &session,
        "query Arcade velocity-scroll Streamline display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(original_display.stdout.trim())?.is_some() {
        return Err(
            "Arcade velocity-scroll Streamline cannot start during a display transaction".into(),
        );
    }
    let display_mode = parse_display_reply_active(original_display.stdout.trim())?;
    let _ = arcade_velocity_scroll_minimum_fps(&display_mode)?;
    let route_dir = output_dir.join("route");
    let streamline_dir = output_dir.join("streamline");
    fs::create_dir_all(&route_dir)?;
    fs::create_dir_all(&streamline_dir)?;

    let telemetry_endpoint = config.agent()?.clone();
    let telemetry_thread = thread::spawn(move || {
        agent_telemetry_for_duration_with_mode(
            &telemetry_endpoint,
            Duration::from_secs(telemetry_secs),
            100,
            "off",
        )
        .map_err(|error| error.to_string())
    });
    let streamline_result = run_gui_frame_streamline_arm_with_options(
        config,
        &session,
        &gatord,
        &route_dir,
        scroll_duration_ms,
        ARCADE_VELOCITY_SCROLL_STREAMLINE_CAPTURE,
        startup_orientation,
    );
    let telemetry_result: Result<Vec<Value>> = match telemetry_thread.join() {
        Ok(Ok(telemetry)) => Ok(telemetry),
        Ok(Err(error)) => Err(error.into()),
        Err(_) => Err("Arcade velocity-scroll Streamline telemetry collector panicked".into()),
    };
    let (streamline_arm, telemetry) = match (streamline_result, telemetry_result) {
        (Ok(arm), Ok(telemetry)) => (arm, telemetry),
        (Err(streamline), Ok(_)) => return Err(streamline),
        (Ok(_), Err(telemetry)) => return Err(telemetry),
        (Err(streamline), Err(telemetry)) => {
            return Err(format!(
                "Arcade velocity-scroll Streamline failed: {streamline}; telemetry collection failed: {telemetry}"
            )
            .into());
        }
    };
    let telemetry_text = telemetry
        .iter()
        .map(serde_json::to_string)
        .collect::<std::result::Result<Vec<_>, _>>()?
        .join("\n");
    fs::write(
        route_dir.join("telemetry.jsonl"),
        format!("{telemetry_text}\n"),
    )?;
    let route_summary = summarize_arcade_velocity_scroll(
        &route_dir,
        &streamline_arm.route,
        &telemetry,
        &display_mode,
        scroll_duration_ms,
    )?;
    let symbol_image =
        retain_streamline_gui_symbol_image(&session, &streamline_dir, &installed_identity)?;
    let mut capture_manifest = streamline_capture_manifest(
        &installed_identity,
        &streamline_arm.gatord_version,
        &gatord_sha256,
        ARCADE_VELOCITY_SCROLL_STREAMLINE_CAPTURE,
        streamline_arm.capture_started_monotonic_ns,
        streamline_arm.capture_ended_monotonic_ns,
    );
    capture_manifest["symbol_images"] = json!([symbol_image.clone()]);
    fs::write(
        streamline_dir.join("capture-manifest.json"),
        format!("{}\n", serde_json::to_string_pretty(&capture_manifest)?),
    )?;
    let summary = json!({
        "schema": "mister-magik-arcade-velocity-scroll-streamline-v1",
        "artifact_status": "passed",
        "display_mode": display_mode,
        "scroll_duration_ms": scroll_duration_ms,
        "route": route_summary,
        "streamline": {
            "gatord_version": streamline_arm.gatord_version,
            "gatord_sha256": gatord_sha256,
            "archive_sha256": streamline_arm.archive_sha256,
            "capture": "streamline/mister-magik.apc",
            "archive": format!("streamline/{}", ARCADE_VELOCITY_SCROLL_STREAMLINE_CAPTURE.archive_file),
            "capture_manifest": "streamline/capture-manifest.json",
            "symbol_image": symbol_image,
            "system_wide": true,
            "correlation_clock": "CLOCK_MONOTONIC",
        },
    });
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE).ok_or(
        "development platform manifest is missing after Arcade velocity-scroll Streamline",
    )?;
    if final_manifest != manifest {
        return Err(
            "installed platform manifest changed during Arcade velocity-scroll Streamline".into(),
        );
    }
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after Arcade velocity-scroll Streamline")?
        .trim()
        .to_owned();
    if final_boot_id != boot_id {
        return Err("device rebooted during Arcade velocity-scroll Streamline".into());
    }
    let final_display = exec_checked_output(
        &session,
        "verify Arcade velocity-scroll Streamline display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(final_display.stdout.trim())?.is_some()
        || parse_display_reply_active(final_display.stdout.trim())? != display_mode
    {
        return Err("display mode changed during Arcade velocity-scroll Streamline".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_arcade_velocity_scroll_attribution(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    fs::create_dir_all(output_dir)?;
    let control_text =
        profile_installed_arcade_velocity_scroll(config, &output_dir.join("control"))?;
    let pmu_text = profile_installed_arcade_velocity_scroll_pmu(config, &output_dir.join("pmu"))?;
    let streamline_text = profile_installed_arcade_velocity_scroll_streamline(
        config,
        &output_dir.join("streamline"),
    )?;
    let pprof_text =
        profile_installed_arcade_velocity_scroll_pprof(config, &output_dir.join("pprof"))?;
    let control: Value = serde_json::from_str(&control_text)?;
    let pprof: Value = serde_json::from_str(&pprof_text)?;
    let pmu: Value = serde_json::from_str(&pmu_text)?;
    let streamline: Value = serde_json::from_str(&streamline_text)?;
    let summary = json!({
        "schema": "mister-magik-arcade-velocity-scroll-attribution-v1",
        "artifact_status": "passed",
        "performance_authority": "control",
        "display_route_policy": "preserve-active-route",
        "arms": {
            "control": control,
            "pprof": pprof,
            "pmu": pmu,
            "streamline": streamline,
        },
        "correlation": {
            "clock_domain": "CLOCK_MONOTONIC",
            "candidate_order": [
                "crt_backdrop_list_overlay",
                "crt_backdrop_blend",
                "crt_backdrop_copy",
            ],
            "selection_rule": "advance only when a hotspot accounts for >=10% of cycles, >=1ms of frame time, or measurable repeated-vblank reduction",
            "cadence_rule": "unprofiled control owns physical cadence and repeated-vblank gates",
        },
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    let mut report = String::from("# Arcade velocity-scroll profiling correlation\n\n");
    report.push_str(
        "The control arm is the only cadence authority; profiler arms are attribution-only.\n\n",
    );
    for arm in ["control", "pprof", "pmu", "streamline"] {
        let arm_summary = &summary["arms"][arm];
        report.push_str(&format!(
            "- {arm}: schema `{}`\n",
            arm_summary["schema"].as_str().unwrap_or("unknown")
        ));
    }
    report.push_str(
        "\nInitial hotspot order is list overlay, blend, copy, then snapshot; advance only after the correlation thresholds in summary.json are met.\n",
    );
    fs::write(output_dir.join("report.md"), report)?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_preview_work_attribution(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    const SAMPLES_PER_ROUTE: usize = 3;
    const SCROLL_DURATION_MS: u64 = 5_000;

    fs::create_dir_all(output_dir)?;
    let _signal_guard = AttendedOperationSignalGuard::install();
    let session = connect_with(&config.connection, 10)?;
    let capability = exec_checked_output(
        &session,
        "installed preview-work benchmark capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("preview-work-attribution-v1")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support preview-work-attribution-v1".into());
    }
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing")?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable")?;
    let registry = exec_checked_output(
        &session,
        "preview-work registry report",
        DEVELOPMENT_CATALOG_REGISTRY_REPORT_COMMAND.as_str(),
    )?;
    let registry = parse_system_entry_registry(&registry.stdout)?;
    let arcade_games = registry["systems"]
        .as_array()
        .and_then(|systems| {
            systems.iter().find_map(|row| {
                (row.get("system").and_then(Value::as_str) == Some("arcade"))
                    .then(|| row.get("games").and_then(Value::as_u64))
                    .flatten()
            })
        })
        .filter(|games| *games > 0)
        .ok_or("preview-work benchmark requires a populated Arcade catalog")?;

    let run_result = (|| -> Result<(Vec<Value>, Vec<Value>, Vec<Value>)> {
        let mut system_entry = Vec::with_capacity(SAMPLES_PER_ROUTE);
        let mut ordinary_scroll = Vec::with_capacity(SAMPLES_PER_ROUTE);
        let mut turbo_scroll = Vec::with_capacity(SAMPLES_PER_ROUTE);
        fs::create_dir_all(output_dir.join("system-entry"))?;
        for sample in 1..=SAMPLES_PER_ROUTE {
            system_entry.push(run_system_entry_sample(
                config,
                &session,
                &output_dir.join("system-entry"),
                "arcade",
                arcade_games,
                1,
                sample,
                SystemEntryInstrumentation::PreviewAttribution,
            )?);
        }
        for sample in 1..=SAMPLES_PER_ROUTE {
            ordinary_scroll.push(run_gui_frame_profile_route_with_pprof(
                config,
                &session,
                &output_dir.join(format!("ordinary-scroll-{sample}")),
                GuiFrameProfileRouteSpec {
                    pmu: false,
                    scroll_duration_ms: SCROLL_DURATION_MS,
                    terminal_checkpoint: Some("terminal-arcade"),
                    pprof_remote_dir: None,
                    pprof_finalization_probe: Duration::ZERO,
                    input_mode: ArcadeRunInputMode::Held,
                    startup_orientation: None,
                    preview_work_attribution: true,
                },
            )?);
        }
        for sample in 1..=SAMPLES_PER_ROUTE {
            turbo_scroll.push(run_gui_frame_profile_route_with_pprof(
                config,
                &session,
                &output_dir.join(format!("turbo-scroll-{sample}")),
                GuiFrameProfileRouteSpec {
                    pmu: false,
                    scroll_duration_ms: SCROLL_DURATION_MS,
                    terminal_checkpoint: Some("terminal-arcade"),
                    pprof_remote_dir: None,
                    pprof_finalization_probe: Duration::ZERO,
                    input_mode: ArcadeRunInputMode::Turbo,
                    startup_orientation: None,
                    preview_work_attribution: true,
                },
            )?);
        }
        Ok((system_entry, ordinary_scroll, turbo_scroll))
    })();
    let restore_result = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let (system_entry, ordinary_scroll, turbo_scroll) = match (run_result, restore_result) {
        (Ok(samples), Ok(())) => samples,
        (Err(error), Ok(())) => return Err(error),
        (Ok(_), Err(error)) => {
            return Err(format!("preview-work launcher restoration failed: {error}").into());
        }
        (Err(run), Err(restore)) => {
            return Err(
                format!("{run}; preview-work launcher restoration failed: {restore}").into(),
            );
        }
    };
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing after preview-work benchmark")?;
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after preview-work benchmark")?;
    if final_manifest != manifest || final_boot_id != boot_id {
        return Err("installed identity changed during preview-work benchmark".into());
    }

    let system_metrics = system_entry
        .iter()
        .map(|sample| sample["preview_work_attribution"].clone())
        .collect::<Vec<_>>();
    let ordinary_metrics = ordinary_scroll
        .iter()
        .map(|sample| sample["preview_work_attribution"].clone())
        .collect::<Vec<_>>();
    let turbo_metrics = turbo_scroll
        .iter()
        .map(|sample| sample["preview_work_attribution"].clone())
        .collect::<Vec<_>>();
    let all_metrics = system_metrics
        .iter()
        .chain(&ordinary_metrics)
        .chain(&turbo_metrics)
        .collect::<Vec<_>>();
    let sum = |field: &str| {
        all_metrics
            .iter()
            .filter_map(|sample| sample.get(field).and_then(Value::as_u64))
            .sum::<u64>()
    };
    let requests = sum("requests");
    let collisions = sum("simultaneous_selected_prefetch_requests");
    let duplicate_work = sum("duplicate_decodes") + sum("repeated_missing_sidecar_probes");
    let measured_work = sum("decodes") + sum("missing_sidecar_probes");
    let collision_rate_pct = if requests == 0 {
        0.0
    } else {
        collisions as f64 * 100.0 / requests as f64
    };
    let duplicate_work_pct = if measured_work == 0 {
        0.0
    } else {
        duplicate_work as f64 * 100.0 / measured_work as f64
    };
    let opportunity_gate_passed = collision_rate_pct >= 5.0 || duplicate_work_pct >= 2.0;
    let selected_entry_ages = system_entry
        .iter()
        .filter_map(|sample| {
            sample
                .pointer("/preview_timing/request_age_us")
                .and_then(Value::as_u64)
        })
        .collect::<Vec<_>>();
    let selected_entry_latency = preview_latency_summary(selected_entry_ages);
    let system_entry_limit_passed = selected_entry_latency["p95"]
        .as_u64()
        .is_some_and(|p95| p95 <= 85_000);
    let summary = json!({
        "schema": "mister-magik-preview-work-attribution-v1",
        "artifact_status": "passed",
        "status": if system_entry_limit_passed { "passed" } else { "failed" },
        "scenario": "preview-work-attribution",
        "production_behavior": "separate selected and prefetch workers",
        "forced_background_catalog": false,
        "sampling": {
            "runs_per_route": SAMPLES_PER_ROUTE,
            "scroll_duration_ms": SCROLL_DURATION_MS,
        },
        "routes": {
            "system_entry": system_metrics,
            "ordinary_scroll": ordinary_metrics,
            "turbo_scroll": turbo_metrics,
        },
        "aggregate": {
            "requests": requests,
            "colliding_requests": collisions,
            "collision_rate_pct": collision_rate_pct,
            "duplicate_decodes": sum("duplicate_decodes"),
            "duplicate_reads": sum("duplicate_reads"),
            "duplicate_resizes": sum("duplicate_resizes"),
            "missing_sidecar_probes": sum("missing_sidecar_probes"),
            "repeated_missing_sidecar_probes": sum("repeated_missing_sidecar_probes"),
            "duplicate_work_pct": duplicate_work_pct,
            "worker_cpu_us": sum("worker_cpu_us"),
            "read_us": sum("read_us"),
            "decode_us": sum("decode_us"),
            "resize_us": sum("resize_us"),
        },
        "opportunity_gate": {
            "passed": opportunity_gate_passed,
            "rule": "duplicate work >=2% or collisions >=5% of requests",
        },
        "system_entry_selected_latency_us": selected_entry_latency,
        "system_entry_limit_us": 85_000,
        "system_entry_limit_passed": system_entry_limit_passed,
        "terminal_samples": {
            "system_entry": system_entry,
            "ordinary_scroll": ordinary_scroll,
            "turbo_scroll": turbo_scroll,
        },
        "manifest": parse_manifest_evidence(&manifest),
        "boot_id": boot_id.trim(),
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    fs::write(
        output_dir.join("report.md"),
        preview_work_attribution_report(&summary)?,
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn preview_work_attribution_report(summary: &Value) -> Result<String> {
    let aggregate = summary
        .get("aggregate")
        .ok_or("preview-work summary has no aggregate")?;
    Ok(format!(
        "# Preview-work attribution\n\nStatus: **{}**\n\n- Requests: {}\n- Selected/prefetch collision rate: {:.2}%\n- Duplicate decodes: {}\n- Repeated missing-sidecar probes: {}\n- Duplicate-work share: {:.2}%\n- Opportunity gate: **{}**\n- System-entry selected-preview p95: {} us\n",
        summary["status"].as_str().unwrap_or("failed"),
        aggregate["requests"].as_u64().unwrap_or(0),
        aggregate["collision_rate_pct"].as_f64().unwrap_or(0.0),
        aggregate["duplicate_decodes"].as_u64().unwrap_or(0),
        aggregate["repeated_missing_sidecar_probes"]
            .as_u64()
            .unwrap_or(0),
        aggregate["duplicate_work_pct"].as_f64().unwrap_or(0.0),
        if summary
            .pointer("/opportunity_gate/passed")
            .and_then(Value::as_bool)
            == Some(true)
        {
            "passed"
        } else {
            "closed"
        },
        summary
            .pointer("/system_entry_selected_latency_us/p95")
            .and_then(Value::as_u64)
            .unwrap_or(0),
    ))
}

#[derive(Clone, Debug)]
struct PreviewWorkSpan {
    generation: u64,
    priority: String,
    key: String,
    started_us: u64,
    queue_age_us: u64,
    ended_us: Option<u64>,
    cache_hit: bool,
    read_us: u64,
    decode_us: u64,
    decode_cpu_us: u64,
    parse_us: u64,
    parse_cpu_us: u64,
    resize_us: u64,
    source: String,
}

fn parse_preview_work_attribution(log: &str) -> Result<Value> {
    const PREFIX: &str = "preview_work_tsv\t";
    let mut spans = BTreeMap::<u64, PreviewWorkSpan>::new();
    let mut missing_sidecar_probes = BTreeMap::<String, u64>::new();
    let mut sidecar_opens = BTreeMap::<String, u64>::new();
    for line in log.lines() {
        let Some(offset) = line.find(PREFIX) else {
            continue;
        };
        let fields = line[offset..].split('\t').collect::<Vec<_>>();
        match fields.get(1).copied() {
            Some("begin") if fields.len() >= 9 => {
                let generation = fields[2].parse::<u64>()?;
                spans.insert(
                    generation,
                    PreviewWorkSpan {
                        generation,
                        priority: fields[3].to_string(),
                        started_us: fields[4].parse()?,
                        queue_age_us: fields[5].parse()?,
                        key: format!("{}|{}|{}", fields[6], fields[7], fields[8]),
                        ended_us: None,
                        cache_hit: false,
                        read_us: 0,
                        decode_us: 0,
                        decode_cpu_us: 0,
                        parse_us: 0,
                        parse_cpu_us: 0,
                        resize_us: 0,
                        source: "incomplete".into(),
                    },
                );
            }
            Some("end") if fields.len() >= 13 => {
                let generation = fields[2].parse::<u64>()?;
                if let Some(span) = spans.get_mut(&generation) {
                    span.ended_us = Some(fields[4].parse()?);
                    span.cache_hit = fields[5] == "1";
                    span.read_us = fields[6].parse()?;
                    span.decode_us = fields[7].parse()?;
                    span.decode_cpu_us = fields[8].parse()?;
                    span.parse_us = fields[9].parse()?;
                    span.parse_cpu_us = fields[10].parse()?;
                    span.resize_us = fields[11].parse()?;
                    span.source = fields[12].to_string();
                }
            }
            Some("sidecar_probe") if fields.get(2) == Some(&"missing") && fields.len() >= 4 => {
                *missing_sidecar_probes
                    .entry(fields[3].to_string())
                    .or_default() += 1;
            }
            Some("sidecar_open") if fields.len() >= 3 => {
                *sidecar_opens.entry(fields[2].to_string()).or_default() += 1;
            }
            _ => {}
        }
    }
    if spans.is_empty() {
        return Err("preview attribution log contains no work spans".into());
    }

    let completed = spans
        .values()
        .filter(|span| span.ended_us.is_some())
        .collect::<Vec<_>>();
    let mut by_key = BTreeMap::<&str, Vec<&PreviewWorkSpan>>::new();
    for span in &completed {
        by_key.entry(span.key.as_str()).or_default().push(*span);
    }
    let mut colliding_requests = BTreeSet::<u64>::new();
    let mut duplicate_work = BTreeSet::<u64>::new();
    for group in by_key.values_mut() {
        group.sort_by_key(|span| span.started_us);
        for (index, current) in group.iter().enumerate() {
            for earlier in &group[..index] {
                if earlier.ended_us.unwrap_or(earlier.started_us) <= current.started_us {
                    continue;
                }
                if earlier.priority != current.priority {
                    colliding_requests.insert(earlier.generation);
                    colliding_requests.insert(current.generation);
                }
                if !earlier.cache_hit && !current.cache_hit {
                    duplicate_work.insert(current.generation);
                }
            }
        }
    }

    let selected_queue = completed
        .iter()
        .filter(|span| span.priority == "selected")
        .map(|span| span.queue_age_us)
        .collect::<Vec<_>>();
    let prefetch_queue = completed
        .iter()
        .filter(|span| span.priority == "prefetch")
        .map(|span| span.queue_age_us)
        .collect::<Vec<_>>();
    let repeated_missing_probes = missing_sidecar_probes
        .values()
        .map(|count| count.saturating_sub(1))
        .sum::<u64>();
    let repeated_sidecar_opens = sidecar_opens
        .values()
        .map(|count| count.saturating_sub(1))
        .sum::<u64>();
    let requests = spans.len() as u64;
    let collisions = colliding_requests.len() as u64;
    Ok(json!({
        "schema": "mister-magik-preview-work-trace-v1",
        "requests": requests,
        "completed_results": completed.len(),
        "incomplete_requests": spans.len().saturating_sub(completed.len()),
        "selected_requests": completed.iter().filter(|span| span.priority == "selected").count(),
        "prefetch_requests": completed.iter().filter(|span| span.priority == "prefetch").count(),
        "cache_hits": completed.iter().filter(|span| span.cache_hit).count(),
        "cache_misses": completed.iter().filter(|span| !span.cache_hit).count(),
        "reads": completed.iter().filter(|span| span.read_us > 0).count(),
        "decodes": completed.iter().filter(|span| span.decode_us > 0 || span.parse_us > 0).count(),
        "resizes": completed.iter().filter(|span| span.resize_us > 0).count(),
        "decoded_cache_insertions": completed.iter().filter(|span| !span.cache_hit && span.source != "failed").count(),
        "simultaneous_selected_prefetch_requests": collisions,
        "collision_rate_pct": if requests == 0 { 0.0 } else { collisions as f64 * 100.0 / requests as f64 },
        "duplicate_decodes": duplicate_work.len(),
        "duplicate_reads": duplicate_work.iter().filter(|generation| spans.get(generation).is_some_and(|span| span.read_us > 0)).count(),
        "duplicate_resizes": duplicate_work.iter().filter(|generation| spans.get(generation).is_some_and(|span| span.resize_us > 0)).count(),
        "missing_sidecar_probes": missing_sidecar_probes.values().sum::<u64>(),
        "repeated_missing_sidecar_probes": repeated_missing_probes,
        "sidecar_opens": sidecar_opens.values().sum::<u64>(),
        "repeated_sidecar_opens": repeated_sidecar_opens,
        "selected_queue_age_us": preview_latency_summary(selected_queue),
        "prefetch_queue_age_us": preview_latency_summary(prefetch_queue),
        "worker_cpu_us": completed.iter().map(|span| span.decode_cpu_us.saturating_add(span.parse_cpu_us)).sum::<u64>(),
        "read_us": completed.iter().map(|span| span.read_us).sum::<u64>(),
        "decode_us": completed.iter().map(|span| span.decode_us.saturating_add(span.parse_us)).sum::<u64>(),
        "resize_us": completed.iter().map(|span| span.resize_us).sum::<u64>(),
        "unique_keys": by_key.len(),
    }))
}

fn preview_latency_summary(mut values: Vec<u64>) -> Value {
    if values.is_empty() {
        return json!({"samples": 0, "p50": Value::Null, "p95": Value::Null, "max": Value::Null});
    }
    values.sort_unstable();
    json!({
        "samples": values.len(),
        "p50": median_u64(&values),
        "p95": percentile_nearest_rank(&values, 95),
        "max": values.last().copied(),
    })
}

fn gui_profile_phase_marker_us(profile: &Value, phase: &str, event: &str) -> Result<u64> {
    profile
        .get("phase_markers")
        .and_then(Value::as_array)
        .and_then(|markers| {
            markers.iter().find_map(|marker| {
                (marker.get("phase").and_then(Value::as_str) == Some(phase)
                    && marker.get("event").and_then(Value::as_str) == Some(event))
                .then(|| marker.get("monotonic_us").and_then(Value::as_u64))
                .flatten()
            })
        })
        .ok_or_else(|| format!("GUI profile is missing {phase} {event}").into())
}

fn summarize_arcade_velocity_scroll(
    output_dir: &Path,
    route: &Value,
    telemetry: &[Value],
    display_mode: &str,
    expected_duration_ms: u64,
) -> Result<Value> {
    use std::fmt::Write as _;

    let profile = gui_profile_payload(route)?;
    let (screen_orientation, ending_screen_orientation) =
        arcade_velocity_scroll_orientations(route)?;
    let minimum_physical_fps = arcade_velocity_scroll_minimum_fps(display_mode)?;
    let phase_started_us = gui_profile_phase_marker_us(profile, "arcade-scroll", "started")?;
    let phase_presented_us = gui_profile_phase_marker_us(profile, "arcade-scroll", "presented")?;
    let phase_duration_us = phase_presented_us
        .checked_sub(phase_started_us)
        .filter(|duration| *duration > 0)
        .ok_or("Arcade velocity-scroll phase timestamps are not increasing")?;
    let scroll_profile_frames = profile
        .get("frames")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|frame| {
            frame.get("phase").and_then(Value::as_str) == Some("arcade-scroll")
                && frame
                    .get("monotonic_us")
                    .and_then(Value::as_u64)
                    .is_some_and(|timestamp| {
                        timestamp >= phase_started_us && timestamp <= phase_presented_us
                    })
                && frame.pointer("/presentation/active_sequence").is_some()
        })
        .collect::<Vec<_>>();
    if scroll_profile_frames.len() < 2 {
        return Err("Arcade velocity-scroll profile contains fewer than two frames".into());
    }
    let first_profile_frame = scroll_profile_frames[0];
    let last_profile_frame = scroll_profile_frames[scroll_profile_frames.len() - 1];
    let profile_elapsed_us = last_profile_frame["monotonic_us"]
        .as_u64()
        .unwrap_or(0)
        .saturating_sub(first_profile_frame["monotonic_us"].as_u64().unwrap_or(0));
    let first_owned = u32::try_from(
        first_profile_frame["presentation"]["owned_vblank_count"]
            .as_u64()
            .unwrap_or(0),
    )
    .unwrap_or(0);
    let last_owned = u32::try_from(
        last_profile_frame["presentation"]["owned_vblank_count"]
            .as_u64()
            .unwrap_or(0),
    )
    .unwrap_or(0);
    let owned_delta = u64::from(last_owned.wrapping_sub(first_owned));
    let refresh_period_us = profile_elapsed_us
        .checked_add(owned_delta / 2)
        .and_then(|elapsed| elapsed.checked_div(owned_delta))
        .filter(|period| *period > 0)
        .ok_or("Arcade velocity-scroll profile has no physical refresh period")?;
    let frame_values = scroll_profile_frames
        .iter()
        .map(|frame| {
            json!({
                "frame": frame["frame"],
                "completion_monotonic_us": frame["monotonic_us"],
                "vsync_period_us": refresh_period_us,
                "main_present_sequence": frame["presentation"]["active_sequence"],
                "main_present_drop_count": frame["presentation"]["latch_drop_count"],
            })
        })
        .collect::<Vec<_>>();
    let frames = frame_values.iter().collect::<Vec<_>>();
    let physical_refresh =
        authoritative_physical_refresh(1, telemetry, &frames, refresh_period_us)?;
    let completion_times = frames
        .iter()
        .map(|frame| frame_u64(frame, "completion_monotonic_us"))
        .collect::<Vec<_>>();
    let completion_elapsed_us = completion_times
        .last()
        .copied()
        .unwrap_or(0)
        .saturating_sub(completion_times[0]);
    let mut completion_intervals = completion_times
        .windows(2)
        .map(|pair| pair[1].saturating_sub(pair[0]))
        .collect::<Vec<_>>();
    completion_intervals.sort_unstable();
    let sequence_gaps = frames
        .windows(2)
        .filter(|pair| {
            let previous = frame_u16(pair[0], "main_present_sequence");
            let current = frame_u16(pair[1], "main_present_sequence");
            previous == 0 || current == 0 || !presentation_sequence_is_contiguous(previous, current)
        })
        .count();
    let latch_drop_delta = frame_u16(frames[frames.len() - 1], "main_present_drop_count")
        .wrapping_sub(frame_u16(frames[0], "main_present_drop_count"));
    let submitted_fps = if completion_elapsed_us == 0 {
        0.0
    } else {
        frames.len().saturating_sub(1) as f64 * 1_000_000.0 / completion_elapsed_us as f64
    };
    let physical_fps = physical_refresh
        .get("unique_fps")
        .and_then(Value::as_f64)
        .unwrap_or(0.0);
    let dropped_frames = physical_refresh
        .get("dropped_frames")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX);
    let ownership_losses = physical_refresh
        .pointer("/presentation_telemetry/ownership_loss_delta")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX);
    let selection_indices = route
        .get("scroll_snapshots")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|snapshot| {
            snapshot
                .pointer("/semantic/selected_index")
                .and_then(Value::as_u64)
        })
        .collect::<Vec<_>>();
    let first_selected = route
        .pointer("/arcade_entered/semantic/selected_index")
        .and_then(Value::as_u64)
        .or_else(|| selection_indices.first().copied())
        .unwrap_or(u64::MAX);
    let final_selected = route
        .pointer("/settled_arcade/semantic/selected_index")
        .and_then(Value::as_u64)
        .or_else(|| selection_indices.last().copied())
        .unwrap_or(u64::MAX);
    let selection_changes = selection_indices
        .windows(2)
        .filter(|pair| pair[0] != pair[1])
        .count();
    let mut distinct_selections = selection_indices.clone();
    distinct_selections.sort_unstable();
    distinct_selections.dedup();
    let profile_selection_indices = scroll_profile_frames
        .iter()
        .filter_map(|frame| frame.get("crt_backdrop_selected").and_then(Value::as_u64))
        .collect::<Vec<_>>();
    let profile_selection_changes = profile_selection_indices
        .windows(2)
        .filter(|pair| pair[0] != pair[1])
        .count();
    let mut distinct_profile_selections = profile_selection_indices.clone();
    distinct_profile_selections.sort_unstable();
    distinct_profile_selections.dedup();
    let exact_cache_frames = scroll_profile_frames
        .iter()
        .filter(|frame| {
            frame
                .get("crt_backdrop_cache_state")
                .and_then(Value::as_str)
                == Some("exact")
        })
        .count();
    let distinct_transition_ids = scroll_profile_frames
        .iter()
        .filter_map(|frame| {
            frame
                .get("crt_backdrop_transition_id")
                .and_then(Value::as_u64)
        })
        .filter(|id| *id != 0)
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let mut foreground_work_us = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "wall_us").saturating_sub(frame_u64(frame, "vsync_us")))
        .collect::<Vec<_>>();
    foreground_work_us.sort_unstable();
    let mut backdrop_prepare_us = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_prepare_us"))
        .collect::<Vec<_>>();
    backdrop_prepare_us.sort_unstable();
    let mut backdrop_blend_us = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_blend_us"))
        .collect::<Vec<_>>();
    backdrop_blend_us.sort_unstable();
    let mut backdrop_copy_us = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_copy_us"))
        .collect::<Vec<_>>();
    backdrop_copy_us.sort_unstable();
    let mut backdrop_list_overlay_us = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_list_overlay_us"))
        .collect::<Vec<_>>();
    backdrop_list_overlay_us.sort_unstable();
    let backdrop_list_restore_pixels = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_list_restore_pixels"))
        .max()
        .unwrap_or(0);
    let backdrop_list_foreground_pixels = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_list_foreground_pixels"))
        .max()
        .unwrap_or(0);
    let active_fade_frames = scroll_profile_frames
        .iter()
        .filter(|frame| frame.get("crt_backdrop_active").and_then(Value::as_bool) == Some(true))
        .count();
    let distinct_alpha_buckets = scroll_profile_frames
        .iter()
        .filter_map(|frame| {
            frame
                .get("crt_backdrop_alpha_bucket")
                .and_then(Value::as_u64)
        })
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let backdrop_prepare_pixels = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_prepare_pixels"))
        .max()
        .unwrap_or(0);
    let backdrop_blend_pixels = scroll_profile_frames
        .iter()
        .map(|frame| frame_u64(frame, "crt_backdrop_blend_pixels"))
        .max()
        .unwrap_or(0);
    let dropped_profile_frame_records = profile
        .get("dropped_frame_records")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX);
    let dropped_worker_profiles = profile
        .pointer("/worker_profiles/dropped_profiles")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let terminal_scanout_authoritative = arcade_velocity_scroll_terminal_is_authoritative(route);
    let mut quality_failures = Vec::new();
    if phase_duration_us < expected_duration_ms * 1_000 {
        quality_failures.push("scroll-window-shorter-than-requested-duration");
    }
    if physical_fps < minimum_physical_fps {
        quality_failures.push(arcade_velocity_scroll_fps_failure(minimum_physical_fps));
    }
    if let Some(limit_us) = arcade_velocity_scroll_foreground_p99_limit_us(display_mode)
        && percentile_99(&foreground_work_us) >= limit_us
    {
        quality_failures.push("foreground-work-p99-over-route-budget");
    }
    if dropped_frames != 0 {
        quality_failures.push("physical-dropped-frames");
    }
    if ownership_losses != 0 {
        quality_failures.push("presentation-ownership-loss");
    }
    if physical_refresh
        .pointer("/presentation_telemetry/endpoints_settled")
        .and_then(Value::as_bool)
        != Some(true)
    {
        quality_failures.push("presentation-endpoints-not-settled");
    }
    if latch_drop_delta != 0 {
        quality_failures.push("latch-drops");
    }
    if sequence_gaps != 0 {
        quality_failures.push("presentation-sequence-gaps");
    }
    if dropped_profile_frame_records != 0 {
        quality_failures.push("profile-frame-records-dropped");
    }
    if dropped_worker_profiles != 0 {
        quality_failures.push("worker-profile-records-dropped");
    }
    if selection_changes == 0 || distinct_selections.len() < 2 {
        quality_failures.push("arcade-selection-did-not-advance");
    }
    if screen_orientation != ending_screen_orientation {
        quality_failures.push("screen-orientation-changed");
    }
    if !terminal_scanout_authoritative {
        quality_failures.push("terminal-capture-not-authoritative-scanout");
    }
    let quality_status = if quality_failures.is_empty() {
        "passed"
    } else {
        "failed"
    };
    let sample_refs = telemetry.iter().collect::<Vec<_>>();
    let frame_profile_artifact = if output_dir.join("frame-profile.json").is_file() {
        "frame-profile.json"
    } else {
        "profile.json"
    };
    let summary = json!({
        "schema": "mister-magik-arcade-velocity-scroll-v1",
        "quality_status": quality_status,
        "quality_failures": quality_failures,
        "display_mode": display_mode,
        "screen_orientation": screen_orientation,
        "ending_screen_orientation": ending_screen_orientation,
        "hold_duration_ms": expected_duration_ms,
        "phase_duration_us": phase_duration_us,
        "frames": frames.len(),
        "submitted_fps": submitted_fps,
        "minimum_physical_fps": minimum_physical_fps,
        "physical_refresh": physical_refresh,
        "latch_drop_delta": latch_drop_delta,
        "sequence_gaps": sequence_gaps,
        "profiling_record_loss": {
            "frame_records": dropped_profile_frame_records,
            "worker_profiles": dropped_worker_profiles,
        },
        "selection": {
            "first": first_selected,
            "final": final_selected,
            "changes": selection_changes,
            "distinct": distinct_selections.len(),
            "snapshots": selection_indices.len(),
            "profile_records": scroll_profile_frames.len(),
            "profile_changes": profile_selection_changes,
            "profile_distinct": distinct_profile_selections.len(),
            "exact_cache_frames": exact_cache_frames,
            "distinct_backdrop_transitions": distinct_transition_ids,
        },
        "completion_intervals_us": {
            "median": median_u64(&completion_intervals).unwrap_or(0),
            "p99": percentile_99(&completion_intervals),
            "max": completion_intervals.last().copied().unwrap_or(0),
        },
        "foreground_work_us": percentile_summary(&foreground_work_us),
        "crt_backdrop_prepare": {
            "timing_us": percentile_summary(&backdrop_prepare_us),
            "max_pixels": backdrop_prepare_pixels,
        },
        "crt_backdrop_blend": {
            "timing_us": percentile_summary(&backdrop_blend_us),
            "max_pixels": backdrop_blend_pixels,
        },
        "crt_backdrop_copy": {
            "timing_us": percentile_summary(&backdrop_copy_us),
        },
        "crt_backdrop_list_overlay": {
            "timing_us": percentile_summary(&backdrop_list_overlay_us),
            "max_restored_pixels": backdrop_list_restore_pixels,
            "max_foreground_pixels": backdrop_list_foreground_pixels,
        },
        "crt_backdrop_fade_activity": {
            "active_frames": active_fade_frames,
            "distinct_alpha_buckets": distinct_alpha_buckets,
        },
        "measurement": {
            "telemetry_analytics_mode": "off",
            "software_cadence_source": "gui-presentation-stamps",
            "physical_cadence_source": "fpga-owned-vblank-telemetry",
            "foreground_phase_timing": "not-collected-to-avoid-observer-effect",
            "terminal_scanout_authoritative": terminal_scanout_authoritative,
        },
        "status_publishing": status_publishing_summary(&[], &sample_refs),
        "terminal_checkpoint": route.get("terminal_checkpoint").cloned().unwrap_or(Value::Null),
        "artifacts": {
            "telemetry": "telemetry.jsonl",
            "profile": frame_profile_artifact,
            "terminal_png": "terminal-arcade.png",
            "terminal_metadata": "terminal-arcade.json",
        },
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    let mut report = String::from("# Arcade velocity-scroll benchmark\n\n");
    writeln!(report, "Quality: **{}**\n", quality_status)?;
    writeln!(report, "- Active mode: `{display_mode}`")?;
    writeln!(report, "- Screen orientation: `{screen_orientation}`")?;
    writeln!(report, "- Fixed hold: {expected_duration_ms} ms")?;
    writeln!(report, "- Physical FPS: {:.3}", physical_fps)?;
    writeln!(report, "- Minimum physical FPS: {minimum_physical_fps:.1}")?;
    writeln!(report, "- Physical dropped frames: {dropped_frames}")?;
    writeln!(report, "- Latch drops: {latch_drop_delta}")?;
    writeln!(report, "- Sequence gaps: {sequence_gaps}")?;
    writeln!(
        report,
        "- Profiling record loss (frames / workers): {dropped_profile_frame_records} / {dropped_worker_profiles}"
    )?;
    writeln!(report, "- Submitted FPS: {:.3}", submitted_fps)?;
    writeln!(report, "- Telemetry analytics: off (observer-free)")?;
    writeln!(
        report,
        "- Selection changes: {selection_changes}; profile changes: {profile_selection_changes}; profile distinct: {}; exact-cache frames: {exact_cache_frames}; backdrop transitions: {distinct_transition_ids}\n",
        distinct_profile_selections.len(),
    )?;
    writeln!(
        report,
        "- Foreground work (p95 / p99 / max): {} / {} / {} us",
        percentile_95(&foreground_work_us),
        percentile_99(&foreground_work_us),
        foreground_work_us.last().copied().unwrap_or(0),
    )?;
    writeln!(
        report,
        "- Backdrop prepare (p95 / p99 / max): {} / {} / {} us; max pixels {}",
        percentile_95(&backdrop_prepare_us),
        percentile_99(&backdrop_prepare_us),
        backdrop_prepare_us.last().copied().unwrap_or(0),
        backdrop_prepare_pixels,
    )?;
    writeln!(
        report,
        "- Backdrop blend (p95 / p99 / max): {} / {} / {} us; max pixels {}",
        percentile_95(&backdrop_blend_us),
        percentile_99(&backdrop_blend_us),
        backdrop_blend_us.last().copied().unwrap_or(0),
        backdrop_blend_pixels,
    )?;
    writeln!(
        report,
        "- Backdrop copy (p95 / p99 / max): {} / {} / {} us",
        percentile_95(&backdrop_copy_us),
        percentile_99(&backdrop_copy_us),
        backdrop_copy_us.last().copied().unwrap_or(0),
    )?;
    writeln!(
        report,
        "- List overlay (p95 / p99 / max): {} / {} / {} us; max restored / foreground pixels: {} / {}",
        percentile_95(&backdrop_list_overlay_us),
        percentile_99(&backdrop_list_overlay_us),
        backdrop_list_overlay_us.last().copied().unwrap_or(0),
        backdrop_list_restore_pixels,
        backdrop_list_foreground_pixels,
    )?;
    writeln!(
        report,
        "- Fade activity: {} active frames; {} distinct alpha buckets",
        active_fade_frames, distinct_alpha_buckets,
    )?;
    fs::write(output_dir.join("report.md"), report)?;
    Ok(summary)
}

fn arcade_velocity_scroll_terminal_is_authoritative(route: &Value) -> bool {
    route
        .pointer("/terminal_checkpoint/capture/authoritative_scanout")
        .and_then(Value::as_bool)
        == Some(true)
        && route
            .pointer("/terminal_checkpoint/capture_source")
            .and_then(Value::as_str)
            == Some("fpga-latched-scanout-slots")
}

fn arcade_velocity_scroll_orientations(route: &Value) -> Result<(&str, &str)> {
    let started = route
        .pointer("/arcade_entered/semantic/screen_orientation")
        .and_then(Value::as_str)
        .filter(|orientation| !orientation.is_empty())
        .ok_or("Arcade velocity-scroll entry snapshot has no screen orientation")?;
    let ended = route
        .pointer("/settled_arcade/semantic/screen_orientation")
        .and_then(Value::as_str)
        .filter(|orientation| !orientation.is_empty())
        .ok_or("Arcade velocity-scroll terminal snapshot has no screen orientation")?;
    Ok((started, ended))
}

fn arcade_velocity_scroll_minimum_fps(display_mode: &str) -> Result<f64> {
    if display_mode.ends_with("p60") {
        Ok(59.9)
    } else if display_mode.ends_with("p50") {
        Ok(49.9)
    } else {
        Err(format!(
            "Arcade velocity-scroll benchmark requires a resolved p50 or p60 mode, found {display_mode}"
        )
        .into())
    }
}

fn arcade_velocity_scroll_fps_failure(minimum_physical_fps: f64) -> &'static str {
    if minimum_physical_fps < 59.0 {
        "physical-fps-below-49.9"
    } else {
        "physical-fps-below-59.9"
    }
}

fn arcade_velocity_scroll_foreground_p99_limit_us(display_mode: &str) -> Option<u64> {
    match display_mode {
        "crt-240p60" => Some(13_300),
        "crt-288p50" => Some(15_900),
        _ => None,
    }
}

fn percentile_summary(values: &[u64]) -> Value {
    json!({
        "p95": percentile_95(values),
        "p99": percentile_99(values),
        "max": values.last().copied().unwrap_or(0),
    })
}

fn wait_for_remote_text(
    session: &Session,
    path: &str,
    timeout: Duration,
    label: &str,
) -> Result<String> {
    let started = Instant::now();
    loop {
        if let Some(text) = remote_read(session, path) {
            return Ok(text);
        }
        if started.elapsed() >= timeout {
            return Err(format!("timed out waiting for {label}").into());
        }
        thread::sleep(Duration::from_millis(20));
    }
}

fn wait_for_gui_profile_file(
    config: &NativeDeviceConfig,
    session: &Session,
    nonce: &str,
    path: &str,
    timeout: Duration,
    label: &str,
) -> Result<()> {
    let started = Instant::now();
    let mut next_keepalive = Instant::now();
    loop {
        let probe = exec(session, &format!("test -s {}", sh(path)), true)?;
        if probe.rc == 0 {
            return Ok(());
        }
        if started.elapsed() >= timeout {
            return Err(format!("timed out waiting for {label}").into());
        }
        if Instant::now() >= next_keepalive {
            launcher_automation::snapshot(config, nonce)
                .map_err(|error| format!("keep GUI profiling automation session alive: {error}"))?;
            next_keepalive = Instant::now() + Duration::from_secs(1);
        }
        thread::sleep(Duration::from_millis(20));
    }
}

fn validate_gui_profile_route(profile: &Value, pmu: bool) -> Result<()> {
    if profile.get("schema").and_then(Value::as_str) != Some("mister-magik-gui-profiling-window-v1")
        || !matches!(
            profile.get("state").and_then(Value::as_str),
            Some("complete" | "failed")
        )
        || !profile.get("failure").is_none_or(Value::is_null)
        || profile.get("pmu_requested").and_then(Value::as_bool) != Some(pmu)
        || profile.get("pmu_valid").and_then(Value::as_bool) != Some(true)
    {
        return Err("GUI profiling route returned invalid window evidence".into());
    }
    let markers = profile
        .get("phase_markers")
        .and_then(Value::as_array)
        .ok_or("GUI profiling route has no phase markers")?;
    for phase in ["arcade-scroll", "settled-arcade"] {
        for event in ["started", "presented"] {
            if !markers.iter().any(|marker| {
                marker.get("phase").and_then(Value::as_str) == Some(phase)
                    && marker.get("event").and_then(Value::as_str) == Some(event)
            }) {
                return Err(format!("GUI profiling route is missing {phase} {event}").into());
            }
        }
    }
    Ok(())
}

const GUI_PROFILE_PHASES: [&str; 2] = ["arcade-scroll", "settled-arcade"];

fn gui_profile_payload(route: &Value) -> Result<&Value> {
    let profile = route
        .get("profile")
        .ok_or("GUI frame attribution arm has no profile payload")?;
    validate_gui_profile_route(
        profile,
        route.get("pmu_requested").and_then(Value::as_bool) == Some(true),
    )?;
    Ok(profile)
}

fn gui_phase_wall_times(profile: &Value) -> Result<Value> {
    let markers = profile["phase_markers"]
        .as_array()
        .ok_or("GUI profile phase markers are missing")?;
    let mut result = serde_json::Map::new();
    for phase in GUI_PROFILE_PHASES {
        let marker_time = |event: &str| {
            markers.iter().find_map(|marker| {
                (marker["phase"].as_str() == Some(phase) && marker["event"].as_str() == Some(event))
                    .then(|| marker["monotonic_us"].as_u64())
                    .flatten()
            })
        };
        let started = marker_time("started")
            .ok_or_else(|| format!("GUI profile is missing {phase} start time"))?;
        let presented = marker_time("presented")
            .ok_or_else(|| format!("GUI profile is missing {phase} presentation time"))?;
        result.insert(
            phase.into(),
            json!({
                "started_monotonic_us": started,
                "presented_monotonic_us": presented,
                "wall_time_us": presented.saturating_sub(started),
            }),
        );
    }
    Ok(Value::Object(result))
}

fn gui_profile_duration_us(profile: &Value) -> Result<u64> {
    let started = profile["measurement_started_at_us"]
        .as_u64()
        .ok_or("GUI profile has no measurement start")?;
    let ended = profile["measurement_ended_at_us"]
        .as_u64()
        .ok_or("GUI profile has no measurement end")?;
    Ok(ended.saturating_sub(started))
}

fn gui_counter_ratio(numerator: u64, denominator: u64) -> f64 {
    if denominator == 0 {
        0.0
    } else {
        numerator as f64 / denominator as f64
    }
}

#[derive(Clone, Copy, Default)]
struct GuiPmuCounters {
    cycles: u64,
    instructions: u64,
    speculative_instructions: u64,
    neon_instructions: u64,
    neon_clock_cycles: u64,
    data_dependent_stall_cycles: u64,
    l1d_accesses: u64,
    l1d_refills: u64,
    branches: u64,
    branch_mispredicts: u64,
}

impl GuiPmuCounters {
    fn add_record(&mut self, record: &Value) {
        let counters = &record["counters"]["counters"];
        self.cycles = self
            .cycles
            .saturating_add(counters["cycles"].as_u64().unwrap_or(0));
        self.instructions = self
            .instructions
            .saturating_add(counters["instructions"].as_u64().unwrap_or(0));
        self.speculative_instructions = self
            .speculative_instructions
            .saturating_add(counters["speculative-instructions"].as_u64().unwrap_or(0));
        self.neon_instructions = self
            .neon_instructions
            .saturating_add(counters["neon-instructions"].as_u64().unwrap_or(0));
        self.neon_clock_cycles = self
            .neon_clock_cycles
            .saturating_add(counters["neon-clock-cycles"].as_u64().unwrap_or(0));
        self.data_dependent_stall_cycles = self.data_dependent_stall_cycles.saturating_add(
            counters["data-dependent-stall-cycles"]
                .as_u64()
                .unwrap_or(0),
        );
        self.l1d_accesses = self.l1d_accesses.saturating_add(counter_value(
            counters,
            "l1d-accesses",
            "l1d_accesses",
        ));
        self.l1d_refills =
            self.l1d_refills
                .saturating_add(counter_value(counters, "l1d-refills", "l1d_refills"));
        self.branches = self
            .branches
            .saturating_add(counters["branches"].as_u64().unwrap_or(0));
        self.branch_mispredicts = self.branch_mispredicts.saturating_add(counter_value(
            counters,
            "branch-mispredicts",
            "branch_mispredicts",
        ));
    }

    fn summary(self, frame_count: usize) -> Value {
        json!({
            "cycles": self.cycles,
            "instructions": self.instructions,
            "speculative_instructions": self.speculative_instructions,
            "neon_instructions": self.neon_instructions,
            "neon_clock_cycles": self.neon_clock_cycles,
            "data_dependent_stall_cycles": self.data_dependent_stall_cycles,
            "l1d_accesses": self.l1d_accesses,
            "l1d_refills": self.l1d_refills,
            "branches": self.branches,
            "branch_mispredicts": self.branch_mispredicts,
            "cycles_per_frame": gui_counter_ratio(self.cycles, frame_count as u64),
            "instructions_per_cycle": gui_counter_ratio(self.instructions, self.cycles),
            "speculative_instructions_per_cycle": gui_counter_ratio(self.speculative_instructions, self.cycles),
            "neon_instruction_share": gui_counter_ratio(self.neon_instructions, self.speculative_instructions),
            "neon_instructions_per_active_cycle": gui_counter_ratio(self.neon_instructions, self.neon_clock_cycles),
            "neon_clock_duty": gui_counter_ratio(self.neon_clock_cycles, self.cycles),
            "data_dependent_stall_ratio": gui_counter_ratio(self.data_dependent_stall_cycles, self.cycles),
            "l1d_refill_ratio": gui_counter_ratio(self.l1d_refills, self.l1d_accesses),
            "branch_mispredict_ratio": gui_counter_ratio(self.branch_mispredicts, self.branches),
        })
    }
}

fn counter_value(counters: &Value, name: &str, legacy_name: &str) -> u64 {
    counters[name]
        .as_u64()
        .or_else(|| counters[legacy_name].as_u64())
        .unwrap_or(0)
}

fn gui_pmu_summary(profile: &Value) -> Result<Value> {
    let thread_profile = &profile["thread_profile"];
    if thread_profile["enabled"].as_bool() != Some(true)
        || !thread_profile["failure"].is_null()
        || thread_profile["dropped_spans"].as_u64() != Some(0)
    {
        return Err("GUI PMU thread profile is incomplete".into());
    }
    let records = thread_profile["records"]
        .as_array()
        .filter(|records| !records.is_empty())
        .ok_or("GUI PMU thread profile contains no spans")?;
    let mut total = GuiPmuCounters::default();
    let mut phases = BTreeMap::<String, GuiPmuCounters>::new();
    for record in records {
        total.add_record(record);
        if let Some(name) = record["name"].as_str() {
            phases
                .entry(name.to_owned())
                .or_default()
                .add_record(record);
        }
    }
    let frame_count = profile["frames"]
        .as_array()
        .map_or(0, |frames| frames.len());
    let phases = phases
        .into_iter()
        .map(|(name, counters)| (name, counters.summary(frame_count)))
        .collect::<serde_json::Map<_, _>>();
    Ok(json!({
        "frame_count": frame_count,
        "total": total.summary(frame_count),
        "spans": phases,
    }))
}

fn gui_copy_amplification(profile: &Value) -> Result<Value> {
    let frames = profile["frames"]
        .as_array()
        .ok_or("GUI profile has no frame records")?;
    let mut damage_bytes = 0_u64;
    let mut invalid_bytes = 0_u64;
    let mut catchup_bytes = 0_u64;
    let mut copied_rectangles = 0_u64;
    let mut full_copies = 0_u64;
    for frame in frames {
        if let Some(rectangles) = frame["slint_damage_rects"].as_array() {
            for rectangle in rectangles {
                let Some(values) = rectangle.as_array() else {
                    continue;
                };
                if values.len() == 4 {
                    let width = values[2].as_u64().unwrap_or(0);
                    let height = values[3].as_u64().unwrap_or(0);
                    damage_bytes =
                        damage_bytes.saturating_add(width.saturating_mul(height).saturating_mul(2));
                }
            }
        }
        invalid_bytes =
            invalid_bytes.saturating_add(frame["latch"]["invalid_bytes"].as_u64().unwrap_or(0));
        catchup_bytes =
            catchup_bytes.saturating_add(frame["latch"]["catchup_bytes"].as_u64().unwrap_or(0));
        copied_rectangles = copied_rectangles
            .saturating_add(frame["latch"]["copied_rectangles"].as_u64().unwrap_or(0));
        full_copies = full_copies.saturating_add(u64::from(
            frame["latch"]["full_copy"].as_bool() == Some(true),
        ));
    }
    Ok(json!({
        "slint_damage_bytes": damage_bytes,
        "invalid_bytes": invalid_bytes,
        "catchup_bytes": catchup_bytes,
        "copied_rectangles": copied_rectangles,
        "full_copies": full_copies,
        "invalid_to_damage_ratio": gui_counter_ratio(invalid_bytes, damage_bytes),
        "catchup_to_damage_ratio": gui_counter_ratio(catchup_bytes, damage_bytes),
        "total_copy_to_damage_ratio": gui_counter_ratio(invalid_bytes.saturating_add(catchup_bytes), damage_bytes),
    }))
}

fn gui_presentation_summary(profile: &Value) -> Result<Value> {
    let frames = profile["frames"]
        .as_array()
        .ok_or("GUI profile has no frame records")?;
    let mut repeated_vblanks = 0_u64;
    let mut latch_drops = 0_u64;
    let mut ownership_losses = 0_u64;
    let mut sequence_gaps = 0_u64;
    let mut outliers = Vec::new();
    let mut previous: Option<&Value> = None;
    for frame in frames {
        if frame.get("presentation").is_none() {
            continue;
        }
        if let Some(before) = previous {
            let same_phase = before["phase"].as_str() == frame["phase"].as_str();
            let active_phase = matches!(
                frame["phase"].as_str(),
                Some("home-pan-right" | "home-pan-left" | "arcade-scroll")
            );
            if same_phase && active_phase {
                let counter_delta = |name: &str| {
                    frame["presentation"][name]
                        .as_u64()
                        .unwrap_or(0)
                        .saturating_sub(before["presentation"][name].as_u64().unwrap_or(0))
                };
                let repeated_delta = counter_delta("repeated_vblank_count");
                let latch_delta = counter_delta("latch_drop_count");
                let ownership_delta = counter_delta("ownership_loss_count");
                repeated_vblanks = repeated_vblanks.saturating_add(repeated_delta);
                latch_drops = latch_drops.saturating_add(latch_delta);
                ownership_losses = ownership_losses.saturating_add(ownership_delta);
                let before_sequence = before["presentation"]["active_sequence"]
                    .as_u64()
                    .unwrap_or(0) as u16;
                let sequence = frame["presentation"]["active_sequence"]
                    .as_u64()
                    .unwrap_or(0) as u16;
                if sequence != before_sequence.wrapping_add(1) {
                    sequence_gaps = sequence_gaps.saturating_add(1);
                }
                let gap_us = frame["monotonic_us"]
                    .as_u64()
                    .unwrap_or(0)
                    .saturating_sub(before["monotonic_us"].as_u64().unwrap_or(0));
                if gap_us > 25_000 || repeated_delta > 0 {
                    outliers.push(json!({
                        "phase": frame["phase"],
                        "frame": frame["frame"],
                        "inter_frame_gap_us": gap_us,
                        "physical_repeated_vblanks": repeated_delta,
                        "latch_drops": latch_delta,
                    }));
                }
            }
        }
        previous = Some(frame);
    }
    let quality_status =
        if repeated_vblanks == 0 && latch_drops == 0 && ownership_losses == 0 && sequence_gaps == 0
        {
            "passed"
        } else {
            "failed"
        };
    Ok(json!({
        "quality_status": quality_status,
        "physical_repeated_vblanks": repeated_vblanks,
        "latch_drops": latch_drops,
        "ownership_losses": ownership_losses,
        "sequence_gaps": sequence_gaps,
        "phase_outliers": outliers,
    }))
}

fn summarize_gui_frame_attribution(
    control_route: &Value,
    pmu_route: &Value,
    streamline_route: &Value,
) -> Result<Value> {
    let control = gui_profile_payload(control_route)?;
    let pmu = gui_profile_payload(pmu_route)?;
    let streamline = gui_profile_payload(streamline_route)?;
    let control_duration = gui_profile_duration_us(control)?;
    let pmu_duration = gui_profile_duration_us(pmu)?;
    let streamline_duration = gui_profile_duration_us(streamline)?;
    Ok(json!({
        "artifact_validity": "passed",
        "performance_authority": "unprofiled-control",
        "control": {
            "duration_us": control_duration,
            "phase_wall_times": gui_phase_wall_times(control)?,
            "copy_amplification": gui_copy_amplification(control)?,
            "presentation": gui_presentation_summary(control)?,
        },
        "pmu": {
            "duration_us": pmu_duration,
            "phase_wall_times": gui_phase_wall_times(pmu)?,
            "counters": gui_pmu_summary(pmu)?,
            "copy_amplification": gui_copy_amplification(pmu)?,
        },
        "streamline": {
            "duration_us": streamline_duration,
            "phase_wall_times": gui_phase_wall_times(streamline)?,
            "copy_amplification": gui_copy_amplification(streamline)?,
        },
        "observer_deltas": {
            "pmu_duration_delta_us": signed_measurement_delta(Some(pmu_duration), Some(control_duration)),
            "streamline_duration_delta_us": signed_measurement_delta(Some(streamline_duration), Some(control_duration)),
        },
        "counter_interpretation": "PMU and Streamline are attribution-only; physical presentation counters from the control arm qualify cadence",
    }))
}

fn modal_input_action(
    config: &NativeDeviceConfig,
    nonce: &str,
    action: AutomationAction,
) -> Result<u64> {
    let detail = launcher_automation::send_action(config, nonce, &action)?;
    let value: Value = serde_json::from_str(&detail)?;
    let sequence = value
        .get("action_sequence")
        .and_then(Value::as_u64)
        .ok_or("modal input action has no sequence")?;
    launcher_automation::await_presented(config, nonce, sequence, 3_000)?;
    Ok(sequence)
}

fn wait_modal_input_snapshot(
    config: &NativeDeviceConfig,
    nonce: &str,
    predicate: impl Fn(&Value) -> bool,
    label: &str,
) -> Result<Value> {
    let started = Instant::now();
    let timeout = Duration::from_secs(5);
    loop {
        let snapshot = launcher_automation::snapshot(config, nonce)?;
        if predicate(&snapshot) {
            return Ok(snapshot);
        }
        if started.elapsed() >= timeout {
            return Err(format!(
                "modal input verification timed out waiting for {label}; final snapshot={snapshot}"
            )
            .into());
        }
        thread::sleep(Duration::from_millis(20));
    }
}

fn modal_semantic<'a>(snapshot: &'a Value, field: &str) -> Option<&'a Value> {
    snapshot.pointer(&format!("/semantic/{field}"))
}

fn verify_installed_modal_input(config: &NativeDeviceConfig, output_dir: &Path) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    fs::create_dir_all(output_dir)?;
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development platform manifest is missing")?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable")?
        .trim()
        .to_string();
    let mut nonce: Option<String> = None;
    let run_result = (|| -> Result<Value> {
        exec_checked(
            &session,
            "modal input isolated fixture",
            &modal_input_prepare_command(),
        )?;
        restart_launcher_with_one_shot_env(
            &session,
            LauncherRestartOptions {
                env_vars: modal_input_launcher_env(),
                timeout_secs: 45,
                remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
                ..LauncherRestartOptions::default()
            },
        )?;
        let status = read_launcher_status(&session)?;
        if status.get("catalog_ready").and_then(Value::as_bool) != Some(true) {
            return Err(format!("isolated modal input catalog is not ready: {status}").into());
        }
        let main_status: Value = serde_json::from_str(
            &remote_read(&session, MAIN_STATUS_REMOTE).ok_or("Main status is missing")?,
        )?;
        let build_version = status
            .pointer("/build/version")
            .and_then(Value::as_str)
            .ok_or("launcher status has no build version")?;
        let source_revision = status
            .pointer("/build/source_revision")
            .and_then(Value::as_str)
            .ok_or("launcher status has no source revision")?;
        let main_generation = main_status
            .get("main_generation")
            .and_then(Value::as_u64)
            .ok_or("Main status has no generation")?;
        let begin = launcher_automation::begin(
            config,
            build_version,
            source_revision,
            main_generation,
            60,
        )?;
        let begin: Value = serde_json::from_str(&begin)?;
        nonce = Some(
            begin
                .get("nonce")
                .and_then(Value::as_str)
                .ok_or("modal input automation has no nonce")?
                .to_string(),
        );
        let active_nonce = nonce.as_deref().expect("nonce assigned above");
        let dialog = wait_modal_input_snapshot(
            config,
            active_nonce,
            |snapshot| {
                modal_semantic(snapshot, "overlay").and_then(Value::as_str) == Some("confirm")
                    && modal_semantic(snapshot, "dialog_title").and_then(Value::as_str)
                        == Some("Catalog update required")
                    && modal_semantic(snapshot, "selected_item_id").and_then(Value::as_str)
                        == Some("menu:arcade")
            },
            "catalog recovery dialog over the Arcade tile",
        )?;
        let rebuild_sequence = modal_input_action(
            config,
            active_nonce,
            AutomationAction::Tap(AutomationButton::Right),
        )?;
        let rebuild_selected = wait_modal_input_snapshot(
            config,
            active_nonce,
            |snapshot| {
                modal_semantic(snapshot, "dialog_selected").and_then(Value::as_i64) == Some(1)
            },
            "Rebuild selection",
        )?;
        let dialog_checkpoint = launcher_automation::capture_checkpoint(
            config,
            active_nonce,
            rebuild_sequence,
            "catalog-recovery-rebuild-selected",
            output_dir,
        )?;
        let hold_sequence = modal_input_action(
            config,
            active_nonce,
            AutomationAction::Hold {
                button: AutomationButton::A,
                duration_ms: 2_000,
            },
        )?;
        let during_hold = wait_modal_input_snapshot(
            config,
            active_nonce,
            |snapshot| {
                modal_semantic(snapshot, "overlay").and_then(Value::as_str) != Some("confirm")
            },
            "dialog dismissal",
        )?;
        require_modal_home_state(&during_hold, "during held A")?;
        let held_checkpoint = launcher_automation::capture_checkpoint(
            config,
            active_nonce,
            hold_sequence,
            "held-a-dismissal",
            output_dir,
        )?;

        modal_input_action(config, active_nonce, AutomationAction::ReleaseAll)?;
        let after_release = launcher_automation::snapshot(config, active_nonce)?;
        require_modal_home_state(&after_release, "after release")?;
        let fresh_sequence = modal_input_action(
            config,
            active_nonce,
            AutomationAction::Tap(AutomationButton::A),
        )?;
        let fresh_press = wait_modal_input_snapshot(
            config,
            active_nonce,
            |snapshot| {
                modal_semantic(snapshot, "return_screen").and_then(Value::as_str) == Some("arcade")
                    && matches!(
                        modal_semantic(snapshot, "composition_state").and_then(Value::as_str),
                        Some("mixed-arcade" | "full-slint")
                    )
            },
            "settled fresh Arcade activation",
        )?;
        let fresh_checkpoint = launcher_automation::capture_checkpoint(
            config,
            active_nonce,
            fresh_sequence,
            "fresh-a-opens-arcade",
            output_dir,
        )?;
        Ok(json!({
            "schema": "mister-magik-modal-input-verification-v1",
            "status": "passed",
            "dialog": dialog["semantic"],
            "rebuild_selected": rebuild_selected["semantic"],
            "during_hold": during_hold["semantic"],
            "after_release": after_release["semantic"],
            "fresh_press": fresh_press["semantic"],
            "checkpoints": [
                serde_json::from_str::<Value>(&dialog_checkpoint)?,
                serde_json::from_str::<Value>(&held_checkpoint)?,
                serde_json::from_str::<Value>(&fresh_checkpoint)?,
            ],
            "isolation": {"remote_root": MODAL_INPUT_REMOTE_DIR},
            "boot_id": boot_id,
            "manifest": parse_manifest_evidence(&manifest),
        }))
    })();

    if let Err(error) = &run_result {
        let evidence = json!({
            "schema": "mister-magik-modal-input-failure-v1",
            "error": error.to_string(),
            "status": remote_read(&session, SLINT_STATUS_REMOTE),
            "main_status": remote_read(&session, MAIN_STATUS_REMOTE),
            "events_tail": tail_remote(&session, "/tmp/mister-magik/events.jsonl", 160)
                .map(|lines| lines.join("\n")),
            "slint_log_tail": tail_remote(&session, "/tmp/mister-magik-slint.log", 160)
                .map(|lines| lines.join("\n")),
        });
        fs::write(
            output_dir.join("failure-evidence.json"),
            format!("{}\n", serde_json::to_string_pretty(&evidence)?),
        )?;
    }

    let end_result = nonce
        .as_deref()
        .map(|nonce| launcher_automation::end(config, nonce).map(|_| ()))
        .unwrap_or(Ok(()));
    let restart_result = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let cleanup_result = exec_checked(
        &session,
        "modal input isolated cleanup",
        &modal_input_cleanup_command(),
    );
    end_result?;
    restart_result?;
    cleanup_result?;
    let summary = run_result?;
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after modal input verification")?;
    if final_boot_id.trim() != boot_id {
        return Err("device rebooted during modal input verification".into());
    }
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is missing after modal input verification")?;
    if final_manifest != manifest {
        return Err("installed platform manifest changed during modal input verification".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    fs::write(
        output_dir.join("report.md"),
        "# Modal input verification\n\nHeld dialog input remained exclusive, and a fresh A press opened Arcade.\n",
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn require_modal_home_state(snapshot: &Value, label: &str) -> Result<()> {
    let return_screen = modal_semantic(snapshot, "return_screen").and_then(Value::as_str);
    let menu_id = modal_semantic(snapshot, "menu_id").and_then(Value::as_str);
    let active_collection =
        modal_semantic(snapshot, "active_collection_id").and_then(Value::as_str);
    if return_screen != Some("home")
        || menu_id != Some("menu:root")
        || active_collection != Some("")
    {
        return Err(
            format!("modal input leaked to the underlying view {label}: {snapshot}").into(),
        );
    }
    Ok(())
}

fn modal_input_prepare_command() -> String {
    let source = installed_layout::app_path(Layout::Development, "catalog-v3")
        .expect("static installed path");
    let safety = platform_safety_script();
    format!(
        "set -eu; root={root}; source={source}; rm -rf \"$root\"; mkdir -p \"$root\"; test -d \"$source\"; cp -a \"$source\" \"$root/catalog-v3\"; test -d \"$root/catalog-v3\"; {safety}",
        root = sh(MODAL_INPUT_REMOTE_DIR),
        source = sh(&source),
        safety = safety,
    )
}

fn modal_input_launcher_env() -> Vec<(String, String)> {
    let root = MODAL_INPUT_REMOTE_DIR;
    vec![
        ("MISTER_CATALOG_REFRESH".into(), "off".into()),
        (
            "MISTER_MAGIK_TEST_CATALOG_RECOVERY_DIALOG".into(),
            "upgrade".into(),
        ),
        (
            "MISTER_SHARDED_CATALOG_DIR".into(),
            format!("{root}/catalog-v3"),
        ),
        (
            "MISTER_LIBRARY_SQLITE".into(),
            format!("{root}/library.sqlite3"),
        ),
        (
            "MISTER_ARCADE_BOOTSTRAP_INDEX".into(),
            format!("{root}/arcade-bootstrap.nav.lz4b"),
        ),
        (
            "MISTER_LIBRARY_REFRESH_LOCK".into(),
            format!("{root}/library-refresh.lock"),
        ),
        (
            "MISTER_CATALOG_BUILDER_LOCK".into(),
            format!("{root}/catalog-builder.lock"),
        ),
        (
            "MISTER_CATALOG_READY_SNAPSHOT".into(),
            format!("{root}/catalog-ready.snapshot"),
        ),
        (
            "MISTER_CATALOG_DIAGNOSTICS_DIR".into(),
            format!("{root}/diagnostics"),
        ),
    ]
}

fn modal_input_cleanup_command() -> String {
    let safety = platform_safety_script();
    format!(
        "set -eu; rm -rf {root}; test ! -e {root}; {safety}",
        root = sh(MODAL_INPUT_REMOTE_DIR),
        safety = safety,
    )
}

fn last_json_line(output: &str) -> Option<Value> {
    output
        .lines()
        .rev()
        .find_map(|line| serde_json::from_str::<Value>(line.trim()).ok())
}

fn profile_installed_search(config: &NativeDeviceConfig, output_dir: &Path) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    fs::create_dir_all(output_dir)?;
    let started = Instant::now();
    let mut log = String::new();
    let output = loop {
        let output = exec(&session, &development_gui_command("search-bench"), true)?;
        log.push_str(&output.stdout);
        log.push_str(&output.stderr);
        if exec_failure_message("installed search benchmark", &output).is_none() {
            break output;
        }
        if !search_benchmark_waits_for_catalog(&output)
            || started.elapsed() >= Duration::from_secs(180)
        {
            fs::write(output_dir.join("search-bench.log"), &log)?;
            return Err(exec_failure_message("installed search benchmark", &output)
                .expect("failed search benchmark checked above")
                .into());
        }
        thread::sleep(Duration::from_secs(1));
    };
    fs::write(output_dir.join("search-bench.log"), &log)?;
    let summary =
        last_json_line(&output.stdout).ok_or("installed search benchmark returned no JSON")?;
    if summary.get("schema").and_then(Value::as_str) != Some("mister-magik-search-benchmark-v2") {
        return Err("installed search benchmark returned the wrong schema".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_media_pack_persistence(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    fs::create_dir_all(output_dir)?;
    let capability = exec_checked_output(
        &session,
        "installed benchmark capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("media-pack-persistence-v1")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support media-pack-persistence-v1".into());
    }
    let output = exec(
        &session,
        &development_gui_command(
            "media-bench-download --system representative --iterations 3 --prime-cache --label production",
        ),
        true,
    )?;
    let mut log = output.stdout.clone();
    log.push_str(&output.stderr);
    fs::write(output_dir.join("production.log"), &log)?;
    if let Some(message) =
        exec_failure_message("installed media-pack persistence benchmark", &output)
    {
        return Err(message.into());
    }
    let summary = last_json_line(&output.stdout)
        .ok_or("installed media-pack persistence benchmark returned no JSON")?;
    if summary.get("schema").and_then(Value::as_str)
        != Some("mister-magik-media-pack-persistence-v1")
        || summary.get("status").and_then(Value::as_str) != Some("passed")
        || summary.get("save_strategy").and_then(Value::as_str) != Some("stream-fat")
        || summary.get("row_count").and_then(Value::as_u64) != Some(9)
    {
        return Err("installed media-pack persistence benchmark returned an invalid report".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_rom_identity_hashing(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    let session = connect_with(&config.connection, 10)?;
    fs::create_dir_all(output_dir)?;
    let capability = exec_checked_output(
        &session,
        "installed benchmark capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability
        .get("rom-identity-benchmark-v3")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return Err("installed app does not support rom-identity-benchmark-v3".into());
    }
    let execution_order = ["production-a", "production-b", "production-c"];
    let mut runs = Vec::with_capacity(execution_order.len());
    for label in execution_order {
        let output = exec(
            &session,
            &development_gui_command("rom-identity-bench"),
            true,
        )?;
        let mut log = output.stdout.clone();
        log.push_str(&output.stderr);
        fs::write(output_dir.join(format!("{label}.log")), &log)?;
        if let Some(message) = exec_failure_message("installed ROM identity benchmark", &output) {
            return Err(format!("{label}: {message}").into());
        }
        let arm = last_json_line(&output.stdout)
            .ok_or_else(|| format!("installed ROM identity benchmark {label} returned no JSON"))?;
        if arm.get("schema").and_then(Value::as_str)
            != Some("mister-magik-rom-identity-benchmark-v1")
            || arm.get("status").and_then(Value::as_str) != Some("passed")
            || arm.get("implementation").and_then(Value::as_str)
                != Some("streaming-slicing-by-eight-crc32")
        {
            return Err(format!(
                "installed ROM identity benchmark {label} returned an invalid arm"
            )
            .into());
        }
        fs::write(
            output_dir.join(format!("{label}.json")),
            format!("{}\n", serde_json::to_string_pretty(&arm)?),
        )?;
        runs.push(arm);
    }
    let expected_result = runs[0]
        .get("result_sha256")
        .and_then(Value::as_str)
        .ok_or("ROM identity production run has no result hash")?
        .to_owned();
    let expected_cache = runs[0]
        .get("software_hash_cache_sha256")
        .and_then(Value::as_str)
        .ok_or("ROM identity production run has no cache hash")?
        .to_owned();
    for arm in &runs {
        if arm.get("result_sha256").and_then(Value::as_str) != Some(expected_result.as_str())
            || arm
                .get("software_hash_cache_sha256")
                .and_then(Value::as_str)
                != Some(expected_cache.as_str())
        {
            return Err("ROM identity production results differ".into());
        }
    }
    let summary = json!({
        "schema": "mister-magik-rom-identity-production-v1",
        "status": "passed",
        "execution_order": execution_order,
        "runs": runs,
        "result_sha256": expected_result,
        "software_hash_cache_sha256": expected_cache,
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

const CATALOG_PMU_REMOTE_DIR: &str = "/tmp/mister-magik/pmu-catalog-benchmark";

fn profile_installed_pmu(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    counter_set: &str,
) -> Result<String> {
    const WORKLOADS: [&str; 4] = ["probe", "screensaver", "search", "catalog"];
    let session = connect_with(&config.connection, 10)?;
    fs::create_dir_all(output_dir)?;
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is missing before PMU profiling")?;
    let installed_identity = pmu_installed_identity(&manifest)?;
    let capability = exec_checked_output(
        &session,
        "installed benchmark capability",
        DEVELOPMENT_BENCHMARK_CAPABILITIES_COMMAND.as_str(),
    )?;
    let capability = last_json_line(&capability.stdout)
        .ok_or("installed benchmark capability output contains no JSON report")?;
    if capability.get("pmu-profile-v1").and_then(Value::as_bool) != Some(true)
        || capability.get("pmu-profile-v2").and_then(Value::as_bool) != Some(true)
    {
        return Err("installed app does not support pmu-profile-v2".into());
    }
    exec_checked(
        &session,
        "catalog PMU preparation",
        &catalog_pmu_prepare_command(),
    )?;
    let run_result = (|| -> Result<Value> {
        let mut summaries = Vec::with_capacity(WORKLOADS.len());
        for workload in WORKLOADS {
            let command = format!(
                "MISTER_PMU_PROFILE=1 MISTER_PMU_COUNTER_SET={counter_set} MISTER_PMU_SAMPLE_EVERY=1 MISTER_PMU_RECORD_LIMIT=4096 {gui} pmu-profile {}",
                sh(workload),
                gui = sh(DEVELOPMENT_GUI_REMOTE),
                counter_set = sh(counter_set),
            );
            let output = exec(&session, &command, true)?;
            let mut log = output.stdout.clone();
            log.push_str(&output.stderr);
            fs::write(output_dir.join(format!("{workload}.log")), &log)?;
            if let Some(message) = exec_failure_message("installed PMU workload", &output) {
                return Err(format!("{workload}: {message}").into());
            }
            let summary = last_json_line(&output.stdout)
                .ok_or_else(|| format!("installed PMU workload {workload} returned no JSON"))?;
            validate_installed_pmu_workload(workload, &summary, counter_set)?;
            fs::write(
                output_dir.join(format!("{workload}.json")),
                format!("{}\n", serde_json::to_string_pretty(&summary)?),
            )?;
            summaries.push(summary);
        }
        Ok(json!({
            "schema": "mister-magik-pmu-suite-v2",
            "status": "passed",
            "sample_every": 1,
            "record_limit": 4096,
            "installed_identity": installed_identity,
            "counter_set": counter_set,
            "workloads": summaries,
        }))
    })();
    let cleanup_result = exec_checked(
        &session,
        "catalog PMU cleanup",
        &catalog_pmu_cleanup_command(),
    );
    let suite = run_result?;
    cleanup_result?;
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is missing after PMU profiling")?;
    if final_manifest != manifest {
        return Err("installed platform manifest changed during PMU profiling".into());
    }
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&suite)?),
    )?;
    serde_json::to_string(&suite).map_err(Into::into)
}

fn profile_installed_neon_attribution(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    fs::create_dir_all(output_dir)?;
    let pmu: Value = serde_json::from_str(&profile_installed_pmu(
        config,
        &output_dir.join("runtime-spans"),
        "cortex-a9-neon",
    )?)?;
    let landscape: Value =
        serde_json::from_str(&profile_installed_arcade_velocity_scroll_pmu_workload(
            config,
            &output_dir.join("arcade-landscape"),
            ARCADE_VELOCITY_SCROLL_DURATION_MS,
            ARCADE_VELOCITY_SCROLL_TELEMETRY_SECS,
            "mister-magik-neon-arcade-landscape-v1",
            Some("normal"),
        )?)?;
    let portrait: Value =
        serde_json::from_str(&profile_installed_arcade_velocity_scroll_pmu_workload(
            config,
            &output_dir.join("arcade-portrait-left"),
            ARCADE_VELOCITY_SCROLL_DURATION_MS,
            ARCADE_VELOCITY_SCROLL_TELEMETRY_SECS,
            "mister-magik-neon-arcade-portrait-left-v1",
            Some("monitor-counterclockwise"),
        )?)?;
    for artifact in [&pmu, &landscape, &portrait] {
        validate_pmu_counter_set(artifact, "cortex-a9-neon")?;
    }
    let summary = json!({
        "schema": "mister-magik-neon-attribution-v1",
        "status": "passed",
        "counter_set": "cortex-a9-neon",
        "profiles": {
            "runtime_spans": pmu,
            "arcade_landscape": landscape,
            "arcade_portrait_left": portrait,
        },
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn pmu_installed_identity(manifest: &str) -> Result<Value> {
    Ok(json!({
        "manifest_sha256": encode_hex(&Sha256::digest(manifest.as_bytes())),
        "magik_revision": exact_manifest_field(manifest, "magik_revision", 40)?,
        "gui_sha256": exact_manifest_field(manifest, "gui_sha256", 64)?,
    }))
}

fn validate_installed_pmu_workload(
    workload: &str,
    summary: &Value,
    counter_set: &str,
) -> Result<()> {
    if workload == "probe" {
        if summary.get("schema").and_then(Value::as_str) == Some("mister-magik-pmu-probe-v2")
            && summary.get("status").and_then(Value::as_str) == Some("ok")
        {
            validate_pmu_counter_set(summary, counter_set)?;
            return Ok(());
        }
        return Err("installed PMU probe did not produce authoritative counters".into());
    }
    if summary.get("schema").and_then(Value::as_str) != Some("mister-magik-pmu-workload-v1")
        || summary.get("workload").and_then(Value::as_str) != Some(workload)
        || summary.get("status").and_then(Value::as_str) != Some("ok")
    {
        return Err(format!("installed PMU workload {workload} returned unusable evidence").into());
    }
    if workload == "catalog" {
        validate_catalog_pmu_workload(summary)?;
        return validate_pmu_counter_set(summary, counter_set);
    }
    if summary.pointer("/profile/enabled").and_then(Value::as_bool) != Some(true)
        || summary
            .pointer("/profile/records")
            .and_then(Value::as_array)
            .is_none_or(Vec::is_empty)
    {
        return Err(format!("installed PMU workload {workload} returned unusable evidence").into());
    }
    validate_pmu_counter_set(summary, counter_set)
}

fn validate_pmu_counter_set(value: &Value, expected: &str) -> Result<()> {
    fn visit(value: &Value, counter_sets: &mut Vec<String>) {
        match value {
            Value::Object(object) => {
                if let Some(counter_set) = object.get("counter_set").and_then(Value::as_str) {
                    counter_sets.push(counter_set.to_owned());
                }
                for value in object.values() {
                    visit(value, counter_sets);
                }
            }
            Value::Array(values) => {
                for value in values {
                    visit(value, counter_sets);
                }
            }
            _ => {}
        }
    }
    let mut counter_sets = Vec::new();
    visit(value, &mut counter_sets);
    if counter_sets.is_empty() || counter_sets.iter().any(|value| value != expected) {
        return Err(
            format!("PMU artifact counter sets {counter_sets:?} do not match {expected}").into(),
        );
    }
    Ok(())
}

fn validate_catalog_pmu_workload(summary: &Value) -> Result<()> {
    if summary
        .pointer("/configuration/root")
        .and_then(Value::as_str)
        != Some(CATALOG_PMU_REMOTE_DIR)
        || summary
            .pointer("/validation/isolated")
            .and_then(Value::as_bool)
            != Some(true)
        || summary
            .pointer("/validation/incremental_game_delta")
            .and_then(Value::as_u64)
            != Some(1)
        || summary
            .pointer("/validation/rebuild_all_preserved_counts")
            .and_then(Value::as_bool)
            != Some(true)
    {
        return Err("catalog PMU workload failed its isolation or catalog validation".into());
    }
    let operations = summary
        .get("operations")
        .and_then(Value::as_array)
        .ok_or("catalog PMU workload has no operations")?;
    if operations.len() != 3 {
        return Err("catalog PMU workload must report three operations".into());
    }
    for (operation, expected) in operations
        .iter()
        .zip(["fresh-build", "update", "rebuild-all"])
    {
        let no_op_rebuild_all = expected == "rebuild-all"
            && operation
                .get("rebuilt_systems")
                .and_then(Value::as_array)
                .is_some_and(Vec::is_empty);
        if operation.get("operation").and_then(Value::as_str) != Some(expected)
            || operation.get("status").and_then(Value::as_str) != Some("ok")
            || operation
                .get("peak_rss_kib")
                .and_then(Value::as_u64)
                .is_none()
            || operation
                .pointer("/profile/dropped_profiles")
                .and_then(Value::as_u64)
                != Some(0)
        {
            return Err(format!("catalog PMU operation {expected} is incomplete").into());
        }
        let profiles = operation
            .pointer("/profile/profiles")
            .and_then(Value::as_array)
            .ok_or_else(|| format!("catalog PMU operation {expected} has no thread profiles"))?;
        if profiles.is_empty()
            || profiles.iter().any(|entry| {
                entry.pointer("/profile/enabled").and_then(Value::as_bool) != Some(true)
                    || !entry
                        .pointer("/profile/failure")
                        .is_some_and(Value::is_null)
                    || entry
                        .pointer("/profile/dropped_spans")
                        .and_then(Value::as_u64)
                        != Some(0)
                    || (!no_op_rebuild_all
                        && entry
                            .pointer("/profile/records")
                            .and_then(Value::as_array)
                            .is_none_or(Vec::is_empty))
            })
        {
            return Err(format!("catalog PMU operation {expected} lost PMU evidence").into());
        }
    }
    if operations[1]
        .get("rebuilt_systems")
        .and_then(Value::as_array)
        .is_none_or(|systems| systems.len() != 1 || systems[0].as_str() != Some("snes"))
    {
        return Err("catalog PMU incremental operation did not rebuild exactly snes".into());
    }
    Ok(())
}

fn catalog_pmu_prepare_command() -> String {
    let safety = platform_safety_script();
    format!(
        "set -eu; root={root}; rm -rf \"$root\"; mkdir -p \"$root\"; {safety}",
        root = sh(CATALOG_PMU_REMOTE_DIR),
        safety = safety,
    )
}

fn catalog_pmu_cleanup_command() -> String {
    let safety = platform_safety_script();
    format!(
        "set -eu; root={root}; rm -rf \"$root\"; test ! -e \"$root\"; {safety}",
        root = sh(CATALOG_PMU_REMOTE_DIR),
        safety = safety,
    )
}

const STREAMLINE_REMOTE_ROOT: &str = "/tmp/mister-magik/streamline-capture";
const STREAMLINE_REMOTE_GATORD: &str = "/tmp/mister-magik/streamline-capture/gatord";
const STREAMLINE_REMOTE_APC: &str = "/tmp/mister-magik/streamline-capture/mister-magik.apc";
const STREAMLINE_REMOTE_ARCHIVE: &str =
    "/tmp/mister-magik/streamline-capture/mister-magik.apc.tar.gz";
const STREAMLINE_REMOTE_PID: &str = "/tmp/mister-magik/streamline-capture/gatord.pid";
const STREAMLINE_REMOTE_LOG: &str = "/tmp/mister-magik/streamline-capture/gatord.log";
const STREAMLINE_REMOTE_READY: &str = "/tmp/mister-magik/streamline-capture/gatord.ready";
const STREAMLINE_TRACEFS_MOUNT: &str = "/sys/kernel/tracing";
const STREAMLINE_TRACEFS_MARKER: &str = "/tmp/mister-magik/streamline-capture/owned-tracefs.mount";
const CORTEX_A9_NEON_GATOR_COUNTERS: &str = "ARMv7_Cortex_A9_ccnt,ARMv7_Cortex_A9_cnt0:0x68,ARMv7_Cortex_A9_cnt1:0x74,ARMv7_Cortex_A9_cnt2:0x8c,ARMv7_Cortex_A9_cnt3:0x61,ARMv7_Cortex_A9_cnt4:0x04,ARMv7_Cortex_A9_cnt5:0x03";
const STREAMLINE_ANALYZER_TIMEOUT: Duration = Duration::from_secs(120);

