struct SystemWideStreamlineCapture<'a> {
    session: &'a Session,
    connection: ConnectionConfig,
    output_dir: &'a Path,
    spec: SystemWideStreamlineCaptureSpec,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct StreamlineInstalledIdentity {
    boot_id: String,
    platform_manifest_sha256: String,
    magik_revision: String,
    gui_sha256: String,
    agent_sha256: String,
    agent_bytes: u64,
    agent_version: u64,
}

impl<'a> SystemWideStreamlineCapture<'a> {
    fn new(
        session: &'a Session,
        connection: &ConnectionConfig,
        output_dir: &'a Path,
        spec: SystemWideStreamlineCaptureSpec,
    ) -> Self {
        Self {
            session,
            connection: connection.clone(),
            output_dir,
            spec,
        }
    }

    fn prepare(&self, gatord: &Path) -> Result<String> {
        exec_checked(
            self.session,
            &format!("prepare {} capture", self.spec.label),
            &streamline_prepare_command(),
        )?;
        put(self.session, gatord, STREAMLINE_REMOTE_GATORD)?;
        let version = exec(
            self.session,
            &format!(
                "chmod 700 {gatord}; {gatord} --version",
                gatord = sh(STREAMLINE_REMOTE_GATORD)
            ),
            true,
        )?;
        parse_gatord_version(&version)
    }

    fn start(&self) -> thread::JoinHandle<std::result::Result<ExecOutput, String>> {
        let capture_connection = self.connection.clone();
        let capture_command = streamline_system_wide_capture_command(self.spec);
        thread::spawn(move || {
            let capture_session = connect_with(&capture_connection, 30)
                .map_err(|error| format!("connect Streamline capture channel: {error}"))?;
            exec(&capture_session, &capture_command, true)
                .map_err(|error| format!("run Streamline capture channel: {error}"))
        })
    }

    fn wait_ready(&self, timeout: Duration) -> Result<()> {
        wait_streamline_system_wide_ready(self.session, timeout)
    }

    fn monotonic_ns(&self, phase: &str) -> Result<u64> {
        streamline_device_monotonic_ns(self.session, phase)
    }

    fn stop(
        &self,
        capture_thread: thread::JoinHandle<std::result::Result<ExecOutput, String>>,
    ) -> Result<()> {
        let stop_result = exec_checked(
            self.session,
            &format!("stop {} capture", self.spec.label),
            &streamline_system_wide_stop_command(),
        );
        if stop_result.is_err() {
            return Err(format!(
                "{} capture could not be joined after stop failure",
                self.spec.label
            )
            .into());
        }
        let output = capture_thread
            .join()
            .map_err(|_| format!("{} capture thread panicked", self.spec.label))??;
        if let Some(message) = exec_failure_message(self.spec.label, &output) {
            return Err(message.into());
        }
        Ok(())
    }

    fn retain_log(&self) -> Result<()> {
        if let Some(log) = remote_read(self.session, STREAMLINE_REMOTE_LOG) {
            fs::write(self.output_dir.join("gatord.log"), log)?;
        }
        Ok(())
    }

    fn package_extract(&self) -> Result<String> {
        exec_checked(
            self.session,
            &format!("package {} capture", self.spec.label),
            &streamline_package_command(),
        )?;
        let archive = self.output_dir.join(self.spec.archive_file);
        get(self.session, STREAMLINE_REMOTE_ARCHIVE, &archive)?;
        let remote_archive_sha256 = exec_checked_output(
            self.session,
            &format!("hash {} capture", self.spec.label),
            &format!(
                "sha256sum {} | cut -d' ' -f1",
                sh(STREAMLINE_REMOTE_ARCHIVE)
            ),
        )?
        .stdout
        .trim()
        .to_owned();
        let local_archive_sha256 = file_sha256(archive.clone())?;
        if remote_archive_sha256.len() != 64 || remote_archive_sha256 != local_archive_sha256 {
            return Err(format!("{} archive changed during transfer", self.spec.label).into());
        }
        extract_streamline_archive(&archive, self.output_dir)?;
        Ok(local_archive_sha256)
    }

    fn cleanup(&self) -> Result<()> {
        exec_checked(
            self.session,
            &format!("clean {} capture", self.spec.label),
            &streamline_cleanup_command(),
        )
    }
}

fn profile_installed_streamline(
    config: &NativeDeviceConfig,
    output_dir: &Path,
    workload: StreamlineWorkload,
) -> Result<String> {
    let gatord = streamline_gatord_path(env::var_os("MISTER_GATORD_PATH"))?;
    let gatord_metadata = fs::metadata(&gatord)?;
    if !gatord_metadata.is_file() || gatord_metadata.len() == 0 {
        return Err("MISTER_GATORD_PATH must name a non-empty regular file".into());
    }
    if gatord_metadata.len() > 64 * 1024 * 1024 {
        return Err("MISTER_GATORD_PATH exceeds the 64 MiB upload limit".into());
    }
    let gatord_sha256 = file_sha256(gatord.clone())?;
    fs::create_dir_all(output_dir)?;
    let archive = output_dir.join("mister-magik.apc.tar.gz");
    let session = connect_with(&config.connection, 30)?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable before Streamline capture")?;
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is unavailable before Streamline capture")?;

    exec_checked(
        &session,
        "prepare Streamline capture",
        &streamline_prepare_command(),
    )?;
    let run_result = (|| -> Result<(String, String)> {
        put(&session, &gatord, STREAMLINE_REMOTE_GATORD)?;
        let version = exec(
            &session,
            &format!(
                "chmod 700 {gatord}; {gatord} --version",
                gatord = sh(STREAMLINE_REMOTE_GATORD)
            ),
            true,
        )?;
        let gatord_version = parse_gatord_version(&version)?;
        let output = exec(&session, &streamline_capture_command(workload), true)?;
        let mut capture_log = output.stdout.clone();
        capture_log.push_str(&output.stderr);
        fs::write(output_dir.join("gatord.log"), &capture_log)?;
        if let Some(message) = exec_failure_message("bounded Streamline capture", &output) {
            return Err(message.into());
        }
        exec_checked(
            &session,
            "package Streamline capture",
            &streamline_package_command(),
        )?;
        get(&session, STREAMLINE_REMOTE_ARCHIVE, &archive)?;
        let remote_archive_sha256 = exec_checked_output(
            &session,
            "hash Streamline capture",
            &format!(
                "sha256sum {} | cut -d' ' -f1",
                sh(STREAMLINE_REMOTE_ARCHIVE)
            ),
        )?
        .stdout
        .trim()
        .to_owned();
        let local_archive_sha256 = file_sha256(archive.clone())?;
        if remote_archive_sha256.len() != 64 || remote_archive_sha256 != local_archive_sha256 {
            return Err("Streamline capture archive changed during transfer".into());
        }
        extract_streamline_archive(&archive, output_dir)?;
        Ok((gatord_version, local_archive_sha256))
    })();

    let cleanup_result = exec_checked(
        &session,
        "clean Streamline capture",
        &streamline_cleanup_command(),
    );
    let (gatord_version, archive_sha256) = match (run_result, cleanup_result) {
        (Ok(result), Ok(())) => result,
        (Err(run), Ok(())) => return Err(run),
        (Ok(_), Err(cleanup)) => return Err(cleanup),
        (Err(run), Err(cleanup)) => {
            return Err(format!("Streamline capture failed: run={run}; cleanup={cleanup}",).into());
        }
    };

    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after Streamline capture")?;
    if final_boot_id != boot_id {
        return Err("device rebooted during Streamline capture".into());
    }
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is unavailable after Streamline capture")?;
    if final_manifest != manifest {
        return Err("installed platform manifest changed during Streamline capture".into());
    }
    let summary = json!({
        "schema": "mister-magik-streamline-capture-v1",
        "status": "passed",
        "gatord_version": gatord_version,
        "gatord_sha256": gatord_sha256,
        "archive_sha256": archive_sha256,
        "capture": "mister-magik.apc",
        "archive": "mister-magik.apc.tar.gz",
        "workload": workload.label(),
        "max_duration_seconds": 10,
        "sample_rate": "low",
        "exclude_kernel": false,
        "call_stack_unwinding": false,
        "counter_set": "cortex-a9-neon",
        "counters": CORTEX_A9_NEON_GATOR_COUNTERS.split(',').collect::<Vec<_>>(),
        "analysis": if output_dir.join("streamline-analysis/summary.json").is_file() {
            "generated"
        } else {
            "not-requested"
        },
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_launcher_response_streamline(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    let gatord = streamline_gatord_path(env::var_os("MISTER_GATORD_PATH"))?;
    let gatord_metadata = fs::metadata(&gatord)?;
    if !gatord_metadata.is_file() || gatord_metadata.len() == 0 {
        return Err("MISTER_GATORD_PATH must name a non-empty regular file".into());
    }
    if gatord_metadata.len() > 64 * 1024 * 1024 {
        return Err("MISTER_GATORD_PATH exceeds the 64 MiB upload limit".into());
    }
    let gatord_sha256 = file_sha256(gatord.clone())?;
    fs::create_dir_all(output_dir)?;
    let session = connect_with(&config.connection, 30)?;
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is unavailable before launcher-response Streamline capture")?;
    let installed_identity = streamline_installed_identity(&session, config.agent()?, &manifest)?;
    let original_reply = exec_checked_output(
        &session,
        "query launcher-response Streamline display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(original_reply.stdout.trim())?.is_some() {
        return Err(
            "launcher-response Streamline cannot start during a display transaction".into(),
        );
    }
    let original_id = parse_display_reply_active(original_reply.stdout.trim())?;
    let original_mode = DISPLAY_MATRIX_MODES
        .iter()
        .find(|mode| mode.id == original_id)
        .copied()
        .ok_or_else(|| {
            format!("launcher-response Streamline cannot restore unknown mode {original_id}")
        })?;
    let capture_mode = DISPLAY_MATRIX_MODES
        .iter()
        .find(|mode| mode.id == "hdmi-1920x1200p60")
        .copied()
        .ok_or("missing launcher-response Streamline display mode")?;

    apply_confirmed_display_mode(config, capture_mode, "launcher-response Streamline capture")?;
    let capture = SystemWideStreamlineCapture::new(
        &session,
        &config.connection,
        output_dir,
        LAUNCHER_RESPONSE_STREAMLINE_CAPTURE,
    );
    let run_result = (|| -> Result<(String, String, Value, u64, u64)> {
        let gatord_version = capture.prepare(&gatord)?;
        let capture_thread = capture.start();
        capture.wait_ready(Duration::from_secs(10))?;
        let capture_started_monotonic_ns = capture.monotonic_ns("capture start")?;
        let route_result =
            run_launcher_response_scenario(&session, "60-hz", "streamline-round-trip", "off", true);
        let capture_result = capture.stop(capture_thread);
        let capture_ended_monotonic_ns = capture.monotonic_ns("capture end")?;
        capture.retain_log()?;
        let route = route_result?;
        capture_result?;
        let local_archive_sha256 = capture.package_extract()?;
        Ok((
            gatord_version,
            local_archive_sha256,
            route,
            capture_started_monotonic_ns,
            capture_ended_monotonic_ns,
        ))
    })();

    let cleanup_result = capture.cleanup();
    let launcher_restore_result = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let display_restore_result = apply_confirmed_display_mode(
        config,
        original_mode,
        "launcher-response Streamline display restoration",
    );
    let (
        gatord_version,
        archive_sha256,
        route,
        capture_started_monotonic_ns,
        capture_ended_monotonic_ns,
    ) = match (
        run_result,
        cleanup_result,
        launcher_restore_result,
        display_restore_result,
    ) {
        (Ok(result), Ok(()), Ok(()), Ok(())) => result,
        (run, cleanup, launcher, display) => {
            return Err(format!(
                "launcher-response Streamline failed: run={:?}; cleanup={:?}; launcher_restore={:?}; display_restore={:?}",
                run.err(),
                cleanup.err(),
                launcher.err(),
                display.err()
            )
            .into());
        }
    };

    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is unavailable after launcher-response Streamline capture")?;
    if final_manifest != manifest {
        return Err(
            "installed platform manifest changed during launcher-response Streamline capture"
                .into(),
        );
    }
    let final_identity = streamline_installed_identity(&session, config.agent()?, &final_manifest)?;
    if final_identity != installed_identity {
        return Err(
            "installed identity changed during launcher-response Streamline capture".into(),
        );
    }
    let capture_manifest = streamline_capture_manifest(
        &installed_identity,
        &gatord_version,
        &gatord_sha256,
        LAUNCHER_RESPONSE_STREAMLINE_CAPTURE,
        capture_started_monotonic_ns,
        capture_ended_monotonic_ns,
    );
    fs::write(
        output_dir.join("capture-manifest.json"),
        format!("{}\n", serde_json::to_string_pretty(&capture_manifest)?),
    )?;
    let summary = json!({
        "schema": "mister-magik-launcher-response-streamline-v1",
        "artifact_status": "passed",
        "product_quality_status": route["input_response_status"],
        "input_integrity_status": if launcher_response_integrity_passed(&route) { "passed" } else { "failed" },
        "gatord_version": gatord_version,
        "gatord_sha256": gatord_sha256,
        "archive_sha256": archive_sha256,
        "capture": "mister-magik.apc",
        "archive": "mister-magik-launcher-response.apc.tar.gz",
        "capture_manifest": "capture-manifest.json",
        "identity": capture_manifest,
        "display_mode": capture_mode.id,
        "refresh_hz": 60,
        "clock_domain": "CLOCK_MONOTONIC",
        "max_duration_seconds": 120,
        "sample_rate": "low",
        "system_wide": true,
        "exclude_kernel": false,
        "call_stack_unwinding": false,
        "route": route,
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

fn profile_installed_settled_composition(
    config: &NativeDeviceConfig,
    output_dir: &Path,
) -> Result<String> {
    fs::create_dir_all(output_dir)?;
    let session = connect_with(&config.connection, 10)?;
    let manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is unavailable before settled composition")?;
    let boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable before settled composition")?;
    let original_reply = exec_checked_output(
        &session,
        "query settled composition display mode",
        &acknowledged_main_command("mister_magik_display_get_v1"),
    )?;
    if parse_display_reply_pending(original_reply.stdout.trim())?.is_some() {
        return Err("settled composition cannot start during a display transaction".into());
    }
    let original_id = parse_display_reply_active(original_reply.stdout.trim())?;
    let original_mode = DISPLAY_MATRIX_MODES
        .iter()
        .find(|mode| mode.id == original_id)
        .copied()
        .ok_or_else(|| format!("settled composition cannot restore unknown mode {original_id}"))?;
    let capture_mode = DISPLAY_MATRIX_MODES
        .iter()
        .find(|mode| mode.id == "hdmi-1280x720p60")
        .copied()
        .ok_or("missing settled composition display mode")?;
    drop(session);
    apply_confirmed_display_mode(config, capture_mode, "settled composition")?;
    let session = connect_with(&config.connection, 10)?;
    let route_result = run_settled_composition_route(config, &session, output_dir);
    if let Some(log) = remote_read(&session, "/tmp/mister-magik-slint.log") {
        fs::write(output_dir.join("launcher.log"), log)?;
    }
    let launcher_restore = launcher_restart(
        &session,
        &LauncherRestartOptions {
            clear_env: true,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            timeout_secs: 45,
            ..LauncherRestartOptions::default()
        },
    );
    let route_cleanup = exec_checked(
        &session,
        "clean settled composition route state",
        &gui_profile_route_cleanup_command(),
    );
    drop(session);
    let display_restore =
        apply_confirmed_display_mode(config, original_mode, "settled composition restoration");
    let route = match (
        route_result,
        launcher_restore,
        route_cleanup,
        display_restore,
    ) {
        (Ok(route), Ok(()), Ok(()), Ok(())) => route,
        (route, launcher, cleanup, display) => {
            return Err(format!(
                "settled composition failed: route={:?}; launcher_restore={:?}; cleanup={:?}; display_restore={:?}",
                route.err(),
                launcher.err(),
                cleanup.err(),
                display.err()
            )
            .into());
        }
    };
    let session = connect_with(&config.connection, 10)?;
    let final_manifest = remote_read(&session, LOCAL_MAIN_MANIFEST_REMOTE)
        .ok_or("development manifest is unavailable after settled composition")?;
    let final_boot_id = remote_read(&session, "/proc/sys/kernel/random/boot_id")
        .ok_or("device boot id is unavailable after settled composition")?;
    if final_manifest != manifest || final_boot_id != boot_id {
        return Err("installed identity changed during settled composition".into());
    }
    let summary = json!({
        "schema": "mister-magik-settled-composition-v1",
        "artifact_status": "passed",
        "product_quality_status": route.pointer("/metrics/presentation/quality_status")
            .cloned().unwrap_or_else(|| json!("unknown")),
        "performance_authority": "unprofiled-installed-dev",
        "modal_carrier_policy": "receipt-scoped",
        "full_raster_policy": "reused-buffer",
        "display_mode": capture_mode.id,
        "identity": {
            "boot_id": boot_id.trim(),
            "manifest": parse_manifest_evidence(&manifest),
        },
        "route": route,
        "artifacts": {
            "profile": "profile.json",
            "launcher_log": "launcher.log",
            "terminal_settings_png": "terminal-settings.png",
            "terminal_settings_metadata": "terminal-settings.json",
        },
    });
    fs::write(
        output_dir.join("summary.json"),
        format!("{}\n", serde_json::to_string_pretty(&summary)?),
    )?;
    serde_json::to_string(&summary).map_err(Into::into)
}

