fn catalog_resume_validation_launcher_env() -> Vec<(String, String)> {
    catalog_build_rebuild_launcher_env()
        .into_iter()
        .filter(|(key, _)| key != "MISTER_CATALOG_REFRESH")
        .collect()
}

fn catalog_production_registry_identity(session: &Session) -> Result<String> {
    let command = "set -eu; for path in /media/fat/mister-magik/catalog-v3/registry/manifest-a.json /media/fat/mister-magik/catalog-v3/registry/manifest-b.json /media/fat/mister-magik-dev/catalog-v3/registry/manifest-a.json /media/fat/mister-magik-dev/catalog-v3/registry/manifest-b.json; do if test -f \"$path\"; then printf '%s\\t' \"$path\"; sha256sum \"$path\" | cut -d' ' -f1; else printf '%s\\tmissing\\n' \"$path\"; fi; done";
    Ok(
        exec_checked_output(session, "hash production catalog registries", command)?
            .stdout
            .trim()
            .to_string(),
    )
}

fn catalog_full_build_rebuild_launcher_env() -> Vec<(String, String)> {
    let mut env = catalog_build_rebuild_launcher_env()
        .into_iter()
        .filter(|(key, _)| {
            key != "MISTER_LIBRARY_ROOTS" && key != "MISTER_LIBRARY_TARGET_ALLOWLIST"
        })
        .collect::<Vec<_>>();
    match std::env::var("MISTER_PREPARED_BUNDLE_BENCH_MODE").as_deref() {
        Ok("capture") => env.push((
            "MISTER_PREPARED_BUNDLE_CAPTURE_DIR".into(),
            PREPARED_BUNDLE_HELPER_REMOTE_DIR.into(),
        )),
        Ok("helper") => env.push((
            "MISTER_PREPARED_BUNDLE_HELPER_DIR".into(),
            PREPARED_BUNDLE_HELPER_REMOTE_DIR.into(),
        )),
        _ => {}
    }
    env
}

struct CatalogBuildRebuildLegOptions {
    exercise_arcade_ui: bool,
    require_updater_index: bool,
    launcher_env: Vec<(String, String)>,
    runtime_command: fn(&str) -> String,
}

fn run_catalog_build_rebuild_leg(
    config: &NativeDeviceConfig,
    session: &Session,
    endpoint: &AgentEndpoint,
    sample_dir: &Path,
    label: &str,
    minimum_generation: Option<u64>,
    options: CatalogBuildRebuildLegOptions,
) -> Result<Value> {
    let CatalogBuildRebuildLegOptions {
        exercise_arcade_ui,
        require_updater_index,
        launcher_env,
        runtime_command,
    } = options;
    if attended_operation_interrupted() {
        return Err(
            format!("{label} catalog benchmark interrupted before launcher restart").into(),
        );
    }
    let started = Instant::now();
    restart_launcher_with_one_shot_env(
        session,
        LauncherRestartOptions {
            env_vars: launcher_env,
            timeout_secs: CATALOG_LIFECYCLE_FIRST_VISIBLE_TIMEOUT_SECS,
            remote_env: DEVELOPMENT_LAUNCHER_ENV_REMOTE.as_str().into(),
            ..LauncherRestartOptions::default()
        },
    )?;
    let mut first_visible_ms = None;
    let mut statuses = Vec::new();
    let mut telemetry = Vec::new();
    let mut automation_nonce = None;
    let mut automation_hold_sent = false;
    let mut interaction_origin_selection = None;
    let mut interaction_started = false;
    let mut interaction_started_at = None;
    let mut interaction_baseline_index = None;
    let mut interaction_telemetry_start = None;
    let mut interaction_telemetry_end = None;
    let mut interaction_complete = false;
    let mut updater_index_evidence = None;
    let mut updater_index_inspected_after_first_visible = false;
    let run_result = (|| -> Result<Value> {
        let (mut catalog, inspect_log, final_status) = loop {
            if attended_operation_interrupted() {
                return Err(format!("{label} catalog benchmark interrupted").into());
            }
            let status = read_launcher_status(session)?;
            if first_visible_ms.is_none()
                && status.get("catalog_ready").and_then(Value::as_bool) == Some(true)
                && (minimum_generation.is_some()
                    || status
                        .get("catalog_games")
                        .and_then(Value::as_u64)
                        .unwrap_or(0)
                        > 0)
            {
                first_visible_ms = Some(started.elapsed().as_millis() as u64);
            }
            if first_visible_ms.is_some() && !updater_index_inspected_after_first_visible {
                updater_index_inspected_after_first_visible = true;
                if let Some(log) = remote_read(session, "/tmp/mister-magik-slint.log")
                    && let Some(evidence) = catalog_updater_index_evidence(&log)
                {
                    if require_updater_index {
                        validate_catalog_updater_index_evidence(&evidence)?;
                    }
                    updater_index_evidence = Some(evidence);
                }
            }
            if !automation_hold_sent
                && status.get("input_enabled").and_then(Value::as_bool) == Some(true)
                && exercise_arcade_ui
                && minimum_generation.is_none()
                && let Some(settled_index) = telemetry.iter().rposition(|sample| {
                    parse_host_presentation_snapshot(sample)
                        .is_some_and(|snapshot| snapshot.magik_ownership && !snapshot.pending)
                })
            {
                let build_version = status
                    .pointer("/build/version")
                    .and_then(Value::as_str)
                    .ok_or("catalog benchmark launcher status has no build version")?;
                let source_revision = status
                    .pointer("/build/source_revision")
                    .and_then(Value::as_str)
                    .ok_or("catalog benchmark launcher status has no source revision")?;
                let main_status: Value = serde_json::from_str(
                    &remote_read(session, MAIN_STATUS_REMOTE)
                        .ok_or("catalog benchmark Main status is missing")?,
                )?;
                let main_generation = main_status
                    .get("main_generation")
                    .and_then(Value::as_u64)
                    .ok_or("catalog benchmark Main status has no generation")?;
                let begun: Value = serde_json::from_str(&launcher_automation::begin(
                    config,
                    build_version,
                    source_revision,
                    main_generation,
                    CATALOG_BUILD_REBUILD_INTERACTION_SECS + 20,
                )?)?;
                let nonce = begun
                    .get("nonce")
                    .and_then(Value::as_str)
                    .ok_or("catalog benchmark automation begin has no nonce")?
                    .to_owned();
                automation_nonce = Some(nonce.clone());
                launcher_automation::send_action(
                    config,
                    &nonce,
                    &AutomationAction::Hold {
                        button: AutomationButton::Down,
                        duration_ms: CATALOG_BUILD_REBUILD_INTERACTION_SECS * 1_000,
                    },
                )?;
                interaction_baseline_index = Some(settled_index);
                interaction_origin_selection =
                    status.get("arcade_selected").and_then(Value::as_u64);
                automation_hold_sent = true;
            }
            if automation_hold_sent
                && !interaction_started
                && interaction_origin_selection.is_some()
                && status.get("arcade_selected").and_then(Value::as_u64)
                    != interaction_origin_selection
            {
                interaction_telemetry_start = interaction_baseline_index;
                interaction_started = true;
                interaction_started_at = Some(Instant::now());
            }
            statuses.push(status.clone());
            let (telemetry_duration, telemetry_cadence_ms) =
                if automation_hold_sent && !interaction_complete {
                    (Duration::from_millis(250), 50)
                } else {
                    (Duration::from_secs(1), 250)
                };
            telemetry.extend(agent_telemetry_for_duration_at_cadence(
                endpoint,
                telemetry_duration,
                telemetry_cadence_ms,
            )?);
            if !interaction_complete
                && interaction_started_at.is_some_and(|started| {
                    started.elapsed() >= Duration::from_secs(CATALOG_BUILD_REBUILD_INTERACTION_SECS)
                })
            {
                interaction_telemetry_end = Some(telemetry.len());
                interaction_complete = true;
                if let Some(nonce) = automation_nonce.as_deref() {
                    let _ = launcher_automation::send_action(
                        config,
                        nonce,
                        &AutomationAction::ReleaseAll,
                    );
                }
            }
            if first_visible_ms.is_none()
                && started.elapsed()
                    >= Duration::from_secs(CATALOG_LIFECYCLE_FIRST_VISIBLE_TIMEOUT_SECS)
            {
                return Err(format!("{label} catalog did not become visible: {status}").into());
            }
            if status.get("catalog_refresh_done").and_then(Value::as_bool) == Some(true) {
                let inspect = inspect_catalog_after_completion(session, runtime_command, label)?;
                let catalog = parse_catalog_lifecycle_inspect(&inspect.stdout).map_err(|error| {
                format!(
                    "{label} catalog refresh completed with invalid inspection: {error}; output={}",
                    inspect.stdout.trim()
                )
            })?;
                // An unchanged forced rebuild may correctly retain its generation.
                // Completion is authoritative here; only reject a rollback.
                if minimum_generation.is_some_and(|generation| {
                    catalog
                        .get("generation")
                        .and_then(Value::as_u64)
                        .unwrap_or(0)
                        < generation
                }) {
                    return Err(format!("{label} catalog generation rolled back").into());
                }
                break (catalog, inspect.stdout, status);
            }
            if started.elapsed() >= Duration::from_secs(CATALOG_LIFECYCLE_COMPLETE_TIMEOUT_SECS) {
                return Err(format!(
                    "{label} catalog did not complete within {} seconds; status={status}",
                    CATALOG_LIFECYCLE_COMPLETE_TIMEOUT_SECS
                )
                .into());
            }
        };
        let complete_ms = started.elapsed().as_millis() as u64;
        fs::write(
            sample_dir.join(format!("{label}-catalog-inspect.tsv")),
            inspect_log,
        )?;
        fs::write(
            sample_dir.join(format!("{label}-launcher-status.json")),
            format!("{}\n", serde_json::to_string_pretty(&final_status)?),
        )?;
        fs::write(
            sample_dir.join(format!("{label}-telemetry.jsonl")),
            format!(
                "{}\n",
                telemetry
                    .iter()
                    .map(serde_json::to_string)
                    .collect::<std::result::Result<Vec<_>, _>>()?
                    .join("\n")
            ),
        )?;
        let launcher_log = remote_read(session, "/tmp/mister-magik-slint.log")
            .ok_or_else(|| format!("{label} catalog benchmark has no launcher log"))?;
        if updater_index_evidence.is_none() {
            updater_index_evidence = catalog_updater_index_evidence(&launcher_log);
        }
        if require_updater_index {
            let evidence = updater_index_evidence.as_ref().ok_or_else(|| {
                format!("{label} catalog benchmark has no updater-index prefetch evidence")
            })?;
            validate_catalog_updater_index_evidence(evidence)?;
        }
        if exercise_arcade_ui && !catalog_benchmark_presented_home_arcade(&launcher_log) {
            return Err(format!(
                "{label} catalog benchmark did not present Home with the Arcade system selected"
            )
            .into());
        }
        fs::write(
            sample_dir.join(format!("{label}-launcher.log")),
            &launcher_log,
        )?;
        let phase_evidence = catalog_phase_evidence(&launcher_log);
        let runtime_start_to_catalog_complete_ms =
            catalog_runtime_completion_ms(Some(&phase_evidence));
        let logical_fingerprint = catalog_logical_fingerprint(&catalog)?;
        catalog["logical_fingerprint"] = json!(logical_fingerprint);
        let interaction_telemetry = interaction_telemetry_start
            .and_then(|start| {
                telemetry.get(start..interaction_telemetry_end.unwrap_or(telemetry.len()))
            })
            .unwrap_or(&telemetry);
        let ui = if exercise_arcade_ui {
            catalog_build_rebuild_ui_summary(&statuses, interaction_telemetry, interaction_started)?
        } else {
            json!({
                "status": "not-measured",
                "reason": "catalog-only-leg",
            })
        };
        let resource_profile = catalog_telemetry_resource_summary(&telemetry);
        Ok(json!({
        "launcher_pid": final_status.get("pid"),
        "timing": {
            "first_visible_ms": first_visible_ms,
            "complete_ms": complete_ms,
            "runtime_start_to_catalog_complete_ms": runtime_start_to_catalog_complete_ms,
        },
        "catalog": catalog,
        "phase_evidence": phase_evidence,
        "resource_profile": resource_profile,
        "updater_index": updater_index_evidence,
        "ui": ui,
        }))
    })();
    let automation_cleanup =
        finish_catalog_benchmark_automation(config, automation_nonce.as_deref());
    match (run_result, automation_cleanup) {
        (Ok(result), Ok(())) => Ok(result),
        (Err(run), Ok(())) => Err(run),
        (Ok(_), Err(cleanup)) => Err(cleanup),
        (Err(run), Err(cleanup)) => {
            Err(format!("{run}; catalog automation cleanup failed: {cleanup}").into())
        }
    }
}

fn finish_catalog_benchmark_automation(
    config: &NativeDeviceConfig,
    nonce: Option<&str>,
) -> Result<()> {
    let Some(nonce) = nonce else {
        return Ok(());
    };
    let release = launcher_automation::send_action(config, nonce, &AutomationAction::ReleaseAll);
    let end = launcher_automation::end(config, nonce).map(|_| ());
    match (release, end) {
        (Ok(_), Ok(())) => Ok(()),
        (Err(release), Ok(())) => Err(format!("input release failed: {release}").into()),
        (Ok(_), Err(end)) => Err(format!("automation end failed: {end}").into()),
        (Err(release), Err(end)) => {
            Err(format!("input release failed: {release}; automation end failed: {end}").into())
        }
    }
}

fn catalog_benchmark_presented_home_arcade(log: &str) -> bool {
    let mut selected_arcade = false;
    let mut presented_home = false;
    for line in log.lines() {
        if line.contains("\tlauncher_home_selected_index_applied\t")
            && line
                .split_ascii_whitespace()
                .any(|field| field == "selected=0")
        {
            selected_arcade = true;
        }
        if line.contains("\tlauncher_first_frame_presented\t") && line.contains("screen=home") {
            presented_home = true;
        }
    }
    selected_arcade && presented_home
}

fn catalog_logical_fingerprint(catalog: &Value) -> Result<String> {
    let logical = catalog_exact_identity(catalog)?;
    let encoded = serde_json::to_vec(&logical)?;
    Ok(encode_hex(&Sha256::digest(encoded)))
}

fn catalog_exact_identity(catalog: &Value) -> Result<Value> {
    let mut identity = serde_json::Map::new();
    for field in [
        "identity_sha256",
        "ordering_sha256",
        "launch_sha256",
        "search_sha256",
    ] {
        let digest = catalog
            .get(field)
            .and_then(Value::as_str)
            .filter(|digest| digest.len() == 64)
            .ok_or_else(|| format!("catalog identity has no valid {field}"))?;
        identity.insert(field.into(), json!(digest));
    }
    Ok(Value::Object(identity))
}

fn catalog_artifact_set_valid(catalog: &Value) -> bool {
    catalog
        .get("artifact_set_sha256")
        .and_then(Value::as_str)
        .is_some_and(|digest| digest.len() == 64)
        && catalog
            .get("artifacts")
            .and_then(Value::as_array)
            .is_some_and(|artifacts| {
                !artifacts.is_empty()
                    && artifacts.iter().all(|artifact| {
                        artifact
                            .get("sha256")
                            .and_then(Value::as_str)
                            .is_some_and(|digest| digest.len() == 64)
                            && artifact.get("bytes").and_then(Value::as_u64).is_some()
                    })
            })
}

fn catalog_phase_evidence(log: &str) -> Value {
    const RECORDS: [&str; 23] = [
        "startup_timing",
        "catalog_scan_attribution_tsv",
        "catalog_scan_handoff_tsv",
        "catalog_target_handoff_tsv",
        "catalog_system_finality_tsv",
        "catalog_contributor_closure_tsv",
        "catalog_target_checkpoint_io_tsv",
        "catalog_shard_staging_tsv",
        "library_scan_timing",
        "catalog_v3_projection_phases_tsv",
        "catalog_v3_reconciliation_tsv",
        "catalog_v3_persist_phases_tsv",
        "catalog_v3_shard_phase_tsv",
        "catalog_memory_tsv",
        "catalog_search_build_tsv",
        "fast_catalog_source_phase_tsv",
        "fast_catalog_capture_tsv",
        "fast_catalog_capture_source_tsv",
        "fast_catalog_refresh_publish_tsv",
        "catalog_artifact_copy_tsv",
        "catalog_shard_allocator_trim_tsv",
        "fast_catalog_generic_phase_tsv",
        "fast_catalog_generic_inventory_tsv",
    ];
    let mut records = Vec::new();
    for line in log.lines() {
        let Some((marker, offset)) = RECORDS
            .iter()
            .find_map(|marker| line.find(marker).map(|offset| (*marker, offset)))
        else {
            continue;
        };
        let fields = line[offset..].split('\t').collect::<Vec<_>>();
        let mut metrics = serde_json::Map::new();
        let mut name = None;
        let mut observed_at_us: Option<u64> = None;
        for (index, field) in fields.iter().enumerate().skip(1) {
            if marker == "startup_timing" && index == 1 {
                name = Some((*field).to_owned());
                continue;
            }
            if marker == "startup_timing" && index == 2 {
                observed_at_us = field
                    .strip_suffix("us")
                    .and_then(|value| value.parse().ok());
                continue;
            }
            for token in field.split_ascii_whitespace() {
                if let Some((key, value)) = token.split_once('=') {
                    metrics.insert(key.to_owned(), catalog_phase_metric(value));
                }
            }
            if name.is_none() && !field.contains('=') {
                name = Some((*field).to_owned());
            }
        }
        records.push(json!({
            "record": marker,
            "name": name,
            "observed_at_us": observed_at_us,
            "metrics": metrics,
        }));
    }
    let has = |record: &str, name: Option<&str>| {
        records.iter().any(|value| {
            value.get("record").and_then(Value::as_str) == Some(record)
                && name.is_none_or(|name| value.get("name").and_then(Value::as_str) == Some(name))
        })
    };
    let post_scan_unchanged = records.iter().any(|value| {
        value.get("record").and_then(Value::as_str) == Some("startup_timing")
            && value.get("name").and_then(Value::as_str) == Some("builder_post_scan_unchanged")
            && value.pointer("/metrics/status").and_then(Value::as_str) == Some("unchanged")
    });
    let required = json!({
        "scan_complete": has("startup_timing", Some("library_scan_complete")),
        "builder_terminal": post_scan_unchanged
            || has("startup_timing", Some("builder_persisted")),
        "scan_attribution": has("catalog_scan_attribution_tsv", None),
        "scan_handoff": has("catalog_scan_handoff_tsv", None),
        "target_handoff": has("catalog_target_handoff_tsv", None),
        "system_finality": has("catalog_system_finality_tsv", None),
        "checkpoint": has("catalog_target_checkpoint_io_tsv", None),
        "shard_staging": post_scan_unchanged || has("catalog_shard_staging_tsv", None),
        "projection": post_scan_unchanged || has("catalog_v3_projection_phases_tsv", None),
        "reconciliation": post_scan_unchanged || has("catalog_v3_reconciliation_tsv", None),
        "persist": post_scan_unchanged || has("catalog_v3_persist_phases_tsv", None),
        "generic_discovery": post_scan_unchanged
            || has("fast_catalog_generic_phase_tsv", None),
    });
    let complete = required
        .as_object()
        .is_some_and(|required| required.values().all(|value| value == &Value::Bool(true)));
    json!({
        "schema": "mister-magik-catalog-phase-evidence-v4",
        "complete": complete,
        "completion_mode": if post_scan_unchanged {
            "post-scan-unchanged"
        } else {
            "persisted"
        },
        "required": required,
        "records": records,
    })
}

fn catalog_phase_metric(value: &str) -> Value {
    let value = value.trim_end_matches(',');
    value
        .parse::<u64>()
        .map(Value::from)
        .unwrap_or_else(|_| Value::String(value.to_owned()))
}

fn catalog_updater_index_evidence(log: &str) -> Option<Value> {
    const PREFIX: &str = "library_scan_timing\tarcade_mra_prefetch\t";
    log.lines().rev().find_map(|line| {
        let offset = line.find(PREFIX)?;
        let mut fields = line[offset..].split('\t');
        (fields.next()? == "library_scan_timing").then_some(())?;
        (fields.next()? == "arcade_mra_prefetch").then_some(())?;
        let prefetch_us = fields.next()?.parse::<u64>().ok()?;
        let mut metrics = serde_json::Map::new();
        for token in fields.flat_map(str::split_ascii_whitespace) {
            if let Some((key, value)) = token.split_once('=') {
                metrics.insert(key.to_owned(), catalog_phase_metric(value));
            }
        }
        Some(json!({
            "schema": "mister-magik-arcade-updater-index-evidence-v1",
            "prefetch_us": prefetch_us,
            "status": metrics.get("index_status"),
            "path": metrics.get("index_path"),
            "error": metrics.get("index_error"),
            "rows": metrics.get("index_rows"),
            "file_sha256": metrics.get("index_file_sha256"),
            "hits": metrics.get("index_hits"),
            "misses": metrics.get("index_misses"),
            "fallback_reads": metrics.get("fallback_reads"),
            "files": metrics.get("files"),
            "index_load_us": metrics.get("index_load_us"),
        }))
    })
}

fn validate_catalog_updater_index_evidence(evidence: &Value) -> Result<()> {
    let status = evidence
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("missing-evidence");
    if status != "loaded" {
        let path = evidence
            .get("path")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        let reason = evidence
            .get("error")
            .and_then(Value::as_str)
            .unwrap_or("unknown");
        return Err(format!(
            "whole-card catalog qualification requires the active updater index: status={status} path={path} reason={reason}"
        )
        .into());
    }
    let rows = evidence.get("rows").and_then(Value::as_u64).unwrap_or(0);
    let files = evidence.get("files").and_then(Value::as_u64).unwrap_or(0);
    let hits = evidence.get("hits").and_then(Value::as_u64).unwrap_or(0);
    let file_sha256 = evidence
        .get("file_sha256")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if rows == 0 || file_sha256.len() != 64 {
        return Err(
            "whole-card catalog qualification has incomplete updater-index identity".into(),
        );
    }
    if files > 0 && hits == 0 {
        return Err(format!(
            "whole-card catalog qualification matched no installed MRAs against {rows} updater-index rows"
        )
        .into());
    }
    Ok(())
}

fn catalog_build_rebuild_ui_summary(
    statuses: &[Value],
    telemetry: &[Value],
    interaction_required: bool,
) -> Result<Value> {
    let final_status = statuses.last().cloned().unwrap_or(Value::Null);
    let physical_refresh = catalog_build_rebuild_physical_refresh(telemetry)?;
    let repeated_vblanks = physical_refresh
        .get("repeated_vblank_delta")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX);
    let first_latch_drops = statuses
        .first()
        .and_then(|status| status.get("latch_drop_count"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let latch_drops = final_status
        .get("latch_drop_count")
        .and_then(Value::as_u64)
        .unwrap_or(u64::MAX)
        .saturating_sub(first_latch_drops);
    let selections = statuses
        .iter()
        .filter_map(|status| status.get("arcade_selected").and_then(Value::as_u64))
        .collect::<BTreeSet<_>>();
    let qualified = !interaction_required
        || (repeated_vblanks == 0
            && physical_refresh
                .get("ownership_loss_delta")
                .and_then(Value::as_u64)
                == Some(0)
            && latch_drops == 0
            && selections.len() >= 2);
    Ok(json!({
        "applicable": interaction_required,
        "qualified": qualified,
        "physical_refresh": physical_refresh,
        "latch_drops": latch_drops,
        "distinct_arcade_selections": selections.len(),
        "status_samples": statuses.len(),
        "frame_budget": final_status.get("frame_budget").cloned().unwrap_or(Value::Null),
    }))
}

fn catalog_build_rebuild_physical_refresh(telemetry: &[Value]) -> Result<Value> {
    let snapshots = telemetry
        .iter()
        .filter_map(parse_host_presentation_snapshot)
        .filter(|snapshot| {
            snapshot.magik_ownership
                && !snapshot.pending
                && snapshot.owned_vblank_count
                    == snapshot
                        .presented_vblank_count
                        .wrapping_add(snapshot.repeated_vblank_count)
        })
        .collect::<Vec<_>>();
    let start = snapshots
        .first()
        .copied()
        .ok_or("catalog benchmark has no initial settled FPGA presentation snapshot")?;
    let end = snapshots
        .last()
        .copied()
        .ok_or("catalog benchmark has no final settled FPGA presentation snapshot")?;
    let elapsed_us = end
        .captured_monotonic_us
        .checked_sub(start.captured_monotonic_us)
        .filter(|elapsed| *elapsed > 0)
        .ok_or("catalog benchmark has insufficient FPGA snapshot separation")?;
    let mut refresh_periods = telemetry
        .iter()
        .filter_map(|sample| {
            sample
                .pointer("/launcher/frame_budget/budget_us")
                .and_then(Value::as_u64)
        })
        .filter(|period| *period > 0)
        .collect::<Vec<_>>();
    refresh_periods.sort_unstable();
    let refresh_period_us = median_u64(&refresh_periods)
        .ok_or("catalog benchmark telemetry has no physical refresh period")?;
    let delta = mister_magik_latch_contract::validate_presentation_telemetry_window(
        start,
        end,
        elapsed_us,
        refresh_period_us,
    )
    .map_err(|error| format!("catalog benchmark FPGA presentation window is invalid: {error}"))?;
    Ok(json!({
        "schema": "mister-magik-frame-evidence-v6",
        "source": "fpga-owned-vblank-telemetry",
        "available": true,
        "refresh_period_us": refresh_period_us,
        "elapsed_us": delta.elapsed_us,
        "owned_vblank_delta": delta.owned_vblank_delta,
        "presented_vblank_delta": delta.presented_vblank_delta,
        "repeated_vblank_delta": delta.repeated_vblank_delta,
        "ownership_loss_delta": delta.ownership_loss_delta,
        "dropped_frames": delta.repeated_vblank_delta,
        "endpoints_settled": !start.pending && !end.pending,
    }))
}

fn catalog_system_games(catalog: &Value, system_id: &str) -> Result<u64> {
    catalog
        .get("systems")
        .and_then(Value::as_array)
        .and_then(|systems| {
            systems
                .iter()
                .find(|system| system.get("system").and_then(Value::as_str) == Some(system_id))
        })
        .and_then(|system| system.get("games"))
        .and_then(Value::as_u64)
        .ok_or_else(|| format!("catalog has no {system_id} game count").into())
}

fn catalog_system_ids(catalog: &Value) -> Result<BTreeSet<String>> {
    catalog
        .get("systems")
        .and_then(Value::as_array)
        .map(|systems| {
            systems
                .iter()
                .filter_map(|system| {
                    system
                        .get("system")
                        .and_then(Value::as_str)
                        .map(str::to_string)
                })
                .collect()
        })
        .ok_or_else(|| "catalog has no system list".into())
}

fn catalog_system_game_counts_except(
    catalog: &Value,
    excluded_system: &str,
) -> Result<BTreeMap<String, u64>> {
    catalog
        .get("systems")
        .and_then(Value::as_array)
        .map(|systems| {
            systems
                .iter()
                .filter_map(|system| {
                    let id = system.get("system").and_then(Value::as_str)?;
                    if id == excluded_system {
                        return None;
                    }
                    Some((
                        id.to_string(),
                        system.get("games").and_then(Value::as_u64).unwrap_or(0),
                    ))
                })
                .collect()
        })
        .ok_or_else(|| "catalog has no system list".into())
}

fn catalog_artifact_identity_except(
    catalog: &Value,
    excluded_system: &str,
) -> Result<BTreeMap<String, (String, u64, String)>> {
    catalog
        .get("artifacts")
        .and_then(Value::as_array)
        .map(|artifacts| {
            artifacts
                .iter()
                .filter_map(|artifact| {
                    if artifact.get("system").and_then(Value::as_str) == Some(excluded_system) {
                        return None;
                    }
                    let path = artifact.get("path").and_then(Value::as_str)?;
                    let kind = artifact.get("kind").and_then(Value::as_str)?;
                    let bytes = artifact.get("bytes").and_then(Value::as_u64)?;
                    let sha256 = artifact.get("sha256").and_then(Value::as_str)?;
                    Some((
                        path.to_string(),
                        (kind.to_string(), bytes, sha256.to_string()),
                    ))
                })
                .collect()
        })
        .ok_or_else(|| "catalog has no artifact list".into())
}

