    #[test]
    fn launcher_response_pulse_gate_requires_exact_confirmed_pairs_and_dwell() {
        let trace = json!({
            "feedback_records": [
                {"phase": "visible", "event_id": 1, "surface": "settings", "item": "orientation", "confirmed_frame": 10},
                {"phase": "visible", "event_id": 2, "surface": "settings", "item": "screensaver", "confirmed_frame": 13},
                {"phase": "hidden", "event_id": 1, "surface": "settings", "item": "orientation", "confirmed_frame": 15, "dwell_us": 83_000},
                {"phase": "hidden", "event_id": 2, "surface": "settings", "item": "screensaver", "confirmed_frame": 18, "dwell_us": 84_000},
            ],
        });
        let summary =
            summarize_launcher_response_pulses(&trace, "settings", &["orientation", "screensaver"])
                .unwrap();
        assert_eq!(summary["status"], "passed");

        let cancelled = json!({
            "feedback_records": [
                {"phase": "visible", "event_id": 1, "surface": "settings", "item": "orientation", "confirmed_frame": 10},
                {"phase": "hidden", "event_id": 1, "surface": "settings", "item": "orientation", "confirmed_frame": 15, "dwell_us": 83_000},
                {"phase": "cancelled", "event_id": 2, "surface": "settings", "item": "screensaver", "confirmed_frame": 16},
            ],
        });
        let cancelled_summary = summarize_launcher_response_pulses(
            &cancelled,
            "settings",
            &["orientation", "screensaver"],
        )
        .unwrap();
        assert_eq!(cancelled_summary["status"], "passed");
        assert_eq!(cancelled_summary["cancelled_count"], 1);

        let mismatched = json!({
            "feedback_records": [
                {"phase": "visible", "event_id": 1, "surface": "settings", "item": "unexpected", "confirmed_frame": 10},
                {"phase": "hidden", "event_id": 1, "surface": "settings", "item": "unexpected", "confirmed_frame": 15, "dwell_us": 83_000},
            ],
        });
        let mismatched_summary =
            summarize_launcher_response_pulses(&mismatched, "settings", &["orientation"]).unwrap();
        assert_eq!(mismatched_summary["status"], "failed");
        assert_eq!(mismatched_summary["visible_items"], json!(["unexpected"]));

        let mut short = trace;
        short["feedback_records"][3]["dwell_us"] = json!(79_999);
        assert_eq!(
            summarize_launcher_response_pulses(
                &short,
                "settings",
                &["orientation", "screensaver"],
            )
            .unwrap()["status"],
            "failed"
        );
    }

