    fn settings_navigation_qualification_fixture() -> (Vec<Value>, Value) {
        let route = [
            ("home-settings", "forward", "home", "settings"),
            ("settings-about", "forward", "settings", "about"),
            ("about-info", "forward", "about", "info"),
            ("about-info", "reverse", "info", "about"),
            ("settings-about", "reverse", "about", "settings"),
            ("home-settings", "reverse", "settings", "home"),
        ];
        let mut telemetry = Vec::new();
        let mut records = Vec::new();
        for (index, (orientation, (route, direction, source, destination))) in
            ["normal", "monitor-counterclockwise"]
                .into_iter()
                .flat_map(|orientation| route.into_iter().map(move |leg| (orientation, leg)))
                .enumerate()
        {
            let base_us = index as u64 * 500_000 + 1_000_000;
            let presented = index as u64 * 30;
            telemetry.push(json!({
                "presentation": {
                    "schema": "mister-magik-presentation-telemetry-snapshot-v1",
                    "source": "fpga-owned-vblank-telemetry",
                    "available": true,
                    "captured_monotonic_us": base_us,
                    "owned_vblank_count": presented,
                    "presented_vblank_count": presented,
                    "repeated_vblank_count": 0,
                    "ownership_loss_count": 0,
                    "magik_ownership": true,
                    "pending": false,
                },
                "launcher": {"frame_budget": {"recent_frames": []}},
            }));
            let sequence = index as u64 * 20 + 1;
            let frame = |id: u64, completion_us: u64, sequence: u64| {
                json!({
                    "frame": id,
                    "settings_navigation_benchmark_leg": index + 1,
                    "navigation_transition_route": route,
                    "navigation_transition_direction": direction,
                    "navigation_transition_renderer": "settings-page",
                    "navigation_transition_orientation": orientation,
                    "navigation_transition_us": 5_000,
                    "navigation_transition_overlay_us": 1_000,
                    "navigation_snapshot_locked": true,
                    "navigation_slint_render_called": false,
                    "completion_monotonic_us": completion_us,
                    "main_present_status": "ok",
                    "main_present_copy_path": "identity-full",
                    "main_present_sequence": sequence,
                    "main_present_post_active_sequence": if id.is_multiple_of(2) { 0 } else { sequence },
                    "main_present_post_pending_sequence": if id.is_multiple_of(2) { sequence } else { 0 },
                    "main_present_post_pending": id.is_multiple_of(2),
                    "main_present_active_sequence": sequence,
                    "main_present_request_us": 800,
                    "main_present_completion_poll_wall_us": 500,
                    "main_present_drop_count": 0,
                    "frame_production_class": "synchronous-animation",
                    "frame_production_sequence": sequence,
                    "frame_production_render_start_phase_us": 4_000,
                    "frame_production_render_wall_us": 5_000,
                    "frame_production_ready_age_us": 100,
                    "frame_start_phase_us": 3_000,
                    "present_phase_us": 10_000,
                    "vsync_source": "vsync",
                    "vsync_stale_hits": 0,
                    "vsync_miss_streak": 0,
                    "wall_us": 15_000,
                    "vsync_us": 5_000,
                    "process_cpu_us": 4_000,
                    "status_worker_active": false,
                    "status_enqueue_us": 0,
                })
            };
            telemetry.push(json!({
                "presentation": {
                    "schema": "mister-magik-presentation-telemetry-snapshot-v1",
                    "source": "fpga-owned-vblank-telemetry",
                    "available": true,
                    "captured_monotonic_us": base_us + 250_000,
                    "owned_vblank_count": presented + 15,
                    "presented_vblank_count": presented + 15,
                    "repeated_vblank_count": 0,
                    "ownership_loss_count": 0,
                    "magik_ownership": true,
                    "pending": false,
                },
                "launcher": {"frame_budget": {"recent_frames": [
                    frame(index as u64 * 10 + 1, base_us + 100_000, sequence),
                    frame(index as u64 * 10 + 2, base_us + 116_667, sequence + 1),
                ]}},
            }));
            records.push(json!({
                "leg": index + 1,
                "orientation": orientation,
                "route": route,
                "renderer": "settings-page",
                "direction": direction,
                "source": source,
                "destination": destination,
                "start_frame": index * 10 + 1,
                "rendered_endpoint_frame": index * 10 + 2,
                "presented_endpoint_frame": index * 10 + 3,
                "presented_sequence": sequence + 2,
                "presentation_window": {
                    "schema": "mister-magik-settings-navigation-presentation-window-v1",
                    "source": "fpga-owned-vblank-telemetry",
                    "start": {
                        "owned_vblank_count": presented,
                        "presented_vblank_count": presented,
                        "repeated_vblank_count": 0,
                        "ownership_loss_count": 0,
                        "magik_ownership": true,
                        "pending": false,
                    },
                    "end": {
                        "owned_vblank_count": presented + 18,
                        "presented_vblank_count": presented + 18,
                        "repeated_vblank_count": 0,
                        "ownership_loss_count": 0,
                        "magik_ownership": true,
                        "pending": false,
                    },
                    "elapsed_us": 300_006,
                    "error": null,
                },
            }));
        }
        (
            telemetry,
            json!({
                "schema": "mister-magik-settings-navigation-transition-v4",
                "state": "complete",
                "orientations": ["normal", "monitor-counterclockwise"],
                "route": ["home", "settings", "about", "info", "about", "settings", "home", "settings", "about", "info", "about", "settings", "home"],
                "records": records,
            }),
        )
    }

    #[test]
    fn settings_navigation_qualification_applies_every_leg_gate() {
        let (telemetry, completion) = settings_navigation_qualification_fixture();
        let summary = summarize_settings_navigation_qualification(&telemetry, completion, None)
            .expect("fixture should qualify");
        assert_eq!(summary["status"], "passed");
        assert_eq!(summary["cadence_authoritative"], true);
        assert_eq!(
            summary["legs"][0]["protocol_v5"]["boundary"],
            "transition-start-to-confirmed-endpoint"
        );
        assert_eq!(summary["legs"][0]["synchronous_frame_production"], true);
        assert_eq!(
            summary["legs"][0]["phase_timing"]["render_wall_us"]["median_us"],
            5_000
        );
        assert_eq!(
            summary["legs"][0]["post_receipt"]["already_active_frames"],
            1
        );
        assert_eq!(summary["legs"][0]["post_receipt"]["pending_frames"], 1);
        assert_eq!(
            summary["legs"].as_array().unwrap().len(),
            SETTINGS_NAVIGATION_LEGS
        );
        assert!(
            summary["legs"]
                .as_array()
                .unwrap()
                .iter()
                .all(|leg| leg["passed"] == true)
        );
    }

    #[test]
    fn settings_navigation_qualification_rejects_route_and_policy_failures() {
        let (telemetry, mut completion) = settings_navigation_qualification_fixture();
        completion["records"].as_array_mut().unwrap().pop();
        assert!(summarize_settings_navigation_qualification(&telemetry, completion, None).is_err());

        let (mut telemetry, completion) = settings_navigation_qualification_fixture();
        telemetry[1]["launcher"]["frame_budget"]["recent_frames"][0]["navigation_snapshot_locked"] =
            json!(false);
        let summary =
            summarize_settings_navigation_qualification(&telemetry, completion, None).unwrap();
        assert_eq!(summary["status"], "failed");
        assert_eq!(summary["legs"][0]["snapshot_lock_violations"], 1);
    }

    #[test]
    fn settings_navigation_qualification_records_insufficient_frame_failure() {
        let (mut telemetry, completion) = settings_navigation_qualification_fixture();
        telemetry[1]["launcher"]["frame_budget"]["recent_frames"]
            .as_array_mut()
            .unwrap()
            .pop();
        let summary =
            summarize_settings_navigation_qualification(&telemetry, completion, None).unwrap();
        assert_eq!(summary["status"], "failed");
        assert_eq!(summary["legs"][0]["frames"], 1);
        assert_eq!(
            summary["legs"][0]["failure"],
            "insufficient-frame-telemetry"
        );
    }

    #[test]
    fn settings_navigation_qualification_requires_exact_presentation_windows() {
        let (telemetry, mut completion) = settings_navigation_qualification_fixture();
        completion["records"][0]
            .as_object_mut()
            .unwrap()
            .remove("presentation_window");
        assert!(summarize_settings_navigation_qualification(&telemetry, completion, None).is_err());

        let (telemetry, mut completion) = settings_navigation_qualification_fixture();
        completion["schema"] = json!("mister-magik-settings-navigation-transition-v3");
        assert!(summarize_settings_navigation_qualification(&telemetry, completion, None).is_err());
    }

    #[test]
    fn settings_navigation_uses_exact_repeat_counts_over_sampled_fps() {
        let (telemetry, mut completion) = settings_navigation_qualification_fixture();
        let window = &mut completion["records"][11]["presentation_window"];
        window["end"]["owned_vblank_count"] = json!(349);
        window["end"]["presented_vblank_count"] = json!(349);
        window["elapsed_us"] = json!(318_582);

        let summary = summarize_settings_navigation_qualification(&telemetry, completion, None)
            .expect("exact zero-repeat window should qualify");
        assert_eq!(summary["legs"][11]["physical_dropped_frames"], 0);
        assert!(
            summary["legs"][11]["protocol_v5"]["physical_fps"]
                .as_f64()
                .expect("physical fps should be numeric")
                < 59.9
        );
        assert_eq!(summary["legs"][11]["passed"], true);
    }

    #[test]
    fn arcade_velocity_scroll_accepts_p50_and_p60_with_route_thresholds() {
        assert_eq!(
            arcade_velocity_scroll_minimum_fps("crt-240p60").unwrap(),
            59.9
        );
        assert_eq!(
            arcade_velocity_scroll_minimum_fps("crt-288p50").unwrap(),
            49.9
        );
        assert_eq!(
            arcade_velocity_scroll_minimum_fps("hdmi-1920x1080p60").unwrap(),
            59.9
        );
        assert!(arcade_velocity_scroll_minimum_fps("custom").is_err());
        assert_eq!(
            arcade_velocity_scroll_fps_failure(49.9),
            "physical-fps-below-49.9"
        );
        assert_eq!(
            arcade_velocity_scroll_fps_failure(59.9),
            "physical-fps-below-59.9"
        );
    }

    #[test]
    fn arcade_velocity_scroll_names_effective_routes_from_measured_state() {
        assert_eq!(
            arcade_velocity_scroll_effective_route("hdmi-1280x720p60", "Normal"),
            "hdmi-landscape"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route(
                "hdmi-1280x720p60",
                "Monitor left (counterclockwise)"
            ),
            "hdmi-portrait-left"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route("hdmi-1280x720p60", "Monitor right (clockwise)"),
            "hdmi-portrait-right"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route("hdmi-1920x1080p60", "Normal"),
            "hdmi1080-landscape"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route(
                "hdmi-1920x1080p60",
                "Monitor left (counterclockwise)"
            ),
            "hdmi1080-portrait-left"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route("crt-240p60", "Monitor left (counterclockwise)"),
            "crt240-portrait-left"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route("crt-240p60", "Monitor right (clockwise)"),
            "crt240-portrait-right"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route("crt-288p50", "Monitor left (counterclockwise)"),
            "crt288-portrait-left"
        );
        assert_eq!(
            arcade_velocity_scroll_effective_route("crt-288p50", "Monitor right (clockwise)"),
            "crt288-portrait-right"
        );
    }

    #[test]
    fn arcade_velocity_scroll_applies_only_low_resolution_crt_work_budgets() {
        assert_eq!(
            arcade_velocity_scroll_foreground_p99_limit_us("crt-240p60"),
            Some(13_300)
        );
        assert_eq!(
            arcade_velocity_scroll_foreground_p99_limit_us("crt-288p50"),
            Some(15_900)
        );
        assert_eq!(
            arcade_velocity_scroll_foreground_p99_limit_us("hdmi-1920x1080p60"),
            None
        );
        assert_eq!(percentile_summary(&[1, 2, 3, 4, 5])["max"], 5);
    }

    #[test]
    fn arcade_velocity_scroll_reports_all_screen_orientations() {
        for orientation in [
            "Normal",
            "Monitor right (clockwise)",
            "Monitor left (counterclockwise)",
        ] {
            let route = json!({
                "arcade_entered": { "semantic": { "screen_orientation": orientation } },
                "settled_arcade": { "semantic": { "screen_orientation": orientation } },
            });
            assert_eq!(
                arcade_velocity_scroll_orientations(&route).unwrap(),
                (orientation, orientation)
            );
        }
    }

    #[test]
    fn arcade_velocity_scroll_exposes_orientation_changes() {
        let route = json!({
            "arcade_entered": { "semantic": { "screen_orientation": "Normal" } },
            "settled_arcade": {
                "semantic": { "screen_orientation": "Monitor right (clockwise)" }
            },
        });
        assert_eq!(
            arcade_velocity_scroll_orientations(&route).unwrap(),
            ("Normal", "Monitor right (clockwise)")
        );
    }

    #[test]
    fn arcade_velocity_scroll_requires_an_authoritative_terminal_scanout() {
        let authoritative = json!({
            "terminal_checkpoint": {
                "capture_source": "fpga-latched-scanout-slots",
                "capture": { "authoritative_scanout": true },
            },
        });
        assert!(arcade_velocity_scroll_terminal_is_authoritative(
            &authoritative
        ));

        let mut framebuffer_only = authoritative.clone();
        framebuffer_only["terminal_checkpoint"]["capture_source"] = json!("framebuffer-memory");
        assert!(!arcade_velocity_scroll_terminal_is_authoritative(
            &framebuffer_only
        ));

        let mut unconfirmed = authoritative;
        unconfirmed["terminal_checkpoint"]["capture"]["authoritative_scanout"] = json!(false);
        assert!(!arcade_velocity_scroll_terminal_is_authoritative(
            &unconfirmed
        ));
    }

    #[test]
    fn preview_work_attribution_counts_only_overlapping_duplicate_misses() {
        let trace = concat!(
            "preview_work_tsv\tbegin\t1\tprefetch\t100\t5\t/a.mmlz4b\tgame\thybrid-320x320\n",
            "preview_work_tsv\tbegin\t2\tselected\t110\t2\t/a.mmlz4b\tgame\thybrid-320x320\n",
            "preview_work_tsv\tend\t1\tprefetch\t200\t0\t20\t30\t25\t4\t3\t0\tindex_pread\n",
            "preview_work_tsv\tend\t2\tselected\t210\t0\t21\t31\t26\t5\t4\t0\tindex_pread\n",
            "preview_work_tsv\tbegin\t3\tselected\t220\t1\t/a.mmlz4b\tgame\thybrid-320x320\n",
            "preview_work_tsv\tend\t3\tselected\t225\t1\t0\t0\t0\t0\t0\t0\tdecoded_cache\n",
            "preview_work_tsv\tsidecar_probe\tmissing\t/a.mmlz4b\n",
            "preview_work_tsv\tsidecar_probe\tmissing\t/a.mmlz4b\n",
        );
        let summary = parse_preview_work_attribution(trace).unwrap();
        assert_eq!(summary["requests"], 3);
        assert_eq!(summary["simultaneous_selected_prefetch_requests"], 2);
        assert_eq!(summary["duplicate_decodes"], 1);
        assert_eq!(summary["duplicate_reads"], 1);
        assert_eq!(summary["repeated_missing_sidecar_probes"], 1);
        assert_eq!(summary["cache_hits"], 1);
    }

